/**
 * Date-range handling for /admin/insights: `?from=yyyy-mm-dd&to=yyyy-mm-dd`
 * (UTC days, inclusive) or `?preset=7d|30d|90d|365d|mtd|qtd|ytd`, plus the
 * equal-length previous period for compare-to-previous. Pure.
 */
export type InsightsRange = {
  from: Date; // inclusive, UTC midnight
  to: Date; // exclusive (UTC midnight of the day after the last day)
  days: number;
  prevFrom: Date;
  prevTo: Date;
  label: string;
  preset: string | null;
  fromStr: string;
  toStr: string;
};

export const PRESETS: { key: string; label: string }[] = [
  { key: "7d", label: "7 days" },
  { key: "30d", label: "30 days" },
  { key: "90d", label: "90 days" },
  { key: "365d", label: "12 months" },
  { key: "mtd", label: "Month to date" },
  { key: "ytd", label: "Year to date" },
];

const DAY = 86_400_000;
const YMD = /^\d{4}-\d{2}-\d{2}$/;

function utcMidnight(d: Date): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

function ymd(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function parseRange(sp: { from?: string; to?: string; preset?: string }, now: Date = new Date()): InsightsRange {
  const today = utcMidnight(now);
  const tomorrow = new Date(today.getTime() + DAY);
  let from: Date | null = null;
  let to: Date | null = null;
  let preset: string | null = null;

  if (sp.from && YMD.test(sp.from)) {
    const f = new Date(`${sp.from}T00:00:00Z`);
    const t = sp.to && YMD.test(sp.to) ? new Date(new Date(`${sp.to}T00:00:00Z`).getTime() + DAY) : tomorrow;
    if (!Number.isNaN(f.getTime()) && !Number.isNaN(t.getTime()) && t > f) {
      from = f;
      to = t > tomorrow ? tomorrow : t;
    }
  }
  if (!from || !to) {
    preset = PRESETS.some((p) => p.key === sp.preset) ? (sp.preset as string) : "30d";
    to = tomorrow;
    switch (preset) {
      case "mtd":
        from = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
        break;
      case "ytd":
        from = new Date(Date.UTC(today.getUTCFullYear(), 0, 1));
        break;
      default: {
        const n = Number(preset.replace("d", ""));
        from = new Date(tomorrow.getTime() - n * DAY);
      }
    }
  }
  // Cap at 3 years so a typo can't ask for a 50-year scan.
  if (to.getTime() - from.getTime() > 3 * 366 * DAY) from = new Date(to.getTime() - 3 * 366 * DAY);
  const days = Math.max(1, Math.round((to.getTime() - from.getTime()) / DAY));
  const prevTo = from;
  const prevFrom = new Date(from.getTime() - days * DAY);
  const lastDay = new Date(to.getTime() - DAY);
  return {
    from,
    to,
    days,
    prevFrom,
    prevTo,
    preset,
    fromStr: ymd(from),
    toStr: ymd(lastDay),
    label: preset ? (PRESETS.find((p) => p.key === preset)?.label ?? preset) : `${ymd(from)} → ${ymd(lastDay)}`,
  };
}

/** Day buckets [from, to) as UTC midnights. */
export function dayBuckets(from: Date, to: Date): Date[] {
  const out: Date[] = [];
  for (let t = utcMidnight(from).getTime(); t < to.getTime(); t += DAY) out.push(new Date(t));
  return out;
}

/** Bucket granularity that keeps a chart readable: day ≤ 62d, week ≤ 1y, else month. */
export function granularity(days: number): "day" | "week" | "month" {
  return days <= 62 ? "day" : days <= 366 ? "week" : "month";
}

export function bucketKey(d: Date, g: "day" | "week" | "month"): string {
  if (g === "day") return ymd(d);
  if (g === "month") return ymd(d).slice(0, 7);
  // ISO-ish week start (Monday, UTC)
  const day = (d.getUTCDay() + 6) % 7;
  return ymd(new Date(utcMidnight(d).getTime() - day * DAY));
}

export function bucketKeys(from: Date, to: Date, g: "day" | "week" | "month"): string[] {
  const keys: string[] = [];
  for (const d of dayBuckets(from, to)) {
    const k = bucketKey(d, g);
    if (keys[keys.length - 1] !== k) keys.push(k);
  }
  return keys;
}
/**
 * Shared building blocks for lib/insights/*: which accounts count, which
 * servers are "live", the price-shape select the MRR formula needs, and the
 * paid-server lifetime model churn/cohorts are built on.
 */
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { withGrantLive } from "@/lib/server-ownership-tags-data";
import { REVENUE_USER_WHERE } from "@/lib/admin-metrics";

/** Server statuses that mean a real machine exists for the customer. */
export const LIVE_STATUSES = ["RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING"] as const;
/** Same, plus DELETING (still counts as "was deployed" for funnels). */
export const DEPLOYED_STATUSES = [...LIVE_STATUSES, "DELETING"] as const;

/** Accounts that count toward business numbers: not staff, not flagged internal/test. */
export const CUSTOMER_WHERE: Prisma.UserWhereInput = { ...REVENUE_USER_WHERE, role: "CUSTOMER" };

/** The exact select `serverMonthlyCents` (lib/admin-metrics.ts) needs. */
export const MRR_SERVER_SELECT = {
  id: true,
  expiresAt: true,
  isFree: true,
  status: true,
  termMonths: true,
  extraDiskGB: true,
  backupTier: true,
  annualDiscountPct: true,
  plan: { select: { name: true, priceCents: true } },
  gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
  dedicatedIp: { select: { id: true } },
  wantsDedicatedIp: true,
  grandfatheredRenewalCents: true,
} as const;

/** One paid-server lifetime: when it started, when it ended (null = still live). */
export type PaidLife = { userId: string; start: Date; end: Date | null };

/**
 * Every paid server lifetime we can reconstruct: live non-free servers (end
 * null) + archived (deleted) servers that ever took money. ServerArchive has
 * no isFree column, so "ever paid" = totalSpentCents > 0 — a free server that
 * was deleted never enters the model. Internal/test accounts excluded.
 */
export async function paidLifetimes(): Promise<PaidLife[]> {
  const [liveRaw, archived, excluded] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { in: [...LIVE_STATUSES] }, user: CUSTOMER_WHERE },
      select: { id: true, expiresAt: true, userId: true, createdAt: true },
    }),
    db.serverArchive.findMany({
      where: { totalSpentCents: { gt: 0 }, userId: { not: null } },
      select: { userId: true, provisionedAt: true, deletedAt: true },
    }),
    db.user.findMany({ where: { NOT: CUSTOMER_WHERE }, select: { id: true } }),
  ]);
  // A live creator grant is not a paid lifetime (churn / LTV / cohorts); once converted it counts.
  const live = (await withGrantLive(liveRaw)).filter((s) => !s.grantLive);
  const skip = new Set(excluded.map((u) => u.id));
  const out: PaidLife[] = live.map((s) => ({ userId: s.userId, start: s.createdAt, end: null }));
  for (const a of archived) {
    if (!a.userId || skip.has(a.userId)) continue;
    out.push({ userId: a.userId, start: a.provisionedAt, end: a.deletedAt });
  }
  return out;
}

/** Users with at least one paid server alive at instant `t`. */
export function payingAt(lives: PaidLife[], t: Date): Set<string> {
  const s = new Set<string>();
  const ts = t.getTime();
  for (const l of lives) {
    if (l.start.getTime() <= ts && (l.end === null || l.end.getTime() > ts)) s.add(l.userId);
  }
  return s;
}

/** First paid-server start per user. */
export function firstPaidStart(lives: PaidLife[]): Map<string, Date> {
  const m = new Map<string, Date>();
  for (const l of lives) {
    const cur = m.get(l.userId);
    if (!cur || l.start < cur) m.set(l.userId, l.start);
  }
  return m;
}

/** A metric that may not have enough data to be honest about. */
export type Maybe<T> = { ok: true; value: T } | { ok: false; reason: string };

export function enough<T>(cond: boolean, value: () => T, reason: string): Maybe<T> {
  return cond ? { ok: true, value: value() } : { ok: false, reason };
}
/**
 * Pure maths + formatting helpers for /admin/insights. No DB, no React — unit
 * tested in test/insights-stats.test.ts.
 */

/** Linear-interpolated percentile (p in 0..100) of an unsorted array; null when empty. */
export function percentile(values: number[], p: number): number | null {
  const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (v.length === 0) return null;
  if (v.length === 1) return v[0];
  const rank = (Math.min(Math.max(p, 0), 100) / 100) * (v.length - 1);
  const lo = Math.floor(rank);
  const hi = Math.ceil(rank);
  return v[lo] + (v[hi] - v[lo]) * (rank - lo);
}

export function mean(values: number[]): number | null {
  const v = values.filter((x) => Number.isFinite(x));
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
}

export function stddev(values: number[]): number | null {
  const m = mean(values);
  if (m == null || values.length < 2) return null;
  const s = values.reduce((a, b) => a + (b - m) ** 2, 0) / (values.length - 1);
  return Math.sqrt(s);
}

/** Least-squares fit y = a + b·x. null with < 2 distinct x values. */
export function linearFit(points: { x: number; y: number }[]): { slope: number; intercept: number; r2: number } | null {
  const n = points.length;
  if (n < 2) return null;
  const mx = points.reduce((s, p) => s + p.x, 0) / n;
  const my = points.reduce((s, p) => s + p.y, 0) / n;
  let sxx = 0;
  let sxy = 0;
  let syy = 0;
  for (const p of points) {
    sxx += (p.x - mx) ** 2;
    sxy += (p.x - mx) * (p.y - my);
    syy += (p.y - my) ** 2;
  }
  if (sxx === 0) return null;
  const slope = sxy / sxx;
  const intercept = my - slope * mx;
  const r2 = syy === 0 ? 1 : (sxy * sxy) / (sxx * syy);
  return { slope, intercept, r2 };
}

/**
 * Days until `current` reaches `capacity` growing at `slopePerDay`. null when
 * not growing (slope <= 0) — "never at this rate", which the UI says honestly
 * instead of inventing a date. 0 when already at/over capacity.
 */
export function daysUntil(current: number, capacity: number, slopePerDay: number): number | null {
  if (capacity <= 0) return null;
  if (current >= capacity) return 0;
  if (!(slopePerDay > 0)) return null;
  return Math.ceil((capacity - current) / slopePerDay);
}

/** Relative change (cur vs prev) as a fraction, null when prev is 0/absent. */
export function relChange(cur: number, prev: number | null | undefined): number | null {
  if (prev == null || prev === 0) return null;
  return (cur - prev) / Math.abs(prev);
}

export function fmtPct(frac: number | null | undefined, digits = 0): string {
  if (frac == null || !Number.isFinite(frac)) return "—";
  return `${(frac * 100).toFixed(digits)}%`;
}

export function fmtDelta(frac: number | null): string | undefined {
  if (frac == null || !Number.isFinite(frac)) return undefined;
  const s = (frac * 100).toFixed(Math.abs(frac) < 0.1 ? 1 : 0);
  return `${frac >= 0 ? "+" : ""}${s}% vs previous period`;
}

export function fmtCents(cents: number | null | undefined): string {
  if (cents == null || !Number.isFinite(cents)) return "—";
  const neg = cents < 0;
  const v = Math.abs(cents) / 100;
  const s = v >= 10_000 ? v.toLocaleString("en-US", { maximumFractionDigits: 0 }) : v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${neg ? "-" : ""}$${s}`;
}

export function fmtDuration(ms: number | null | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return "—";
  const s = ms / 1000;
  if (s < 60) return `${s.toFixed(s < 10 ? 1 : 0)}s`;
  const m = s / 60;
  if (m < 60) return `${m.toFixed(m < 10 ? 1 : 0)}m`;
  const h = m / 60;
  if (h < 48) return `${h.toFixed(h < 10 ? 1 : 0)}h`;
  return `${(h / 24).toFixed(1)}d`;
}

/** RFC-4180 CSV. Cells containing , " CR LF are quoted; formula-leading cells are defused. */
export function toCsv(rows: (string | number | boolean | null | undefined)[][]): string {
  return rows
    .map((r) =>
      r
        .map((c) => {
          if (c == null) return "";
          let s = String(c);
          // CSV-injection guard: a cell starting with = + - @ (that isn't a plain number) opens as a formula in Excel.
          if (/^[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?$/.test(s)) s = `'${s}`;
          return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
        })
        .join(","),
    )
    .join("\r\n");
}

/** UTC month key "2026-09". */
export function monthKeyUTC(d: Date): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

/** Whole months between two month keys (b - a). */
export function monthDiff(a: string, b: string): number {
  const [ay, am] = a.split("-").map(Number);
  const [by, bm] = b.split("-").map(Number);
  return (by - ay) * 12 + (bm - am);
}

/** z-score of `x` against a baseline; null when the baseline has no spread. */
export function zScore(x: number, baseline: number[]): number | null {
  const m = mean(baseline);
  const s = stddev(baseline);
  if (m == null || s == null || s === 0) return null;
  return (x - m) / s;
}
import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { includeBots } from "@/lib/bots/scope";
import { parseRange, PRESETS } from "@/lib/insights/range";
import { INSIGHTS_TABS, type InsightsTabKey } from "@/lib/insights/tabs";
import { RangeControls, BotToggle } from "./Controls";
import { OverviewTab } from "./tabs/overview";
import { RevenueTab } from "./tabs/revenue";
import { CustomersTab } from "./tabs/customers";
import { FunnelTab } from "./tabs/funnel";
import { ProductsTab } from "./tabs/products";
import { CapacityTab } from "./tabs/capacity";
import { OperationsTab } from "./tabs/operations";
import { GrowthTab } from "./tabs/growth";
import { PaymentsTab } from "./tabs/payments";
import { CrawlersTab } from "./tabs/crawlers";

export const dynamic = "force-dynamic";

/**
 * /admin/insights — the owner's business analytics, every number computed
 * from the database (lib/insights/*). Date range + compare-to-previous-period
 * via the URL; CSV export per tab (./export/route.ts). Visitor numbers are
 * bot-free unless the admin flips the include-bots toggle.
 */
export default async function InsightsPage({ searchParams }: { searchParams: Promise<{ tab?: string; from?: string; to?: string; preset?: string }> }) {
  await requireArea("analytics");
  const sp = await searchParams;
  const tab: InsightsTabKey = (INSIGHTS_TABS.some((t) => t.key === sp.tab) ? sp.tab : "overview") as InsightsTabKey;
  const range = parseRange(sp);
  const bots = await includeBots();
  const qs = range.preset ? `preset=${range.preset}` : `from=${range.fromStr}&to=${range.toStr}`;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Insights"
        sub={`Business analytics from live data · ${range.label} (${range.fromStr} → ${range.toStr}, UTC) compared with the ${range.days} days before.`}
      >
        <BotToggle on={bots} />
        <a href={`/admin/insights/export?tab=${tab}&${qs}`} className="btn-secondary !h-8 !px-3 !py-1 text-xs" download>
          Export CSV
        </a>
      </PageHeader>

      <div className="flex flex-col gap-3">
        <RangeControls tab={tab} preset={range.preset} fromStr={range.fromStr} toStr={range.toStr} presets={PRESETS} />
        <nav aria-label="Insights sections" className="-mx-1 flex gap-1 overflow-x-auto px-1 pb-1">
          {INSIGHTS_TABS.map((t) => (
            <Link
              key={t.key}
              href={`/admin/insights?tab=${t.key}&${qs}`}
              aria-current={t.key === tab ? "page" : undefined}
              className={`shrink-0 rounded-lg px-3 py-1.5 text-sm font-medium transition ${
                t.key === tab ? "bg-gradient-to-r from-accent-blue/25 to-brand-500/25 text-white ring-1 ring-brand-500/40" : "text-slate-400 hover:bg-white/[0.04] hover:text-slate-200"
              }`}
            >
              {t.label}
            </Link>
          ))}
        </nav>
      </div>

      {bots && (
        <p className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-200">
          Bot traffic is INCLUDED in visitor numbers right now. Conversions, revenue and stored daily rollups are always bot-free.
        </p>
      )}

      {tab === "overview" && <OverviewTab range={range} />}
      {tab === "revenue" && <RevenueTab range={range} />}
      {tab === "customers" && <CustomersTab range={range} />}
      {tab === "funnel" && <FunnelTab range={range} />}
      {tab === "products" && <ProductsTab range={range} />}
      {tab === "capacity" && <CapacityTab />}
      {tab === "operations" && <OperationsTab range={range} />}
      {tab === "growth" && <GrowthTab range={range} />}
      {tab === "payments" && <PaymentsTab range={range} />}
      {tab === "crawlers" && <CrawlersTab range={range} />}
    </div>
  );
}

model ErrorLog {
  id          String   @id @default(cuid())
  level       String   @default("error") // error | warn | info
  source      String // worker | action | api | client | job
  context     String // short label, e.g. "BACKUP_RESTORE" / "actions-sites.publish"
  message     String
  detail      String? // stack / extra JSON
  fingerprint String   @unique // hash(context+message) for dedup
  userId      String?
  serverId    String?
  jobId       String?
  count       Int      @default(1)
  firstSeen   DateTime @default(now())
  lastSeen    DateTime @default(now())
  resolved    Boolean  @default(false)

  @@index([lastSeen])
  @@index([level, lastSeen])
  @@index([source])
}
model TelemetryEvent {
  id        String   @id @default(cuid())
  // One of these two identifies the source; VPS/GAME events set serverId,
  // HOSTING/MAIL events (centralized shippers) set nodeId + nodeKind instead.
  serverId  String?
  server    Server?  @relation(fields: [serverId], references: [id], onDelete: Cascade)
  nodeId    String? // HostingNode.id for HOSTING; a fixed constant for MAIL (see lib/telemetry.ts)
  nodeKind  String // VPS | GAME | HOSTING | MAIL
  type      String // SSH_LOGIN | SSH_LOGOUT | SSH_FAILED | VISITOR | MAIL_AUTH
  ts        DateTime @default(now()) // event time as reported by the shipper
  ip        String?
  user      String?
  path      String? // VISITOR request path
  site      String? // which vhost/customer site, on a centralized HOSTING shipper
  status    String?
  meta      String?
  label     String? // hostname/display label the shipper reported, for the UI
  createdAt DateTime @default(now()) // ingest time — what the prune sweep keys off

  @@index([createdAt])
  @@index([serverId, createdAt])
  @@index([nodeKind, createdAt])
}
model DeployFunnelEvent {
  id           String   @id @default(cuid())
  userId       String? // signed-in account, when resolvable server-side
  visitorId    String? // stable cookie id, when consent allows
  sessionId    String? // per-tab session id (client), the primary dedupe key
  product      String // vps | game | hosting | email
  step         String // wizard step label reached/errored, OR (type="select") the selection kind
  stepIndex    Int // position of that step within the session's wizard
  type         String   @default("step") // step | error | complete | select
  errorCode    String? // machine code for an error event (e.g. PROVISION_FAILED)
  errorMessage String? // human error text, truncated
  /// (type="select" only) JSON string of what was picked, e.g. `{"value":"minecraft"}`.
  /// Added 2026-09-27 — see prisma/manual-migration-deploy-funnel-select.sql.
  /// NOT yet part of the generated Prisma client shared via this worktree's
  /// symlinked node_modules (regenerating it here would touch /opt/nxeon's live
  /// client before production's own DB has this column) — read/written with raw
  /// SQL ($queryRaw/$executeRaw) in lib/deploy-funnel.ts until a real `db push`
  /// at deploy regenerates the client, at which point the raw-SQL path keeps
  /// working unchanged.
  detail       String?  @db.Text
  createdAt    DateTime @default(now())

  @@index([product, createdAt])
  @@index([product, type])
}
model InsightsSnapshot {
  id        String   @id @default(cuid())
  date      DateTime // UTC midnight
  metric    String // "mrr_cents" | "paid_servers" | "paying_customers" | "node_committed_ram_mb" | "node_used_ram_mb"
  scopeId   String   @default("") // node id for per-node metrics, "" for global
  value     Float
  createdAt DateTime @default(now())

  @@unique([date, metric, scopeId])
  @@index([metric, date])
}
model GrowthReport {
  id          String    @id @default(cuid())
  weekStart   DateTime  @unique
  generatedAt DateTime  @default(now())
  trigger     String    @default("auto") // auto | manual
  data        Json
  emailedAt   DateTime?
}
model MetricsDaily {
  id              String       @id @default(cuid())
  date            DateTime // UTC day
  scope           MetricsScope
  scopeId         String
  sent            Int          @default(0)
  delivered       Int          @default(0)
  hardBounce      Int          @default(0)
  softBounce      Int          @default(0)
  opens           Int          @default(0) // UNRELIABLE — MPP/scanner inflated
  uniqueClicks    Int          @default(0)
  replies         Int          @default(0)
  positiveReplies Int          @default(0)
  complaints      Int          @default(0)
  unsubscribes    Int          @default(0)
  updatedAt       DateTime     @updatedAt

  @@unique([scope, scopeId, date])
  @@index([scope, scopeId])
  @@index([date])
}
model VisitorDaily {
  id                String   @id @default(cuid())
  date              DateTime @unique // UTC midnight of the day this row summarises
  pageviews         Int      @default(0)
  sessions          Int      @default(0)
  uniqueVisitors    Int      @default(0) // distinct visitorId (falling back to ip)
  newVisitors       Int      @default(0) // first ever seen on this day
  returningVisitors Int      @default(0) // seen on some earlier day too
  bounces           Int      @default(0) // single-pageview sessions
  totalSessionMs    BigInt   @default(0) // Σ session dwell — divide by sessions for avg time on site
  signups           Int      @default(0) // accounts created this day
  deployed          Int      @default(0) // of those accounts, how many deployed a server
  updatedAt         DateTime @updatedAt

  @@index([date])
}
model Visit {
  id           String    @id @default(cuid())
  ip           String
  path         String
  referrer     String?
  ua           String?
  // Parsed from `ua` at ingest time (lib/ua-parse.ts, ua-parser-js) — kept as
  // plain columns rather than re-parsed on every analytics read, same reasoning
  // as country/city below. deviceType is one of "Desktop"/"Mobile"/"Tablet"/
  // "Smart TV"/"Console"/"Wearable"/"XR" (UAParser has no positive "desktop"
  // signal — it's the fallback when no other type is detected). os/browser are
  // UAParser's own display names ("iOS", "Android", "Windows", "macOS", "Linux",
  // "Chrome", "Safari", "Firefox", "Edge", …) — null when ua was missing/unparseable.
  deviceType   String?
  os           String?
  browser      String?
  kind         String    @default("marketing") // marketing | portal
  userId       String?
  country      String?
