export type ChurnInsights = {
  startCustomers: number;
  churned: number;
  newPaying: number;
  endCustomers: number;
  churnRate: Maybe<number>;
  monthlyChurn: Maybe<number>;
  churnRatePrev: Maybe<number>;
  ltvRealized: Maybe<{ mean: number; median: number; customers: number }>;
  ltvPredicted: Maybe<number>;
  cohorts: Maybe<{ month: string; size: number; retained: (number | null)[] }[]>;
  churnedList: { userId: string; email: string; since: Date | null }[];
};

const MIN_START = 5;

function churnFor(lives: PaidLife[], from: Date, to: Date) {
  const start = payingAt(lives, from);
  const end = payingAt(lives, new Date(Math.min(to.getTime(), Date.now())));
  let churned = 0;
  const churnedIds: string[] = [];
  for (const u of start) if (!end.has(u)) {
    churned++;
    churnedIds.push(u);
  }
  let newPaying = 0;
  for (const u of end) if (!start.has(u)) newPaying++;
  return { start, end, churned, churnedIds, newPaying };
}

export async function churnInsights(r: InsightsRange, mrr: { mrrCents: number; payingCustomers: number }): Promise<ChurnInsights> {
  const lives = await paidLifetimes();
  const cur = churnFor(lives, r.from, r.to);
  const prev = churnFor(lives, r.prevFrom, r.prevTo);
  const rate = cur.start.size > 0 ? cur.churned / cur.start.size : 0;
  const monthly = 1 - Math.pow(1 - rate, 30 / r.days);

  // Realized LTV: net real cash per customer who has EVER paid.
  const everPaid = [...new Set(lives.map((l) => l.userId))];
  const spend = await realLifetimeSpendCentsByUser(everPaid);
  const ltvValues = everPaid.map((u) => spend.get(u) ?? 0).filter((v) => v > 0);

  // Cohorts by first-paid month: share still paying at the end of each later month.
  const first = firstPaidStart(lives);
  const nowKey = monthKeyUTC(new Date());
  const byMonth = new Map<string, string[]>();
  for (const [u, d] of first) {
    const k = monthKeyUTC(d);
    if (monthDiff(k, nowKey) > 11) continue;
    const arr = byMonth.get(k) ?? [];
    arr.push(u);
    byMonth.set(k, arr);
  }
  const cohortLives = new Map<string, PaidLife[]>();
  for (const [month, users] of byMonth) {
    const set = new Set(users);
    cohortLives.set(month, lives.filter((l) => set.has(l.userId)));
  }
  const cohortRows = [...byMonth.entries()]
    .sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .map(([month, users]) => {
      const span = monthDiff(month, nowKey);
      const retained: (number | null)[] = [];
      for (let k = 0; k <= 11; k++) {
        if (k > span) {
          retained.push(null);
          continue;
        }
        const [y, m] = month.split("-").map(Number);
        const endOfMonth = new Date(Date.UTC(y, m - 1 + k + 1, 1));
        const at = endOfMonth.getTime() > Date.now() ? new Date() : endOfMonth;
        const paying = payingAt(cohortLives.get(month) ?? [], at);
        retained.push(users.length ? paying.size / users.length : null);
      }
      return { month, size: users.length, retained };
    });

  const churnedUsers = cur.churnedIds.length
    ? await db.user.findMany({ where: { id: { in: cur.churnedIds.slice(0, 50) } }, select: { id: true, email: true } })
    : [];
  const lastEnd = new Map<string, Date>();
  const churnedSet = new Set(cur.churnedIds);
  for (const l of lives) if (l.end && churnedSet.has(l.userId)) {
    const p = lastEnd.get(l.userId);
    if (!p || l.end > p) lastEnd.set(l.userId, l.end);
  }

  return {
    startCustomers: cur.start.size,
    churned: cur.churned,
    newPaying: cur.newPaying,
    endCustomers: cur.end.size,
    churnRate: enough(cur.start.size >= MIN_START, () => rate, `Only ${cur.start.size} paying customer(s) at the start of the period — need ${MIN_START}+ for a meaningful churn rate.`),
    monthlyChurn: enough(cur.start.size >= MIN_START, () => monthly, `Not enough paying customers at period start.`),
    churnRatePrev: enough(prev.start.size >= MIN_START, () => prev.churned / prev.start.size, `Not enough customers in the previous period.`),
    ltvRealized: enough(
      ltvValues.length >= 3,
      () => ({ mean: Math.round(mean(ltvValues) ?? 0), median: Math.round(percentile(ltvValues, 50) ?? 0), customers: ltvValues.length }),
      `Only ${ltvValues.length} customer(s) with real payments so far.`,
    ),
    ltvPredicted: enough(
      cur.start.size >= MIN_START && monthly > 0 && mrr.payingCustomers > 0,
      () => Math.round(mrr.mrrCents / mrr.payingCustomers / monthly),
      monthly === 0 && cur.start.size >= MIN_START
        ? "No churn in this period — ARPU ÷ churn is undefined (not infinite). Widen the date range."
        : "Needs a measurable churn rate first.",
    ),
    cohorts: enough(cohortRows.length > 0, () => cohortRows, "No paying customers in the last 12 months."),
    churnedList: churnedUsers.map((u) => ({ userId: u.id, email: u.email, since: lastEnd.get(u.id) ?? null })),
  };
}

/**
 * Operational insights: job failure rate + latency per job type, and support
 * load + response times.
 *
 * Job timing: the Job table has createdAt/updatedAt and (once agent D1's
 * worker-metrics work lands) may gain startedAt/finishedAt columns. This
 * module checks information_schema at runtime and uses the precise columns
 * when present (queue wait = startedAt − createdAt, run = finishedAt −
 * startedAt); otherwise it reports END-TO-END latency (updatedAt − createdAt
 * for finished jobs) and says so — it never pretends to split the two.
 */
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { CUSTOMER_WHERE, enough, type Maybe } from "./common";
import type { InsightsRange } from "./range";
import { percentile } from "./stats";

export type JobTypeRow = {
  type: string;
  total: number;
  done: number;
  failed: number;
  queuedNow: number;
  failRate: number | null;
  waitP50: number | null;
  waitP95: number | null;
  runP50: number | null;
  runP95: number | null;
  e2eP50: number | null;
  e2eP95: number | null;
  topError: string | null;
};

let jobCols: { started: boolean; finished: boolean } | null = null;
async function jobTimingColumns() {
  if (jobCols) return jobCols;
  try {
    const rows = await db.$queryRaw<{ column_name: string }[]>`
      SELECT column_name FROM information_schema.columns WHERE table_name = 'Job' AND column_name IN ('startedAt', 'finishedAt')`;
    const names = new Set(rows.map((r) => r.column_name));
    jobCols = { started: names.has("startedAt"), finished: names.has("finishedAt") };
  } catch {
    jobCols = { started: false, finished: false };
  }
  return jobCols;
}

export async function jobInsights(r: InsightsRange): Promise<{ rows: JobTypeRow[]; precise: boolean; totalFailRate: number | null; prevFailRate: number | null }> {
  const cols = await jobTimingColumns();
  const precise = cols.started && cols.finished;
  type Row = { type: string; status: string; createdAt: Date; updatedAt: Date; startedAt: Date | null; finishedAt: Date | null; error: string | null };
  const sel = precise
    ? Prisma.sql`"startedAt", "finishedAt"`
    : Prisma.sql`NULL::timestamp AS "startedAt", NULL::timestamp AS "finishedAt"`;
  const [jobs, prev, queued] = await Promise.all([
    db.$queryRaw<Row[]>`SELECT type::text AS type, status::text AS status, "createdAt", "updatedAt", ${sel}, left(error, 160) AS error
      FROM "Job" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to} LIMIT 200000`,
    db.job.groupBy({ by: ["status"], where: { createdAt: { gte: r.prevFrom, lt: r.prevTo } }, _count: { _all: true } }),
    db.job.groupBy({ by: ["type"], where: { status: "QUEUED" }, _count: { _all: true } }),
  ]);
  const queuedBy = new Map(queued.map((q) => [q.type as string, q._count._all]));
  const by = new Map<string, Row[]>();
  for (const j of jobs) {
    const a = by.get(j.type) ?? [];
    a.push(j);
    by.set(j.type, a);
  }
  const rows: JobTypeRow[] = [];
  let totDone = 0;
  let totFailed = 0;
  for (const [type, list] of by) {
    const finished = list.filter((j) => j.status === "DONE" || j.status === "FAILED");
    const done = list.filter((j) => j.status === "DONE").length;
    const failed = list.filter((j) => j.status === "FAILED").length;
    totDone += done;
    totFailed += failed;
    const e2e = finished.map((j) => j.updatedAt.getTime() - j.createdAt.getTime());
    const waits = precise ? list.filter((j) => j.startedAt).map((j) => j.startedAt!.getTime() - j.createdAt.getTime()) : [];
    const runs = precise ? finished.filter((j) => j.startedAt && j.finishedAt).map((j) => j.finishedAt!.getTime() - j.startedAt!.getTime()) : [];
    const errs = new Map<string, number>();
    for (const j of list) if (j.status === "FAILED" && j.error) {
      const k = j.error.replace(/\d+/g, "#").slice(0, 80);
      errs.set(k, (errs.get(k) ?? 0) + 1);
    }
    const topError = [...errs.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
    rows.push({
      type,
      total: list.length,
      done,
      failed,
      queuedNow: queuedBy.get(type) ?? 0,
      failRate: done + failed > 0 ? failed / (done + failed) : null,
      waitP50: percentile(waits, 50),
      waitP95: percentile(waits, 95),
      runP50: percentile(runs, 50),
      runP95: percentile(runs, 95),
      e2eP50: percentile(e2e, 50),
      e2eP95: percentile(e2e, 95),
      topError,
    });
  }
  const pd = prev.find((p) => p.status === "DONE")?._count._all ?? 0;
  const pf = prev.find((p) => p.status === "FAILED")?._count._all ?? 0;
  return {
    rows: rows.sort((a, b) => b.total - a.total),
    precise,
    totalFailRate: totDone + totFailed > 0 ? totFailed / (totDone + totFailed) : null,
    prevFailRate: pd + pf > 0 ? pf / (pd + pf) : null,
  };
}

export type SupportInsights = {
  created: number;
  createdPrev: number;
  openNow: number;
  awaitingStaffNow: number;
  firstResponse: Maybe<{ p50: number; p90: number; n: number }>;
  firstResponsePrev: Maybe<{ p50: number }>;
  resolution: Maybe<{ p50: number; p90: number; n: number }>;
  unanswered: number;
  perHundredPaying: number | null;
  byPriority: { label: string; count: number }[];
  oldestAwaiting: { id: string; subject: string; email: string; waitingMs: number }[];
};

async function ticketTimes(from: Date, to: Date) {
  const tickets = await db.ticket.findMany({
    where: { createdAt: { gte: from, lt: to }, user: CUSTOMER_WHERE },
    select: { id: true, status: true, priority: true, createdAt: true, updatedAt: true, messages: { where: { isStaff: true }, orderBy: { createdAt: "asc" }, take: 1, select: { createdAt: true } } },
    take: 20_000,
  });
  const first = tickets.filter((t) => t.messages[0]).map((t) => t.messages[0].createdAt.getTime() - t.createdAt.getTime());
  const resolved = tickets.filter((t) => t.status === "CLOSED").map((t) => t.updatedAt.getTime() - t.createdAt.getTime());
  return { tickets, first, resolved };
}

export async function supportInsights(r: InsightsRange, payingCustomers: number): Promise<SupportInsights> {
  const [cur, prev, open, awaiting] = await Promise.all([
    ticketTimes(r.from, r.to),
    ticketTimes(r.prevFrom, r.prevTo),
    db.ticket.count({ where: { status: { not: "CLOSED" }, user: CUSTOMER_WHERE } }),
    db.ticket.findMany({
      where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] }, user: CUSTOMER_WHERE },
      orderBy: { updatedAt: "asc" },
      take: 10,
      select: { id: true, subject: true, updatedAt: true, user: { select: { email: true } } },
    }),
  ]);
  const prio = new Map<string, number>();
  for (const t of cur.tickets) prio.set(t.priority, (prio.get(t.priority) ?? 0) + 1);
  const awaitingCount = await db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] }, user: CUSTOMER_WHERE } });
  return {
    created: cur.tickets.length,
    createdPrev: prev.tickets.length,
    openNow: open,
    awaitingStaffNow: awaitingCount,
    firstResponse: enough(cur.first.length >= 3, () => ({ p50: percentile(cur.first, 50)!, p90: percentile(cur.first, 90)!, n: cur.first.length }), `Only ${cur.first.length} ticket(s) got a staff reply in this period.`),
    firstResponsePrev: enough(prev.first.length >= 3, () => ({ p50: percentile(prev.first, 50)! }), "Not enough tickets in the previous period."),
    resolution: enough(cur.resolved.length >= 3, () => ({ p50: percentile(cur.resolved, 50)!, p90: percentile(cur.resolved, 90)!, n: cur.resolved.length }), `Only ${cur.resolved.length} ticket(s) closed in this period.`),
    unanswered: cur.tickets.filter((t) => !t.messages[0]).length,
    perHundredPaying: payingCustomers > 0 ? (cur.tickets.length / payingCustomers) * 100 : null,
    byPriority: [...prio.entries()].map(([label, count]) => ({ label, count })).sort((a, b) => b.count - a.count),
    oldestAwaiting: awaiting.map((t) => ({ id: t.id, subject: t.subject, email: t.user.email, waitingMs: Date.now() - t.updatedAt.getTime() })),
  };
}

/**
 * Acquisition funnel for /admin/insights — bot-free by construction:
 *   visitors   distinct people (visitorId, else IP) in the Visit log with
 *              isBot = false (lib/analytics.ts visitScope — honours the admin
 *              "include bots" toggle, which shows the polluted number when on)
 *   signups    counting customer accounts created in the period
 *   deployed   of those signups, anyone who got a real server (or a free MC server)
 *   paid       of those signups, anyone with a real card/PayPal/crypto payment
 *              OR an earned-revenue debit by now
 * plus time-to-first-deploy / time-to-first-payment and conversion broken
 * down by acquisition source, partner and country, and the free-Minecraft →
 * paid upgrade funnel.
 */
import { db } from "@/lib/db";
import { visitScope } from "@/lib/analytics";
import { REVENUE_WHERE } from "@/lib/admin-metrics";
import { REAL_CASH_IN_WHERE } from "@/lib/revenue";
import { resolveAcquisitionSources } from "@/lib/user-attribution";
import { CUSTOMER_WHERE, DEPLOYED_STATUSES, enough, type Maybe } from "./common";
import type { InsightsRange } from "./range";
import { percentile } from "./stats";

export type FunnelStage = { visitors: number; signups: number; deployed: number; paid: number };
export type Breakdown = { label: string; signups: number; deployed: number; paid: number };

export type FunnelInsights = {
  cur: FunnelStage;
  prev: FunnelStage;
  botVisitorsExcluded: number;
  ttfdMs: Maybe<{ p50: number; p90: number; n: number }>;
  ttfpMs: Maybe<{ p50: number; p90: number; n: number }>;
  bySource: Breakdown[];
  byPartner: Breakdown[];
  byCountry: Breakdown[];
  freeMc: { created: number; upgraded: number; medianDaysToUpgrade: number | null; allTimeCreated: number; allTimeUpgraded: number };
};

type VisitScope = { ip?: { notIn: string[] }; isBot?: boolean };

async function distinctVisitors(from: Date, to: Date, scope: VisitScope): Promise<number> {
  const [vids, ips] = await Promise.all([
    db.visit.findMany({ where: { createdAt: { gte: from, lt: to }, visitorId: { not: null }, ...scope }, distinct: ["visitorId"], select: { visitorId: true }, take: 200_000 }),
    db.visit.findMany({ where: { createdAt: { gte: from, lt: to }, visitorId: null, ...scope }, distinct: ["ip"], select: { ip: true }, take: 200_000 }),
  ]);
  return vids.length + ips.length;
}

type Signup = { id: string; createdAt: Date; heardAboutUs: string | null; billingCountry: string | null };

async function signupsIn(from: Date, to: Date): Promise<Signup[]> {
  return db.user.findMany({
    where: { ...CUSTOMER_WHERE, createdAt: { gte: from, lt: to } },
    select: { id: true, createdAt: true, heardAboutUs: true, billingCountry: true },
    take: 50_000,
  });
}

/** first deploy + first payment instants per user. */
async function outcomes(ids: string[]): Promise<{ deploy: Map<string, Date>; pay: Map<string, Date> }> {
  const deploy = new Map<string, Date>();
  const pay = new Map<string, Date>();
  if (!ids.length) return { deploy, pay };
  const [servers, freemc, cash, debit] = await Promise.all([
    db.server.groupBy({ by: ["userId"], where: { userId: { in: ids }, status: { in: [...DEPLOYED_STATUSES] } }, _min: { createdAt: true } }),
    db.freeMinecraftServer.findMany({ where: { userId: { in: ids } }, select: { userId: true, createdAt: true } }),
    db.walletTransaction.groupBy({ by: ["userId"], where: { ...REAL_CASH_IN_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
    db.walletTransaction.groupBy({ by: ["userId"], where: { ...REVENUE_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
  ]);
  const setMin = (m: Map<string, Date>, id: string, d: Date | null | undefined) => {
    if (!d) return;
    const c = m.get(id);
    if (!c || d < c) m.set(id, d);
  };
  for (const s of servers) setMin(deploy, s.userId, s._min.createdAt);
  // Archived (deleted) servers also prove a deploy happened.
  const arch = await db.serverArchive.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _min: { provisionedAt: true } });
  for (const a of arch) if (a.userId) setMin(deploy, a.userId, a._min.provisionedAt);
  for (const f of freemc) setMin(deploy, f.userId, f.createdAt);
  for (const c of cash) setMin(pay, c.userId, c._min.createdAt);
  for (const d of debit) setMin(pay, d.userId, d._min.createdAt);
  return { deploy, pay };
}

function stage(visitors: number, signups: Signup[], o: { deploy: Map<string, Date>; pay: Map<string, Date> }): FunnelStage {
  return {
    visitors,
    signups: signups.length,
    deployed: signups.filter((s) => o.deploy.has(s.id)).length,
    paid: signups.filter((s) => o.pay.has(s.id)).length,
  };
}

function breakdown(signups: Signup[], o: { deploy: Map<string, Date>; pay: Map<string, Date> }, labelOf: (s: Signup) => string): Breakdown[] {
  const m = new Map<string, Breakdown>();
  for (const s of signups) {
    const label = labelOf(s);
    const b = m.get(label) ?? { label, signups: 0, deployed: 0, paid: 0 };
    b.signups++;
    if (o.deploy.has(s.id)) b.deployed++;
    if (o.pay.has(s.id)) b.paid++;
    m.set(label, b);
  }
  return [...m.values()].sort((a, b) => b.signups - a.signups);
}

export async function funnelInsights(r: InsightsRange): Promise<FunnelInsights> {
  const scope = await visitScope();
  const [vCur, vPrev, vAll, sCur, sPrev] = await Promise.all([
    distinctVisitors(r.from, r.to, scope),
    distinctVisitors(r.prevFrom, r.prevTo, scope),
    // Same count with bots included, so the page can say how many it removed.
    distinctVisitors(r.from, r.to, scope.ip ? { ip: scope.ip } : {}),
    signupsIn(r.from, r.to),
    signupsIn(r.prevFrom, r.prevTo),
  ]);
  const [oCur, oPrev] = await Promise.all([outcomes(sCur.map((s) => s.id)), outcomes(sPrev.map((s) => s.id))]);

  const ttfd = sCur.filter((s) => oCur.deploy.has(s.id)).map((s) => oCur.deploy.get(s.id)!.getTime() - s.createdAt.getTime()).filter((x) => x >= 0);
  const ttfp = sCur.filter((s) => oCur.pay.has(s.id)).map((s) => oCur.pay.get(s.id)!.getTime() - s.createdAt.getTime()).filter((x) => x >= 0);

  // Sources (self-reported survey first, then real utm/gclid first-touch).
  const sources = await resolveAcquisitionSources(sCur.map((s) => ({ id: s.id, heardAboutUs: s.heardAboutUs })));
  const srcLabel = (s: Signup) => {
    const a = sources.get(s.id);
    if (!a) return "Unknown";
    if (a.kind === "self-reported") return `Survey: ${a.label}`;
    if (a.kind === "tracked") return `Tracked: ${a.label}`;
    if (a.kind === "skipped") return "Skipped survey";
    return "Unknown";
  };

  // Partner attachment.
  const attach = sCur.length
    ? await db.partnerCustomer.findMany({ where: { customerId: { in: sCur.map((s) => s.id) } }, select: { customerId: true, partner: { select: { name: true, code: true } } } })
    : [];
  const partnerOf = new Map(attach.map((a) => [a.customerId, `${a.partner.name} (${a.partner.code})`]));

  // Country: billing country if set, else the most recent bot-free visit that geocoded.
  const needCountry = sCur.filter((s) => !s.billingCountry).map((s) => s.id);
  const visitCountry = needCountry.length
    ? await db.visit.findMany({
        where: { userId: { in: needCountry }, country: { not: null }, isBot: false },
        distinct: ["userId"],
        orderBy: [{ userId: "asc" }, { createdAt: "desc" }],
        select: { userId: true, country: true },
      })
    : [];
  const countryOf = new Map(visitCountry.map((v) => [v.userId as string, v.country as string]));

  // Free Minecraft → paid.
  const [mcCur, mcAll] = await Promise.all([
    db.freeMinecraftServer.findMany({ where: { createdAt: { gte: r.from, lt: r.to }, user: CUSTOMER_WHERE }, select: { userId: true, createdAt: true } }),
    db.freeMinecraftServer.findMany({ where: { user: CUSTOMER_WHERE }, select: { userId: true, createdAt: true }, take: 50_000 }),
  ]);
  const mcPay = await outcomes([...new Set(mcAll.map((m) => m.userId))]);
  const upgradedAfter = (m: { userId: string; createdAt: Date }) => {
    const p = mcPay.pay.get(m.userId);
    return p && p >= m.createdAt ? p : null;
  };
  const upDays = mcCur.map((m) => upgradedAfter(m)).map((p, i) => (p ? (p.getTime() - mcCur[i].createdAt.getTime()) / 86_400_000 : null)).filter((x): x is number => x != null);

  return {
    cur: stage(vCur, sCur, oCur),
    prev: stage(vPrev, sPrev, oPrev),
    botVisitorsExcluded: Math.max(0, vAll - vCur),
    ttfdMs: enough(ttfd.length >= 3, () => ({ p50: percentile(ttfd, 50)!, p90: percentile(ttfd, 90)!, n: ttfd.length }), `Only ${ttfd.length} signup(s) in this period deployed.`),
    ttfpMs: enough(ttfp.length >= 3, () => ({ p50: percentile(ttfp, 50)!, p90: percentile(ttfp, 90)!, n: ttfp.length }), `Only ${ttfp.length} signup(s) in this period paid.`),
    bySource: breakdown(sCur, oCur, srcLabel),
    byPartner: breakdown(sCur, oCur, (s) => partnerOf.get(s.id) ?? "No partner"),
    byCountry: breakdown(sCur, oCur, (s) => s.billingCountry ?? countryOf.get(s.id) ?? "Unknown"),
    freeMc: {
      created: mcCur.length,
      upgraded: mcCur.filter((m) => upgradedAfter(m)).length,
      medianDaysToUpgrade: percentile(upDays, 50),
      allTimeCreated: mcAll.length,
      allTimeUpgraded: mcAll.filter((m) => upgradedAfter(m)).length,
    },
  };
}
  );
  tot.openRate = tot.sent > 0 ? tot.opened / tot.sent : null;
  tot.clickRate = tot.sent > 0 ? tot.clicked / tot.sent : null;
  return { rows, totals: tot };
}

const FAIL_TEMPLATES = ["payment_failed", "payment_retry_failed", "payment_final_notice", "paypal_payment_failed"];

export type PaymentInsights = {
  failureEmails: { template: string; count: number }[];
  failureEmailsPrev: number;
  usersWithFailures: number;
  dunningNow: { stage: number; count: number }[];
  overdueInvoices: { count: number; cents: number };
  refunds: { cents: number; count: number };
  refundsPrev: { cents: number; count: number };
  refundedInvoices: number;
  chargebacksRecorded: number;
  chargebacksPrev: number;
  recentRefunds: { when: Date; email: string; cents: number; description: string }[];
};

export async function paymentInsights(r: InsightsRange): Promise<PaymentInsights> {
  const [fails, failsPrev, failUsers, dunning, overdue, refunds, refundsPrev, refundedInv, cb, cbPrev, recent] = await Promise.all([
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to }, template: { in: FAIL_TEMPLATES } }, _count: { _all: true } }),
    db.emailLog.count({ where: { createdAt: { gte: r.prevFrom, lt: r.prevTo }, template: { in: FAIL_TEMPLATES } } }),
    db.emailLog.findMany({ where: { createdAt: { gte: r.from, lt: r.to }, template: { in: FAIL_TEMPLATES }, userId: { not: null } }, distinct: ["userId"], select: { userId: true } }),
    db.server.groupBy({ by: ["dunningStage"], where: { dunningStage: { gt: 0 }, user: CUSTOMER_WHERE }, _count: { _all: true } }),
    db.invoice.aggregate({ where: { status: "OPEN", createdAt: { lt: new Date(Date.now() - 7 * 86_400_000) }, user: CUSTOMER_WHERE }, _count: { _all: true }, _sum: { amountCents: true } }),
