/** StatCard with an automatic "vs previous period" delta. `higherIsBetter` picks the colour. */
export function Kpi({
  label,
  value,
  cur,
  prev,
  higherIsBetter = true,
  note,
  spark,
}: {
  label: string;
  value: string;
  cur?: number | null;
  prev?: number | null;
  higherIsBetter?: boolean;
  note?: string;
  spark?: number[];
}) {
  const ch = cur != null ? relChange(cur, prev) : null;
  const delta = fmtDelta(ch) ?? note;
  const good = ch == null ? undefined : higherIsBetter ? ch >= 0 : ch <= 0;
  return <StatCard label={label} value={value} delta={delta} deltaGood={good} spark={spark} />;
}

export function NotEnough({ reason }: { reason: string }) {
  return (
    <p className="rounded-lg border border-dashed border-white/10 bg-white/[0.02] px-3 py-4 text-center text-sm text-slate-500">
      Not enough data yet — {reason}
    </p>
  );
}

export function MaybeValue<T>({ m, render }: { m: Maybe<T>; render: (v: T) => React.ReactNode }) {
  return m.ok ? <>{render(m.value)}</> : <NotEnough reason={m.reason} />;
}

