/**
 * Time-frame handling for /admin/reports. Pure (no DB, no React) — unit tested
 * in test/reports-range.test.ts.
 *
 * What it adds over lib/insights/range.ts (which it stays shape-compatible
 * with, so every lib/insights/* function can be called with a ReportRange):
 *
 *  - A TIME ZONE. Day boundaries are computed in the owner's IANA zone (default
 *    UTC), so "today" and "month to date" mean the owner's today, not London's.
 *    DST-safe: every boundary is resolved through Intl, never a fixed offset.
 *  - A "today" preset and partial-period FAIRNESS: when the chosen period is
 *    still running (it contains "now"), the comparison period is truncated to
 *    the same elapsed length. Today-so-far at 10:00 is compared with yesterday
 *    00:00–10:00, not with all of yesterday — otherwise every running period
 *    would look like a collapse.
 *  - A BASELINE: the N equal-length periods before the comparison period, so
 *    the insight engine can tell an anomaly ("far outside the usual spread")
 *    from ordinary week-to-week noise.
 *  - A compare toggle (previous period / none).
 */

export type ComparePref = "previous" | "none";

export type Span = { from: Date; to: Date };

export type ReportRange = {
  /** Inclusive start (midnight in `tz`, as a UTC instant). */
  from: Date;
  /** Exclusive end, clamped to `now` when the period is still running. */
  to: Date;
  /** Exclusive end of the nominal period (midnight after the last day). */
  nominalTo: Date;
  /** Elapsed length in days (fractional for a running period, ≥ 1/24). */
  days: number;
  /** Whole calendar days the nominal period covers. */
  calendarDays: number;
  prevFrom: Date;
  prevTo: Date;
  /** Older equal-length periods (newest first) for anomaly detection. */
  baseline: Span[];
  partial: boolean;
  compare: ComparePref;
  tz: string;
  preset: string | null;
  fromStr: string;
  toStr: string;
  label: string;
  prevLabel: string;
};

export const REPORT_PRESETS: { key: string; label: string }[] = [
  { key: "today", label: "Today" },
  { key: "7d", label: "Last 7 days" },
  { key: "30d", label: "Last 30 days" },
  { key: "90d", label: "Last 90 days" },
  { key: "mtd", label: "Month to date" },
];

const HOUR = 3_600_000;
const DAY = 86_400_000;
const YMD = /^\d{4}-\d{2}-\d{2}$/;
export const BASELINE_PERIODS = 4;
const MAX_DAYS = 400;

/** True when `tz` is a zone this runtime's Intl understands. */
export function isValidTimeZone(tz: string): boolean {
  if (!tz || tz.length > 64) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/** Calendar parts of instant `d` as seen in `tz`. */
export function zonedParts(d: Date, tz: string): { y: number; m: number; day: number; h: number; min: number; s: number } {
  const f = new Intl.DateTimeFormat("en-US", {
    timeZone: tz,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const p: Record<string, number> = {};
  for (const part of f.formatToParts(d)) if (part.type !== "literal") p[part.type] = Number(part.value);
  return { y: p.year, m: p.month, day: p.day, h: p.hour === 24 ? 0 : p.hour, min: p.minute, s: p.second };
}

/** Offset of `tz` from UTC at instant `d`, in ms (positive east of UTC). */
function offsetMs(d: Date, tz: string): number {
  const z = zonedParts(d, tz);
  const asUtc = Date.UTC(z.y, z.m - 1, z.day, z.h, z.min, z.s);
  return asUtc - Math.floor(d.getTime() / 1000) * 1000;
}

/**
 * The UTC instant of local midnight on calendar day y-m-d in `tz`. Two-pass so
 * a DST change between the guess and the answer is still resolved exactly.
 */
export function zonedMidnight(y: number, m: number, day: number, tz: string): Date {
  const guess = Date.UTC(y, m - 1, day);
  let t = guess - offsetMs(new Date(guess), tz);
  t = guess - offsetMs(new Date(t), tz);
  return new Date(t);
}

/** Local calendar date string (yyyy-mm-dd) of instant `d` in `tz`. */
export function localYmd(d: Date, tz: string): string {
  const z = zonedParts(d, tz);
  return `${z.y}-${String(z.m).padStart(2, "0")}-${String(z.day).padStart(2, "0")}`;
}

function ymdParts(s: string): [number, number, number] {
  const [y, m, d] = s.split("-").map(Number);
  return [y, m, d];
}

/** Add whole calendar days to a yyyy-mm-dd string (zone-free arithmetic). */
export function addDaysYmd(s: string, n: number): string {
  const [y, m, d] = ymdParts(s);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

function midnightOf(s: string, tz: string): Date {
  const [y, m, d] = ymdParts(s);
  return zonedMidnight(y, m, d, tz);
}

function fmtDay(s: string): string {
  const [y, m, d] = ymdParts(s);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
