export type RangeParams = { preset?: string; from?: string; to?: string; tz?: string; compare?: string };

export function parseReportRange(sp: RangeParams, now: Date = new Date()): ReportRange {
  const tz = sp.tz && isValidTimeZone(sp.tz) ? sp.tz : "UTC";
  const compare: ComparePref = sp.compare === "none" ? "none" : "previous";
  const todayStr = localYmd(now, tz);
  let fromStr: string | null = null;
  let lastStr: string | null = null;
  let preset: string | null = null;

  if (sp.from && YMD.test(sp.from)) {
    const last = sp.to && YMD.test(sp.to) ? sp.to : todayStr;
    if (!Number.isNaN(Date.parse(`${sp.from}T00:00:00Z`)) && !Number.isNaN(Date.parse(`${last}T00:00:00Z`)) && last >= sp.from) {
      fromStr = sp.from;
      lastStr = last > todayStr ? todayStr : last;
      if (fromStr > lastStr) fromStr = lastStr;
    }
  }
  if (!fromStr || !lastStr) {
    preset = REPORT_PRESETS.some((p) => p.key === sp.preset) ? (sp.preset as string) : "7d";
    lastStr = todayStr;
    if (preset === "today") fromStr = todayStr;
    else if (preset === "mtd") fromStr = `${todayStr.slice(0, 8)}01`;
    else fromStr = addDaysYmd(todayStr, -(Number(preset.replace("d", "")) - 1));
  }
  // Cap the span so a typo can't ask for a decade-long scan.
  const span = Math.round((Date.parse(`${lastStr}T00:00:00Z`) - Date.parse(`${fromStr}T00:00:00Z`)) / DAY) + 1;
  if (span > MAX_DAYS) fromStr = addDaysYmd(lastStr, -(MAX_DAYS - 1));
  const calendarDays = Math.round((Date.parse(`${lastStr}T00:00:00Z`) - Date.parse(`${fromStr}T00:00:00Z`)) / DAY) + 1;

  const from = midnightOf(fromStr, tz);
  const nominalTo = midnightOf(addDaysYmd(lastStr, 1), tz);
  const partial = now.getTime() < nominalTo.getTime();
  const to = partial ? new Date(Math.max(now.getTime(), from.getTime() + HOUR)) : nominalTo;
  const elapsed = to.getTime() - from.getTime();

  // Comparison period: the same number of CALENDAR days immediately before,
  // starting at local midnight (DST-correct), truncated to the same elapsed
  // length when this period is still running.
  const prevFromStr = addDaysYmd(fromStr, -calendarDays);
  const prevFrom = midnightOf(prevFromStr, tz);
  const prevNominalTo = from;
  const prevTo = partial ? new Date(Math.min(prevFrom.getTime() + elapsed, prevNominalTo.getTime())) : prevNominalTo;

  const baseline: Span[] = [];
  for (let k = 2; k <= BASELINE_PERIODS + 1; k++) {
    const bFrom = midnightOf(addDaysYmd(fromStr, -calendarDays * k), tz);
    const bNominalTo = midnightOf(addDaysYmd(fromStr, -calendarDays * (k - 1)), tz);
    baseline.push({ from: bFrom, to: partial ? new Date(Math.min(bFrom.getTime() + elapsed, bNominalTo.getTime())) : bNominalTo });
  }

  const presetLabel = preset ? REPORT_PRESETS.find((p) => p.key === preset)?.label ?? preset : null;
  const label = presetLabel ?? (fromStr === lastStr ? fmtDay(fromStr) : `${fmtDay(fromStr)} – ${fmtDay(lastStr)}`);
  const prevLastStr = addDaysYmd(fromStr, -1);
  const prevLabel =
    preset === "today"
      ? partial
        ? "the same hours yesterday"
        : "yesterday"
      : `the previous ${calendarDays} day${calendarDays === 1 ? "" : "s"}${partial ? " (same elapsed time)" : ""} (${fmtDay(prevFromStr)} – ${fmtDay(prevLastStr)})`;

  return {
    from,
    to,
    nominalTo,
    days: Math.max(1 / 24, elapsed / DAY),
    calendarDays,
    prevFrom,
    prevTo,
    baseline,
    partial,
    compare,
    tz,
    preset,
    fromStr,
    toStr: lastStr,
    label,
    prevLabel,
  };
}

/** Query string that reproduces this range (for links, exports, saved views). */
export function rangeQuery(r: Pick<ReportRange, "preset" | "fromStr" | "toStr" | "tz" | "compare">): string {
  const q = new URLSearchParams();
  if (r.preset) q.set("preset", r.preset);
  else {
    q.set("from", r.fromStr);
    q.set("to", r.toStr);
  }
  if (r.tz !== "UTC") q.set("tz", r.tz);
  if (r.compare === "none") q.set("compare", "none");
  return q.toString();
}

/**
 * Local-day bucket keys covering [from, to) in `tz` (for charts). A key is the
 * local yyyy-mm-dd; `bucketOf` maps an instant to its key.
 */
export function localDayKeys(r: Pick<ReportRange, "fromStr" | "toStr">): string[] {
  const out: string[] = [];
  for (let s = r.fromStr; s <= r.toStr; s = addDaysYmd(s, 1)) out.push(s);
  return out;
}

export function bucketOf(d: Date, tz: string): string {
  return localYmd(d, tz);
}

