/**
 * Shapes shared by the report aggregation layer (lib/reports/collect.ts, DB)
 * and the insight engine (lib/reports/engine.ts, pure). Everything here is
 * plain JSON-able data so a report can be snapshotted (ReportRun.data),
 * emailed, or rendered without touching the database again.
 */

export type Domain =
  | "acquisition"
  | "signups"
  | "funnel"
  | "revenue"
  | "payments"
  | "provisioning"
  | "usage"
  | "retention"
  | "support"
  | "errors"
  | "fleet"
  | "email";

export const DOMAIN_LABELS: Record<Domain, string> = {
  acquisition: "Acquisition",
  signups: "Signups",
  funnel: "Deploy funnel",
  revenue: "Orders & revenue",
  payments: "Payments",
  provisioning: "Provisioning",
  usage: "Product usage",
  retention: "Retention & churn",
  support: "Support",
  errors: "Errors",
  fleet: "Fleet & capacity",
  email: "Email",
};

export type Unit = "count" | "cents" | "ratio" | "ms";

/**
 * One headline number with its comparison. For a ratio, `num`/`den` carry the
 * sample so the engine can test significance (and refuse to on tiny samples).
 * `baseline` holds the same metric for older equal-length periods (newest
 * first); null when it could not be computed.
 */
export type Metric = {
  key: string;
  domain: Domain;
  label: string;
  unit: Unit;
  cur: number | null;
  prev: number | null;
  num?: number;
  den?: number;
  prevNum?: number;
  prevDen?: number;
  /** Count of underlying events behind a money/latency metric (sample size). */
  n?: number;
  prevN?: number;
  baseline?: number[] | null;
  higherIsBetter: boolean;
  drill?: string;
  /** Small trend series for a sparkline (local days). */
  spark?: number[];
  note?: string;
};

export type Ranked = { label: string; value: number; prev?: number; hint?: string; href?: string };

export type FunnelStep = { step: string; index: number; reached: number; errored: number };
export type ProductFunnel = {
  product: string;
  sessions: number;
  completed: number;
  prevSessions: number;
  prevCompleted: number;
  steps: FunnelStep[];
  /** Sessions that reached the Payment step but have no complete event. */
  paymentReached: number;
  paymentLeft: number;
  prevPaymentReached: number;
  prevPaymentLeft: number;
  /** Signed-in user ids among the payment leavers (drill-down). */
  paymentLeftUserIds: string[];
  topErrors: { code: string; message: string; count: number }[];
};

export type GroupRate = { key: string; label: string; total: number; failed: number; prevTotal?: number; prevFailed?: number; examples?: string[]; userIds?: string[] };

export type FrictionInputs = {
  /** Email/password signups old enough to have verified (> 24h) and how many never did. */
  verification: { eligible: number; unverified: number; prevEligible: number; prevUnverified: number; verifyEmailsSent: number; verifyEmailsFailed: number; unverifiedUserIds: string[] };
  /** Signups that never deployed anything (paid, free VPS or free Minecraft). */
  activation: { signups: number; activated: number; prevSignups: number; prevActivated: number; medianHoursToDeploy: number | null };
  /** Payment failures grouped by card/billing country and by brand. */
  declinesByCountry: GroupRate[];
  declinesByBrand: GroupRate[];
  declineReasons: Ranked[];
  /** 3-D Secure / authentication failures. */
  authFailures: number;
  /** Renewal (off-session) declines recorded by the billing sweep. */
  renewalDeclines: { count: number; users: number; reasons: Ranked[]; userIds: string[] };
  /** Region picker showed a sold-out region / a customer clicked one. */
  soldOut: { sessionsShown: number; sessionsShownCompleted: number; picks: { region: string; count: number }[]; instrumented: boolean };
  /** PROVISION jobs grouped by game family / product. */
  provisionByGame: GroupRate[];
  provisionByNode: GroupRate[];
  /** Server-side error events whose context is on the deploy / order / payment path. */
  deployPathErrors: { events: number; prevEvents: number; contexts: Ranked[]; instrumented: boolean };
  /** Order-step validation/refusal messages (DeployFunnelEvent ORDER_ERROR). */
  orderErrors: { message: string; count: number; product: string }[];
  /** Device conversion: share of human visitors vs share of payers. */
  devices: { device: string; visitors: number; signups: number; payers: number }[];
  /** Transactional email failure rate by template. */
  emailFailures: GroupRate[];
  /** New error fingerprints first seen in the period. */
  newErrorTypes: { context: string; message: string; count: number; source: string }[];
  /** Support. */
  unansweredTickets: number;
  ticketFirstResponseP50Ms: number | null;
  ticketFirstResponsePrevP50Ms: number | null;
  chatHandoffs: { conversations: number; escalated: number; prevConversations: number; prevEscalated: number };
  botUnanswered: { count: number; top: Ranked[] };
  /** Free-month promo first renewals. */
