/**
 * Significance tests for the report insight engine. Pure; unit tested in
 * test/reports-engine.test.ts.
 *
 * The point of this file is restraint: a report that announces "signups up
 * 100%!" on 2 vs 1 trains the owner to ignore it. Every test here has a
 * minimum sample below which it answers "not significant", full stop.
 */
import { mean, stddev } from "@/lib/insights/stats";

export type Sig = { significant: boolean; rel: number | null; z: number | null; confidence: "high" | "medium" };

export const MIN_COUNT = 10; // a count change is never news below this many events (max of the two periods)
export const MIN_REL = 0.25; // …nor when it moved less than 25%
export const MIN_DEN = 20; // a rate is never compared on fewer than 20 trials per period
export const MIN_RATE_DIFF = 0.05; // …nor when it moved less than 5 points
export const MIN_MONEY_N = 5; // money: at least 5 transactions each side
export const MIN_MONEY_CENTS = 2_000; // …and at least $20 of movement
export const MIN_LATENCY_N = 10;
export const MIN_BASELINE = 3; // baseline periods needed before "anomaly" is a word we use
export const ANOMALY_Z = 3;

export function rel(cur: number, prev: number | null | undefined): number | null {
  if (prev == null || prev === 0) return null;
  return (cur - prev) / Math.abs(prev);
}

/**
 * Two Poisson counts over equal exposure: z = (a − b) / √(a + b). Needs
 * max(a, b) ≥ minCount and a relative move ≥ minRel (or a from-zero jump that
 * clears minCount on its own).
 */
export function countChange(cur: number, prev: number, opts: { minCount?: number; minRel?: number } = {}): Sig {
  const minCount = opts.minCount ?? MIN_COUNT;
  const minRel = opts.minRel ?? MIN_REL;
  const r = rel(cur, prev);
  if (Math.max(cur, prev) < minCount || cur + prev === 0) return { significant: false, rel: r, z: null, confidence: "medium" };
  const z = (cur - prev) / Math.sqrt(cur + prev);
  const bigEnough = r == null ? cur >= minCount : Math.abs(r) >= minRel;
  const significant = bigEnough && Math.abs(z) >= 1.96;
  const confidence = Math.abs(z) >= 2.58 && cur + prev >= 40 ? "high" : "medium";
  return { significant, rel: r, z, confidence };
}

/** Two-proportion z-test (pooled). Needs ≥ minDen trials on BOTH sides. */
export function ratioChange(n1: number, d1: number, n2: number, d2: number, opts: { minDen?: number; minDiff?: number } = {}): Sig & { p1: number | null; p2: number | null } {
  const minDen = opts.minDen ?? MIN_DEN;
  const minDiff = opts.minDiff ?? MIN_RATE_DIFF;
  const p1 = d1 > 0 ? n1 / d1 : null;
  const p2 = d2 > 0 ? n2 / d2 : null;
  if (d1 < minDen || d2 < minDen || p1 == null || p2 == null) return { significant: false, rel: null, z: null, confidence: "medium", p1, p2 };
  const p = (n1 + n2) / (d1 + d2);
  const se = Math.sqrt(p * (1 - p) * (1 / d1 + 1 / d2));
  const z = se === 0 ? 0 : (p1 - p2) / se;
  const significant = Math.abs(p1 - p2) >= minDiff && Math.abs(z) >= 1.96;
  const confidence = Math.abs(z) >= 2.58 && d1 >= 50 && d2 >= 50 ? "high" : "medium";
  return { significant, rel: rel(p1, p2), z, confidence, p1, p2 };
}

/** Money totals: both sides need MIN_MONEY_N transactions, a ≥ 25% move and ≥ $20 / 10% absolute. */
export function moneyChange(cur: number, prev: number, n: number, prevN: number): Sig {
  const r = rel(cur, prev);
  if (n < MIN_MONEY_N || prevN < MIN_MONEY_N) return { significant: false, rel: r, z: null, confidence: "medium" };
  const diff = Math.abs(cur - prev);
  const significant = r != null && Math.abs(r) >= MIN_REL && diff >= Math.max(MIN_MONEY_CENTS, 0.1 * Math.abs(prev));
  return { significant, rel: r, z: null, confidence: n >= 20 && prevN >= 20 ? "high" : "medium" };
}

/** Latency medians: both sides need MIN_LATENCY_N samples and a ≥ 30% move. */
export function latencyChange(cur: number, prev: number, n: number, prevN: number): Sig {
  const r = rel(cur, prev);
  if (n < MIN_LATENCY_N || prevN < MIN_LATENCY_N) return { significant: false, rel: r, z: null, confidence: "medium" };
  return { significant: r != null && Math.abs(r) >= 0.3, rel: r, z: null, confidence: n >= 30 && prevN >= 30 ? "high" : "medium" };
}

/**
 * Is `cur` far outside the spread of `baseline`? Needs MIN_BASELINE values,
 * a non-zero spread, a baseline mean worth talking about (`minMean`), and
 * |z| ≥ ANOMALY_Z.
 */
export function anomaly(cur: number, baseline: number[] | null | undefined, minMean = 5): { anomalous: boolean; z: number | null; mean: number | null; lo: number | null; hi: number | null } {
  const b = (baseline ?? []).filter((x) => Number.isFinite(x));
  if (b.length < MIN_BASELINE) return { anomalous: false, z: null, mean: null, lo: null, hi: null };
  const m = mean(b)!;
  const s = stddev(b);
  const lo = Math.min(...b);
  const hi = Math.max(...b);
  if (s == null || s === 0 || Math.max(m, cur) < minMean) return { anomalous: false, z: null, mean: m, lo, hi };
  const z = (cur - m) / s;
  return { anomalous: Math.abs(z) >= ANOMALY_Z && (cur > hi || cur < lo), z, mean: m, lo, hi };
}

/** Confidence for an absolute-count friction rule: "early" below the minimum sample. */
export function sampleConfidence(n: number, min = MIN_COUNT): "high" | "medium" | "early" {
  if (n >= Math.max(30, min * 3)) return "high";
  if (n >= min) return "medium";
  return "early";
}

