    offset = 0;
  } else if (cur) {
    offset = Number(cur.offset);
    if (offset > st.size) offset = 0; // truncated in place (copytruncate)
  }

  const chunk = await readChunk(LOG_PATH, offset);
  if (chunk && chunk.consumed > 0) {
    const s = await ingestLogText(chunk.text);
    total = { lines: s.lines, botHits: s.botHits };
    offset += chunk.consumed;
  }
  await db.crawlLogCursor.upsert({
    where: { id: LOG_PATH },
    create: { id: LOG_PATH, inode, offset: BigInt(offset) },
    update: { inode, offset: BigInt(offset) },
  });
  return total;
