// ---------------------------------------------------------------------------
// Automated reports (/admin/reports, lib/reports/*) — all additive, 2026-10-06.
// ---------------------------------------------------------------------------

/// Per-day occurrence counts for each ErrorLog fingerprint. ErrorLog itself is
/// a DEDUP store (one row per fingerprint with a lifetime `count`), so it can't
/// say "how many times did this happen last Tuesday". lib/log.ts `persist()`
/// bumps one row here per (UTC day, fingerprint) alongside the ErrorLog upsert.
/// PII-free by construction: no message/detail/user columns — join to ErrorLog
/// by fingerprint for the (already redacted) text.
model ErrorDaily {
  id          String   @id @default(cuid())
  date        DateTime // UTC midnight
  fingerprint String // ErrorLog.fingerprint
  context     String
  source      String
  level       String
  count       Int      @default(0)
  updatedAt   DateTime @default(now())

  @@unique([date, fingerprint])
  @@index([date])
  @@index([context, date])
}

/// Human (non-bot) HTTP 5xx responses per UTC day and route group, tallied by
/// the existing access-log sweep (lib/bots/crawler-ingest.ts). Route groups are
/// coarse (lib/reports/routes.ts `routeGroup`) — ids/slugs are collapsed so
/// this never stores a customer-identifying path.
model HttpErrorDaily {
  id        String   @id @default(cuid())
  date      DateTime // UTC midnight
  route     String // e.g. "/dashboard/deploy", "/dashboard/servers/:id", "/api/stripe/*"
  status    Int
  hits      Int      @default(0)
  updatedAt DateTime @default(now())

  @@unique([date, route, status])
  @@index([date])
}

/// One payment attempt outcome we learned about server-side (Stripe webhook
/// `payment_intent.payment_failed` today). Card data is limited to what a
/// receipt shows: brand + issuing country — never number, expiry or last4.
/// `message` is the processor's human text, secret-scrubbed and truncated.
model PaymentEvent {
  id          String   @id @default(cuid())
  createdAt   DateTime @default(now())
  provider    String // stripe | paypal | coinbase
  outcome     String // failed | succeeded | requires_action
  externalId  String   @unique // processor id (payment intent id), dedupes webhook redelivery
  userId      String?
  amountCents Int?
  currency    String?
  method      String? // card | link | upi | grabpay | …
  cardBrand   String?
  cardCountry String? // ISO-3166 alpha-2 of the issuing bank
  failureCode String? // Stripe last_payment_error.code
  declineCode String? // Stripe last_payment_error.decline_code
  threeDS     Boolean  @default(false) // failure happened at the 3-D Secure / authentication step
  message     String?

  @@index([createdAt])
  @@index([userId, createdAt])
}

/// A saved /admin/reports view (time frame + compare + time zone).
model ReportView {
  id        String   @id @default(cuid())
  ownerId   String
  name      String
  params    String // query string, e.g. "preset=30d&tz=Asia%2FSingapore"
  createdAt DateTime @default(now())

  @@index([ownerId])
}

/// A generated report snapshot: written by the optional digest sweep
/// (worker/report-digest.ts) and by "Save snapshot" on the page, so a past
/// report can be re-read exactly as it was generated.
model ReportRun {
  id          String    @id @default(cuid())
  periodFrom  DateTime
  periodTo    DateTime
  label       String
  trigger     String // digest-daily | digest-weekly | manual
  headline    String
  data        Json // { report: ReportData, summary: ReportSummary }
  generatedAt DateTime  @default(now())
  emailedAt   DateTime?

  @@unique([trigger, periodFrom])
  @@index([generatedAt])
}
