/**
 * Per-day occurrence counter for /admin/reports (ErrorDaily). ErrorLog only
 * knows a lifetime count per fingerprint; this one-row-per-(UTC day,
 * fingerprint) upsert is what lets a report say "this error happened 40 times
 * last week, 3 the week before". Stores no message/user data (the fingerprint
 * joins back to ErrorLog). Swallows its own failure — e.g. the table not yet
 * existing before the deploy's `db push` — so it can never break the logger.
 */
async function bumpErrorDaily(now: Date, fingerprint: string, context: string, source: string, level: string): Promise<void> {
  try {
    const day = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
    await db.$executeRaw`
      INSERT INTO "ErrorDaily" (id, date, fingerprint, context, source, level, count, "updatedAt")
      VALUES (${`ed_${fingerprint.slice(0, 20)}_${day.getTime()}`}, ${day}, ${fingerprint}, ${context.slice(0, 200)}, ${source}, ${level}, 1, now())
      ON CONFLICT (date, fingerprint) DO UPDATE SET count = "ErrorDaily".count + 1, "updatedAt" = now()`;
  } catch {
    /* best-effort: reports degrade to ErrorLog's lifetime counts */
  }
}

