/**
 * Coarse route groups for HTTP-error tallies (HttpErrorDaily) and the
 * "errors on deploy / payment paths" report rule. Pure.
 *
 * Every id-like or slug-like segment is collapsed, so a stored route can never
 * identify a customer or a server: "/dashboard/servers/cmuk25…/files" →
 * "/dashboard/servers/:id". Static assets and Next internals collapse to one
 * bucket each.
 */

const ID_SEG = /^(c[a-z0-9]{20,}|[0-9a-f]{8}-[0-9a-f-]{27,}|[0-9a-f]{16,}|\d+)$/i;

export function routeGroup(rawPath: string): string {
  let p = String(rawPath || "/").split("?")[0].split("#")[0];
  if (!p.startsWith("/")) p = `/${p}`;
  if (p.startsWith("/_next/static") || /\.(js|css|map|png|jpe?g|webp|svg|ico|woff2?|txt|xml)$/i.test(p)) return "(static)";
  if (p.startsWith("/_next")) return "/_next/*";
  const segs = p.split("/").filter(Boolean).slice(0, 4);
  if (segs.length === 0) return "/";
  const [a, b] = segs;
  if (a === "api") {
    // /api/<area>/* — the area is what matters ("/api/stripe/*", "/api/chat/*").
    return b ? `/api/${b.slice(0, 40)}/*` : "/api";
  }
  if (a === "dashboard" || a === "admin") {
    const out = [a];
    for (const s of segs.slice(1, 3)) out.push(ID_SEG.test(s) ? ":id" : s.slice(0, 40));
    // Anything below a server id is one bucket per server area, not per tab.
    return `/${out.join("/")}`;
  }
  // Marketing pages: first segment only (games/<slug> → /games/*).
  return segs.length > 1 ? `/${a.slice(0, 40)}/*` : `/${a.slice(0, 40)}`;
}

/**
 * Is this route (or an error context string) on the money path — signup,
 * deploy wizard, checkout, payment, order placement, provisioning?
 */
const MONEY_PATH = /(register|signup|login|deploy|checkout|order|pay|stripe|paypal|coinbase|billing|wallet|topup|top-up|provision|invoice|coupon|promo)/i;

export function isMoneyPath(routeOrContext: string): boolean {
  return MONEY_PATH.test(routeOrContext);
}

