/**
 * Server-side record of payment-attempt outcomes (PaymentEvent) so
 * /admin/reports can answer "why did people at the Payment step not pay?" —
 * declines by reason, card country and brand, and 3-D Secure failures. Before
 * this, a declined card left no trace in our database at all (Stripe's own
 * Checkout UI shows the decline to the customer and that was the end of it).
 *
 * Privacy: only brand + issuing country + the processor's codes are kept —
 * never the card number, last4 or expiry. Best-effort: never throws, so it can
 * never turn a webhook into a retry storm. Raw SQL so it works before and after
 * the Prisma client is regenerated at deploy.
 */
import { randomUUID } from "node:crypto";
import type Stripe from "stripe";
import { db } from "./db";
import { redactSecrets } from "./log";

export type PaymentEventInput = {
  provider: "stripe" | "paypal" | "coinbase";
  outcome: "failed" | "succeeded" | "requires_action";
  externalId: string;
  userId?: string | null;
  amountCents?: number | null;
  currency?: string | null;
  method?: string | null;
  cardBrand?: string | null;
  cardCountry?: string | null;
  failureCode?: string | null;
  declineCode?: string | null;
  threeDS?: boolean;
  message?: string | null;
};

const AUTH_CODES = new Set(["payment_intent_authentication_failure", "authentication_required"]);

/** Pure: map a failed Stripe PaymentIntent onto a PaymentEvent row. */
export function paymentEventFromStripeIntent(pi: Stripe.PaymentIntent, userId: string | null): PaymentEventInput {
  const err = pi.last_payment_error ?? null;
  const pm = (err?.payment_method ?? null) as Stripe.PaymentMethod | null;
  const card = pm && typeof pm === "object" ? pm.card ?? null : null;
  const code = err?.code ?? null;
  return {
    provider: "stripe",
    outcome: "failed",
    externalId: `${pi.id}:${(err as { request_log_url?: string } | null)?.request_log_url ? "" : ""}${pi.latest_charge && typeof pi.latest_charge === "string" ? pi.latest_charge : pi.id}`,
    userId,
    amountCents: typeof pi.amount === "number" ? pi.amount : null,
    currency: pi.currency ?? null,
    method: (pm && typeof pm === "object" ? pm.type : null) ?? err?.payment_method_type ?? (pi.payment_method_types?.[0] ?? null),
    cardBrand: card?.brand ?? null,
    cardCountry: card?.country ? card.country.toUpperCase() : null,
    failureCode: code,
    declineCode: err?.decline_code ?? null,
    threeDS: code ? AUTH_CODES.has(code) : false,
    message: err?.message ?? null,
  };
}

export async function recordPaymentEvent(e: PaymentEventInput): Promise<void> {
  try {
    const message = e.message ? redactSecrets(e.message).slice(0, 300) : null;
    await db.$executeRaw`
      INSERT INTO "PaymentEvent" (id, "createdAt", provider, outcome, "externalId", "userId", "amountCents", currency, method, "cardBrand", "cardCountry", "failureCode", "declineCode", "threeDS", message)
      VALUES (${randomUUID()}, now(), ${e.provider}, ${e.outcome}, ${e.externalId.slice(0, 200)}, ${e.userId ?? null}, ${e.amountCents ?? null}, ${e.currency ?? null},
              ${e.method?.slice(0, 40) ?? null}, ${e.cardBrand?.slice(0, 30) ?? null}, ${e.cardCountry?.slice(0, 2) ?? null},
              ${e.failureCode?.slice(0, 80) ?? null}, ${e.declineCode?.slice(0, 80) ?? null}, ${e.threeDS ?? false}, ${message})
      ON CONFLICT ("externalId") DO NOTHING`;
  } catch (err) {
    console.error("[payment-events] record failed", (err as Error)?.message ?? err);
  }
}

