/**
 * Report aggregation: acquisition, signups, deploy funnel. Every query is
 * bot-free (Visit.isBot = false + the admin-excluded IPs) and counts only real
 * customers (lib/reports/sql.ts realUser).
 */
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { excludedIps } from "@/lib/analytics";
import { percentile } from "@/lib/insights/stats";
import { channelOf, cleanLanding } from "./classify";
import { realUser, realCashIn, revenueDebit, type Span } from "./sql";
import type { ReportRange } from "./range";
import type { FrictionInputs, Metric, ProductFunnel, Ranked, ReportSection } from "./types";

const DAY = 86_400_000;

function selfHosts(): string[] {
  const out = new Set<string>(["nxeon.cloud"]);
  for (const v of [process.env.APP_URL, process.env.NXEON_ADMIN_HOST]) {
    try {
      if (v) out.add(new URL(v.startsWith("http") ? v : `https://${v}`).hostname.replace(/^www\./, ""));
    } catch {
      /* ignore */
    }
  }
  return [...out];
}

async function ipEx(): Promise<string[]> {
  try {
    const ips = await excludedIps();
    return ips.length ? ips : ["0.0.0.0"];
  } catch {
    return ["0.0.0.0"];
  }
}

// ---------------------------------------------------------------------------
// Acquisition
// ---------------------------------------------------------------------------

type VisitTotals = { pv: number; vis: number; ses: number };

async function visitTotals(s: Span, ips: string[]): Promise<VisitTotals> {
  const [r] = await db.$queryRaw<VisitTotals[]>`
    SELECT count(*)::int AS pv, count(DISTINCT coalesce("visitorId", ip))::int AS vis, count(DISTINCT "sessionId")::int AS ses
    FROM "Visit" WHERE "createdAt" >= ${s.from} AND "createdAt" < ${s.to} AND "isBot" = false AND ip <> ALL(${ips})`;
  return r ?? { pv: 0, vis: 0, ses: 0 };
}

async function channelCounts(s: Span, ips: string[]): Promise<Map<string, number>> {
  const rows = await db.$queryRaw<{ host: string | null; us: string | null; um: string | null; g: boolean; n: number }[]>`
    SELECT substring(referrer from '^[a-zA-Z]+://([^/?#:]+)') AS host, "utmSource" AS us, "utmMedium" AS um, (gclid IS NOT NULL) AS g, count(*)::int AS n
    FROM "Visit" WHERE "isEntry" = true AND "createdAt" >= ${s.from} AND "createdAt" < ${s.to} AND "isBot" = false AND ip <> ALL(${ips})
    GROUP BY 1, 2, 3, 4`;
  const hosts = selfHosts();
  const m = new Map<string, number>();
  for (const r of rows) {
    const c = channelOf({ host: r.host?.replace(/^www\./, "") ?? null, utmSource: r.us, utmMedium: r.um, gclid: r.g }, hosts);
    m.set(c, (m.get(c) ?? 0) + r.n);
  }
  return m;
}

async function groupDistinct(s: Span, ips: string[], col: "deviceType" | "country"): Promise<Map<string, number>> {
  const c = Prisma.raw(`"${col}"`);
  const rows = await db.$queryRaw<{ k: string | null; n: number }[]>`
    SELECT ${c} AS k, count(DISTINCT coalesce("visitorId", ip))::int AS n
    FROM "Visit" WHERE "createdAt" >= ${s.from} AND "createdAt" < ${s.to} AND "isBot" = false AND ip <> ALL(${ips})
    GROUP BY 1 ORDER BY 2 DESC LIMIT 25`;
  return new Map(rows.map((r) => [r.k ?? "Unknown", r.n]));
}

async function landingCounts(s: Span, ips: string[]): Promise<Map<string, number>> {
  const rows = await db.$queryRaw<{ p: string; n: number }[]>`
    SELECT split_part(path, '?', 1) AS p, count(*)::int AS n
    FROM "Visit" WHERE "isEntry" = true AND "createdAt" >= ${s.from} AND "createdAt" < ${s.to} AND "isBot" = false AND ip <> ALL(${ips})
    GROUP BY 1 ORDER BY 2 DESC LIMIT 200`;
  const m = new Map<string, number>();
  for (const r of rows) {
    const k = cleanLanding(r.p);
    m.set(k, (m.get(k) ?? 0) + r.n);
  }
  return m;
}

function rankedFrom(cur: Map<string, number>, prev: Map<string, number> | null, limit = 10): Ranked[] {
  return [...cur.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([label, value]) => ({ label, value, prev: prev ? prev.get(label) ?? 0 : undefined }));
}

export async function collectAcquisition(r: ReportRange): Promise<{ section: ReportSection; channels: Map<string, number>; prevChannels: Map<string, number> }> {
  const ips = await ipEx();
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [tc, tp, base, chC, chP, devC, devP, ctyC, ctyP, lpC, lpP] = await Promise.all([
    visitTotals(cur, ips),
    visitTotals(prev, ips),
    Promise.all(r.baseline.map((b) => visitTotals(b, ips))),
    channelCounts(cur, ips),
    channelCounts(prev, ips),
    groupDistinct(cur, ips, "deviceType"),
    groupDistinct(prev, ips, "deviceType"),
    groupDistinct(cur, ips, "country"),
    groupDistinct(prev, ips, "country"),
    landingCounts(cur, ips),
    landingCounts(prev, ips),
  ]);
  const metrics: Metric[] = [
    { key: "visitors", domain: "acquisition", label: "Unique visitors", unit: "count", cur: tc.vis, prev: tp.vis, baseline: base.map((b) => b.vis), higherIsBetter: true, drill: "/admin/visitors" },
    { key: "sessions", domain: "acquisition", label: "Sessions", unit: "count", cur: tc.ses, prev: tp.ses, baseline: base.map((b) => b.ses), higherIsBetter: true },
    { key: "pageviews", domain: "acquisition", label: "Page views", unit: "count", cur: tc.pv, prev: tp.pv, baseline: base.map((b) => b.pv), higherIsBetter: true },
  ];
  return {
    section: {
      domain: "acquisition",
      metrics,
      tables: [],
      ranked: [
        { key: "channels", title: "Landing visits by channel", rows: rankedFrom(chC, chP, 12) },
        { key: "landing", title: "Top landing pages", rows: rankedFrom(lpC, lpP, 12) },
        { key: "devices", title: "Visitors by device", rows: rankedFrom(devC, devP, 6) },
        { key: "countries", title: "Visitors by country", rows: rankedFrom(ctyC, ctyP, 10) },
      ],
      notes: ["Bot traffic and admin-excluded IPs are removed from every number here."],
    },
    channels: chC,
    prevChannels: chP,
  };
}

// ---------------------------------------------------------------------------
// Signups (+ first-touch segments) and activation
// ---------------------------------------------------------------------------

type SignupRow = {
  id: string;
  createdAt: Date;
  google: boolean;
  verifiedAt: Date | null;
  billingCountry: string | null;
  heardAboutUs: string | null;
  firstDeploy: Date | null;
  paid: boolean;
};

async function signupRows(s: Span): Promise<SignupRow[]> {
  return db.$queryRaw<SignupRow[]>`
    WITH s AS (
      SELECT u.id, u."createdAt", (u."googleId" IS NOT NULL) AS google, u."emailVerifiedAt" AS "verifiedAt", u."billingCountry", u."heardAboutUs"
      FROM "User" u WHERE ${realUser("u")} AND u."createdAt" >= ${s.from} AND u."createdAt" < ${s.to}
    )
    SELECT s.*,
      (SELECT min(t) FROM (
         SELECT min(x."createdAt") AS t FROM "Server" x WHERE x."userId" = s.id
         UNION ALL SELECT min(a."provisionedAt") FROM "ServerArchive" a WHERE a."userId" = s.id
         UNION ALL SELECT min(f."createdAt") FROM "FreeMinecraftServer" f WHERE f."userId" = s.id
      ) z) AS "firstDeploy",
      (EXISTS (SELECT 1 FROM "WalletTransaction" w WHERE w."userId" = s.id AND ${realCashIn("w")})
        OR EXISTS (SELECT 1 FROM "WalletTransaction" w WHERE w."userId" = s.id AND ${revenueDebit("w")})) AS paid
    FROM s
    LIMIT 50000`;
}

type Touch = { userId: string; path: string; host: string | null; us: string | null; um: string | null; g: boolean; device: string | null; country: string | null };

/** First-touch landing visit for each user: by visitorId (pre-signup visits) or, failing that, their own earliest visit. */
async function firstTouches(ids: string[]): Promise<Map<string, Touch>> {
  if (!ids.length) return new Map();
  const rows = await db.$queryRaw<Touch[]>`
    WITH ids AS (SELECT unnest(${ids}::text[]) AS uid),
    vids AS (SELECT DISTINCT v."userId" AS uid, v."visitorId" FROM "Visit" v JOIN ids ON ids.uid = v."userId" WHERE v."visitorId" IS NOT NULL),
    cand AS (
      SELECT vids.uid, v.path, v.referrer, v."utmSource", v."utmMedium", v.gclid, v."deviceType", v.country, v."createdAt"
      FROM vids JOIN "Visit" v ON v."visitorId" = vids."visitorId" WHERE v."isBot" = false
      UNION ALL
      SELECT ids.uid, v.path, v.referrer, v."utmSource", v."utmMedium", v.gclid, v."deviceType", v.country, v."createdAt"
      FROM ids JOIN "Visit" v ON v."userId" = ids.uid WHERE v."isBot" = false
    )
    SELECT DISTINCT ON (uid) uid AS "userId", path, substring(referrer from '^[a-zA-Z]+://([^/?#:]+)') AS host,
      "utmSource" AS us, "utmMedium" AS um, (gclid IS NOT NULL) AS g, "deviceType" AS device, country
    FROM cand ORDER BY uid, "createdAt" ASC`;
  return new Map(rows.map((t) => [t.userId, t]));
}

export type SegmentRow = { segment: string; key: string; signups: number; activated: number; paid: number; userIds: string[] };

function segmentize(rows: SignupRow[], touch: Map<string, Touch>): SegmentRow[] {
  const hosts = selfHosts();
  const out = new Map<string, SegmentRow>();
  const add = (segment: string, key: string, r: SignupRow) => {
    const k = `${segment}|${key}`;
    const e = out.get(k) ?? { segment, key, signups: 0, activated: 0, paid: 0, userIds: [] };
    e.signups++;
    if (r.firstDeploy) e.activated++;
    if (r.paid) e.paid++;
    if (e.userIds.length < 200) e.userIds.push(r.id);
    out.set(k, e);
  };
  for (const r of rows) {
    const t = touch.get(r.id);
    add("Landing page", t ? cleanLanding(t.path) : "Unknown", r);
    add("Channel", t ? channelOf({ host: t.host?.replace(/^www\./, "") ?? null, utmSource: t.us, utmMedium: t.um, gclid: t.g }, hosts) : "Unknown", r);
    add("Device", t?.device ?? "Unknown", r);
    add("Country", r.billingCountry ?? t?.country ?? "Unknown", r);
    add("Sign-in method", r.google ? "Google" : "Email & password", r);
  }
  return [...out.values()].sort((a, b) => b.signups - a.signups);
}

async function signupCount(s: Span): Promise<number> {
  const [r] = await db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "User" u WHERE ${realUser("u")} AND u."createdAt" >= ${s.from} AND u."createdAt" < ${s.to}`;
  return r?.n ?? 0;
}

export async function collectSignups(
  r: ReportRange,
): Promise<{ section: ReportSection; segments: SegmentRow[]; verification: FrictionInputs["verification"]; activation: FrictionInputs["activation"]; devices: FrictionInputs["devices"]; internalUnflagged: number }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [sc, sp, base, verifyMail, internal] = await Promise.all([
    signupRows(cur),
    signupRows(prev),
    Promise.all(r.baseline.map((b) => signupCount(b))),
    db.$queryRaw<{ status: string; n: number }[]>`
      SELECT status, count(*)::int AS n FROM "EmailLog" WHERE template = 'email_verify' AND "createdAt" >= ${r.from} AND "createdAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ n: number }[]>`
      SELECT count(*)::int AS n FROM "User" u WHERE u.role::text = 'CUSTOMER' AND u."excludeFromRevenue" = false AND NOT ${realUser("u")}`,
  ]);
  const touch = await firstTouches(sc.map((s) => s.id));
  const segments = segmentize(sc, touch);

  // Verification: only email/password signups old enough (24h) to have had the chance.
  const cutoff = (s: Span) => new Date(Math.min(s.to.getTime(), Date.now()) - DAY);
  const elig = (rows: SignupRow[], s: Span) => rows.filter((x) => !x.google && x.createdAt < cutoff(s));
  const ec = elig(sc, cur);
  const ep = elig(sp, prev);
  const verification: FrictionInputs["verification"] = {
    eligible: ec.length,
    unverified: ec.filter((x) => !x.verifiedAt).length,
    prevEligible: ep.length,
    prevUnverified: ep.filter((x) => !x.verifiedAt).length,
    verifyEmailsSent: verifyMail.reduce((a, b) => a + b.n, 0),
    verifyEmailsFailed: verifyMail.filter((v) => v.status === "FAILED").reduce((a, b) => a + b.n, 0),
    unverifiedUserIds: ec.filter((x) => !x.verifiedAt).map((x) => x.id).slice(0, 500),
  };
  const hours = sc.filter((x) => x.firstDeploy && x.firstDeploy >= x.createdAt).map((x) => (x.firstDeploy!.getTime() - x.createdAt.getTime()) / 3_600_000);
  const activation: FrictionInputs["activation"] = {
    signups: sc.length,
    activated: sc.filter((x) => x.firstDeploy).length,
    prevSignups: sp.length,
    prevActivated: sp.filter((x) => x.firstDeploy).length,
    medianHoursToDeploy: percentile(hours, 50),
  };
  const devices = segments
    .filter((s) => s.segment === "Device")
    .map((s) => ({ device: s.key, visitors: 0, signups: s.signups, payers: s.paid }));

  const google = sc.filter((x) => x.google).length;
  const paid = sc.filter((x) => x.paid).length;
  const prevPaid = sp.filter((x) => x.paid).length;
  const metrics: Metric[] = [
    { key: "signups", domain: "signups", label: "New accounts", unit: "count", cur: sc.length, prev: sp.length, baseline: base, higherIsBetter: true, drill: "signups" },
    { key: "google_share", domain: "signups", label: "Signed up with Google", unit: "ratio", cur: sc.length ? google / sc.length : null, prev: sp.length ? sp.filter((x) => x.google).length / sp.length : null, num: google, den: sc.length, prevNum: sp.filter((x) => x.google).length, prevDen: sp.length, higherIsBetter: true },
    { key: "verify_rate", domain: "signups", label: "Email signups verified (24h+ old)", unit: "ratio", cur: ec.length ? (ec.length - verification.unverified) / ec.length : null, prev: ep.length ? (ep.length - verification.prevUnverified) / ep.length : null, num: ec.length - verification.unverified, den: ec.length, prevNum: ep.length - verification.prevUnverified, prevDen: ep.length, higherIsBetter: true, drill: "unverified" },
    { key: "activation_rate", domain: "signups", label: "New accounts that deployed anything", unit: "ratio", cur: sc.length ? activation.activated / sc.length : null, prev: sp.length ? activation.prevActivated / sp.length : null, num: activation.activated, den: sc.length, prevNum: activation.prevActivated, prevDen: sp.length, higherIsBetter: true, drill: "unactivated" },
    { key: "signup_paid_rate", domain: "signups", label: "New accounts that have paid", unit: "ratio", cur: sc.length ? paid / sc.length : null, prev: sp.length ? prevPaid / sp.length : null, num: paid, den: sc.length, prevNum: prevPaid, prevDen: sp.length, higherIsBetter: true, note: "Counted up to now, so a recent period has had less time to convert." },
  ];
  const segTable = (segment: string) => {
    const rows = segments.filter((s) => s.segment === segment).slice(0, 12);
    return {
      key: `seg_${segment}`,
      title: `Signups by ${segment.toLowerCase()}`,
      head: [segment, "Signups", "Deployed", "Paid", "Paid %"],
      rows: rows.map((s) => [s.key, s.signups, s.activated, s.paid, s.signups ? `${Math.round((s.paid / s.signups) * 100)}%` : "—"]),
    };
  };
  return {
    section: {
      domain: "signups",
      metrics,
      tables: [segTable("Channel"), segTable("Landing page"), segTable("Device"), segTable("Country"), segTable("Sign-in method")],
      ranked: [],
      notes: [
        "Segments use each account's first-touch landing visit (joined by the visitor cookie, so pre-signup visits count). 'Deployed' includes free servers; 'Paid' is a real card/PayPal/crypto payment or earned revenue, up to now.",
        "Internal QA accounts (e-mail ending .test/.local/.invalid/example.*) are excluded even when not flagged.",
      ],
    },
    segments,
    verification,
    activation,
    devices,
    internalUnflagged: internal[0]?.n ?? 0,
  };
}

// ---------------------------------------------------------------------------
// Deploy funnel
// ---------------------------------------------------------------------------

type Ev = { product: string; type: string; step: string; stepIndex: number; sid: string; userId: string | null; errorCode: string | null; msg: string | null; detail: string | null };

async function funnelEvents(s: Span): Promise<Ev[]> {
  return db.$queryRaw<Ev[]>`
    SELECT e.product, e.type, e.step, e."stepIndex", coalesce(e."sessionId", e.id) AS sid, e."userId", e."errorCode", left(e."errorMessage", 300) AS msg, e.detail
    FROM "DeployFunnelEvent" e LEFT JOIN "User" u ON u.id = e."userId"
    WHERE e."createdAt" >= ${s.from} AND e."createdAt" < ${s.to} AND (e."userId" IS NULL OR ${realUser("u")})
    LIMIT 200000`;
}

function parseDetail(d: string | null): Record<string, unknown> {
  if (!d) return {};
  try {
    const v = JSON.parse(d);
    return v && typeof v === "object" ? (v as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

export type SessionInfo = { device: string | null; country: string | null };

async function sessionInfo(sids: string[]): Promise<Map<string, SessionInfo>> {
  if (!sids.length) return new Map();
  const rows = await db.$queryRaw<{ sid: string; device: string | null; country: string | null }[]>`
    SELECT DISTINCT ON ("sessionId") "sessionId" AS sid, "deviceType" AS device, country
    FROM "Visit" WHERE "sessionId" = ANY(${sids}::text[]) ORDER BY "sessionId", "createdAt" ASC`;
  return new Map(rows.map((r) => [r.sid, { device: r.device, country: r.country }]));
}

type Agg = {
  funnels: ProductFunnel[];
  /** per product: per device: { reachedByIndex } */
  deviceSteps: { product: string; device: string; steps: { index: number; reached: number }[] }[];
  paymentByCountry: { country: string; reached: number; completed: number }[];
  soldOut: FrictionInputs["soldOut"];
  orderErrors: FrictionInputs["orderErrors"];
  provisionFails: { userId: string | null; game: string | null; nodeId: string | null; serverId: string | null; msg: string | null }[];
  gamesPicked: Map<string, number>;
};

function aggregate(evs: Ev[], info: Map<string, SessionInfo> | null): Agg {
  const byProduct = new Map<string, Ev[]>();
  for (const e of evs) {
    if (!["vps", "game", "hosting", "email"].includes(e.product)) continue;
    const a = byProduct.get(e.product) ?? [];
    a.push(e);
    byProduct.set(e.product, a);
  }
  const funnels: ProductFunnel[] = [];
  const deviceSteps: Agg["deviceSteps"] = [];
  const payCountry = new Map<string, { reached: number; completed: number }>();
  const orderErr = new Map<string, { message: string; count: number; product: string }>();
  const provisionFails: Agg["provisionFails"] = [];
  const gamesPicked = new Map<string, number>();
  let shown = 0;
  let shownDone = 0;
  const picks = new Map<string, number>();
  let soldOutInstrumented = false;

  for (const [product, list] of byProduct) {
    const sessions = new Set<string>();
    const completed = new Set<string>();
    const reachedAt = new Map<number, Set<string>>();
    const labelsAt = new Map<number, Map<string, number>>();
    const erroredAt = new Map<number, number>();
    const paySessions = new Set<string>();
    const sessionUser = new Map<string, string>();
    const soldShown = new Set<string>();
    const errs = new Map<string, { code: string; message: string; count: number }>();
    for (const e of list) {
      if (e.userId) sessionUser.set(e.sid, e.userId);
      if (e.type === "step") {
        sessions.add(e.sid);
        const set = reachedAt.get(e.stepIndex) ?? new Set<string>();
        set.add(e.sid);
        reachedAt.set(e.stepIndex, set);
        const lm = labelsAt.get(e.stepIndex) ?? new Map<string, number>();
        lm.set(e.step, (lm.get(e.step) ?? 0) + 1);
        labelsAt.set(e.stepIndex, lm);
        if (/^payment$/i.test(e.step)) paySessions.add(e.sid);
      } else if (e.type === "complete") {
        completed.add(e.sid);
        sessions.add(e.sid);
      } else if (e.type === "error") {
        if (e.errorCode === "PROVISION_FAILED") {
          const d = parseDetail(e.detail);
          provisionFails.push({ userId: e.userId, game: typeof d.game === "string" ? d.game : null, nodeId: typeof d.nodeId === "string" ? d.nodeId : null, serverId: typeof d.serverId === "string" ? d.serverId : null, msg: e.msg });
          continue;
        }
        erroredAt.set(e.stepIndex, (erroredAt.get(e.stepIndex) ?? 0) + 1);
        const key = `${e.errorCode ?? ""}|${(e.msg ?? "").slice(0, 120)}`;
        const x = errs.get(key) ?? { code: e.errorCode ?? "ERROR", message: (e.msg ?? "").slice(0, 200), count: 0 };
        x.count++;
        errs.set(key, x);
        if (e.errorCode === "ORDER_ERROR" && e.msg) {
          const ok = `${product}|${e.msg.slice(0, 160)}`;
          const o = orderErr.get(ok) ?? { message: e.msg.slice(0, 200), count: 0, product };
          o.count++;
          orderErr.set(ok, o);
        }
      } else if (e.type === "select") {
        const d = parseDetail(e.detail);
        if (e.step === "region_sold_out_shown") {
          soldOutInstrumented = true;
          soldShown.add(e.sid);
        } else if (e.step === "region" && (d.availability === "sold_out" || d.availability === "limited")) {
          soldOutInstrumented = true;
          const k = `${String(d.value ?? "?")} (${d.availability === "sold_out" ? "sold out" : "limited"})`;
          picks.set(k, (picks.get(k) ?? 0) + 1);
        } else if (e.step === "game" && typeof d.value === "string") {
          gamesPicked.set(d.value, (gamesPicked.get(d.value) ?? 0) + 1);
        }
      }
    }
    shown += soldShown.size;
    for (const s of soldShown) if (completed.has(s)) shownDone++;
    const steps = [...reachedAt.entries()]
      .sort((a, b) => a[0] - b[0])
      .map(([index, set]) => {
        const labels = [...(labelsAt.get(index)?.entries() ?? [])].sort((a, b) => b[1] - a[1]).map(([l]) => l);
        return { step: labels.slice(0, 2).join(" / "), index, reached: set.size, errored: erroredAt.get(index) ?? 0 };
      });
    const left = [...paySessions].filter((s) => !completed.has(s));
    funnels.push({
      product,
      sessions: sessions.size,
      completed: completed.size,
      prevSessions: 0,
      prevCompleted: 0,
      steps,
      paymentReached: paySessions.size,
      paymentLeft: left.length,
      prevPaymentReached: 0,
      prevPaymentLeft: 0,
      paymentLeftUserIds: [...new Set(left.map((s) => sessionUser.get(s)).filter((u): u is string => !!u))].slice(0, 500),
      topErrors: [...errs.values()].sort((a, b) => b.count - a.count).slice(0, 5),
    });
    if (info) {
      const devMap = new Map<string, Map<number, Set<string>>>();
      for (const [index, set] of reachedAt) {
        for (const sid of set) {
          const dev = info.get(sid)?.device ?? "Unknown";
          const m = devMap.get(dev) ?? new Map<number, Set<string>>();
          const ss = m.get(index) ?? new Set<string>();
          ss.add(sid);
          m.set(index, ss);
          devMap.set(dev, m);
        }
      }
      for (const [device, m] of devMap)
        deviceSteps.push({ product, device, steps: [...m.entries()].sort((a, b) => a[0] - b[0]).map(([index, s]) => ({ index, reached: s.size })) });
      for (const sid of paySessions) {
        const c = info.get(sid)?.country ?? "Unknown";
        const e = payCountry.get(c) ?? { reached: 0, completed: 0 };
        e.reached++;
        if (completed.has(sid)) e.completed++;
        payCountry.set(c, e);
      }
    }
  }
  return {
    funnels: funnels.sort((a, b) => b.sessions - a.sessions),
    deviceSteps,
    paymentByCountry: [...payCountry.entries()].map(([country, v]) => ({ country, ...v })).sort((a, b) => b.reached - a.reached),
    soldOut: { sessionsShown: shown, sessionsShownCompleted: shownDone, picks: [...picks.entries()].map(([region, count]) => ({ region, count })).sort((a, b) => b.count - a.count), instrumented: soldOutInstrumented },
    orderErrors: [...orderErr.values()].sort((a, b) => b.count - a.count).slice(0, 10),
    provisionFails,
    gamesPicked,
  };
}

export async function collectFunnel(r: ReportRange): Promise<{ section: ReportSection; agg: Agg; prevAgg: Agg }> {
  const [ec, ep, baseCounts] = await Promise.all([
    funnelEvents({ from: r.from, to: r.to }),
    funnelEvents({ from: r.prevFrom, to: r.prevTo }),
    Promise.all(
      r.baseline.map((b) =>
        db.$queryRaw<{ n: number }[]>`SELECT count(DISTINCT coalesce("sessionId", id))::int AS n FROM "DeployFunnelEvent" WHERE type = 'complete' AND "createdAt" >= ${b.from} AND "createdAt" < ${b.to}`.then((x) => x[0]?.n ?? 0),
      ),
    ),
  ]);
  const sids = [...new Set(ec.map((e) => e.sid))].slice(0, 20_000);
  const info = await sessionInfo(sids);
  const agg = aggregate(ec, info);
  const prevAgg = aggregate(ep, null);
  for (const f of agg.funnels) {
    const p = prevAgg.funnels.find((x) => x.product === f.product);
    if (p) {
      f.prevSessions = p.sessions;
      f.prevCompleted = p.completed;
      f.prevPaymentReached = p.paymentReached;
      f.prevPaymentLeft = p.paymentLeft;
    }
  }
  const tot = (a: Agg, k: "sessions" | "completed" | "paymentReached" | "paymentLeft") => a.funnels.reduce((s, f) => s + f[k], 0);
  const metrics: Metric[] = [
    { key: "wizard_sessions", domain: "funnel", label: "Wizard sessions", unit: "count", cur: tot(agg, "sessions"), prev: tot(prevAgg, "sessions"), higherIsBetter: true, drill: "/admin/deploy-funnel" },
    { key: "wizard_completed", domain: "funnel", label: "Wizard sessions that ordered", unit: "count", cur: tot(agg, "completed"), prev: tot(prevAgg, "completed"), baseline: baseCounts, higherIsBetter: true },
    {
      key: "wizard_completion",
      domain: "funnel",
      label: "Wizard completion rate",
      unit: "ratio",
      cur: tot(agg, "sessions") ? tot(agg, "completed") / tot(agg, "sessions") : null,
      prev: tot(prevAgg, "sessions") ? tot(prevAgg, "completed") / tot(prevAgg, "sessions") : null,
      num: tot(agg, "completed"),
      den: tot(agg, "sessions"),
      prevNum: tot(prevAgg, "completed"),
      prevDen: tot(prevAgg, "sessions"),
      higherIsBetter: true,
    },
    {
      key: "payment_conversion",
      domain: "funnel",
      label: "Reached Payment → ordered",
      unit: "ratio",
      cur: tot(agg, "paymentReached") ? 1 - tot(agg, "paymentLeft") / tot(agg, "paymentReached") : null,
      prev: tot(prevAgg, "paymentReached") ? 1 - tot(prevAgg, "paymentLeft") / tot(prevAgg, "paymentReached") : null,
      num: tot(agg, "paymentReached") - tot(agg, "paymentLeft"),
      den: tot(agg, "paymentReached"),
      prevNum: tot(prevAgg, "paymentReached") - tot(prevAgg, "paymentLeft"),
      prevDen: tot(prevAgg, "paymentReached"),
      higherIsBetter: true,
      drill: "payment_leavers",
    },
  ];
  const tables: ReportSection["tables"] = agg.funnels.map((f) => ({
    key: `funnel_${f.product}`,
    title: `${f.product.toUpperCase()} wizard — sessions reaching each step`,
    head: ["#", "Step", "Sessions", "Kept from previous step", "Errors"],
    rows: f.steps.map((s, i) => [s.index, s.step, s.reached, i === 0 || !f.steps[i - 1].reached ? "—" : `${Math.round((s.reached / f.steps[i - 1].reached) * 100)}%`, s.errored]).concat([["", "Ordered", f.completed, f.steps.length && f.steps[f.steps.length - 1].reached ? `${Math.round((f.completed / f.steps[f.steps.length - 1].reached) * 100)}%` : "—", ""]]),
  }));
  if (agg.paymentByCountry.length)
    tables.push({
      key: "pay_country",
      title: "Reached Payment → ordered, by country",
      head: ["Country", "Reached Payment", "Ordered", "Rate"],
      rows: agg.paymentByCountry.slice(0, 15).map((c) => [c.country, c.reached, c.completed, c.reached ? `${Math.round((c.completed / c.reached) * 100)}%` : "—"]),
    });
  if (agg.orderErrors.length)
    tables.push({ key: "order_errors", title: "Order-step errors customers saw", head: ["Wizard", "Message", "Times"], rows: agg.orderErrors.map((o) => [o.product, o.message, o.count]) });
  return {
    section: {
      domain: "funnel",
      metrics,
      tables,
      ranked: [{ key: "games", title: "Games picked in the wizard", rows: rankedFrom(agg.gamesPicked, prevAgg.gamesPicked, 10) }],
      notes: [
        "Sessions are browser tabs (per-tab session id), counted once per step they reached. Two wizard generations share step indexes, so a step label can read 'A / B'.",
        "'Ordered' = a complete event; a server-side provisioning failure is counted under Provisioning, not here.",
      ],
    },
    agg,
    prevAgg,
  };
}

