/**
 * Report aggregation: orders & revenue, payments, retention & churn. Reuses
 * the audited lib/insights/* figures (MRR, earned revenue, cash in, churn) so
 * a number in a report never disagrees with the same number on /admin/insights.
 */
import { db } from "@/lib/db";
import { revenueInsights, churnInsights } from "@/lib/insights/revenue";
import { paymentInsights, partnerInsights } from "@/lib/insights/growth";
import { orderKind, productOf, normalizeMessage } from "./classify";
import { realUser, realCashIn, revenueDebit, type Span } from "./sql";
import type { ReportRange } from "./range";
import { localDayKeys, bucketOf } from "./range";
import type { FrictionInputs, GroupRate, Metric, Ranked, ReportSection } from "./types";

const DAY = 86_400_000;

type Debit = { id: string; userId: string; amountCents: number; description: string; createdAt: Date };

async function debits(s: Span): Promise<Debit[]> {
  return db.$queryRaw<Debit[]>`
    SELECT w.id, w."userId", -w."amountCents" AS "amountCents", w.description, w."createdAt"
    FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${revenueDebit("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to}
    ORDER BY w."createdAt" ASC LIMIT 100000`;
}

async function cashIn(s: Span): Promise<{ n: number; cents: number; users: number }> {
  const [r] = await db.$queryRaw<{ n: number; cents: number; users: number }[]>`
    SELECT count(*)::int AS n, coalesce(sum(w."amountCents"), 0)::int AS cents, count(DISTINCT w."userId")::int AS users
    FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${realCashIn("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to}`;
  return r ?? { n: 0, cents: 0, users: 0 };
}

/** First-ever revenue debit per user (to tell a new paying customer from a returning one). */
async function firstDebitAt(userIds: string[]): Promise<Map<string, Date>> {
  if (!userIds.length) return new Map();
  const rows = await db.$queryRaw<{ userId: string; t: Date }[]>`
    SELECT w."userId", min(w."createdAt") AS t FROM "WalletTransaction" w
    WHERE w."userId" = ANY(${userIds}::text[]) AND ${revenueDebit("w")} GROUP BY 1`;
  return new Map(rows.map((r) => [r.userId, r.t]));
}

export async function collectRevenue(r: ReportRange): Promise<{ section: ReportSection; avgOrderCents: number | null; arpuCents: number | null; payingCustomers: number; promo: FrictionInputs["promoRenewals"] }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [dc, dp, base, cc, cp, rev, recent, coupons, promos, partners, mrrSnaps] = await Promise.all([
    debits(cur),
    debits(prev),
    Promise.all(r.baseline.map((b) => debits(b).then((d) => d.reduce((a, x) => a + x.amountCents, 0)))),
    cashIn(cur),
    cashIn(prev),
    revenueInsights(r),
    // Average NEW order over the 90 days up to the end of the period: the engine's "what is one customer worth".
    debits({ from: new Date(r.to.getTime() - 90 * DAY), to: r.to }),
    db.$queryRaw<{ code: string; n: number; cents: number }[]>`
      SELECT c.code, count(*)::int AS n, coalesce(sum(cr."amountCents"), 0)::int AS cents
      FROM "CouponRedemption" cr JOIN "Coupon" c ON c.id = cr."couponId" JOIN "User" u ON u.id = cr."userId"
      WHERE cr.state = 'CONSUMED' AND ${realUser("u")} AND cr."createdAt" >= ${r.from} AND cr."createdAt" < ${r.to}
      GROUP BY 1 ORDER BY 2 DESC`,
    db.$queryRaw<{ campaign: string; n: number; renewed: number; due: number; dueRenewed: number }[]>`
      SELECT coalesce(nullif(p.campaign, ''), 'first-month-free') AS campaign,
        count(*) FILTER (WHERE p."createdAt" >= ${r.from} AND p."createdAt" < ${r.to})::int AS n,
        count(*) FILTER (WHERE p.renewed AND p."renewedAt" >= ${r.from} AND p."renewedAt" < ${r.to})::int AS renewed,
        count(*) FILTER (WHERE p."createdAt" < now() - interval '35 days')::int AS due,
        count(*) FILTER (WHERE p."createdAt" < now() - interval '35 days' AND p.renewed)::int AS "dueRenewed"
      FROM "PromoRedemption" p JOIN "User" u ON u.id = p."userId"
      WHERE p.state = 'CONSUMED' AND ${realUser("u")} GROUP BY 1`,
    partnerInsights(r).catch(() => null),
    db.insightsSnapshot.findMany({ where: { metric: "mrr_cents", scopeId: "", date: { gte: new Date(r.from.getTime() - 2 * DAY), lte: r.to } }, orderBy: { date: "asc" } }).catch(() => []),
  ]);
  const sum = (d: Debit[], f?: (x: Debit) => boolean) => d.filter((x) => !f || f(x)).reduce((a, x) => a + x.amountCents, 0);
  const isNew = (x: Debit) => orderKind(x.description) === "new";
  const isRenew = (x: Debit) => orderKind(x.description) === "renewal";
  const newOrders = recent.filter(isNew).map((x) => x.amountCents);
  const avgOrderCents = newOrders.length >= 3 ? Math.round(newOrders.reduce((a, b) => a + b, 0) / newOrders.length) : null;

  const firsts = await firstDebitAt([...new Set(dc.map((d) => d.userId))]);
  const newPaying = [...firsts.entries()].filter(([, t]) => t >= r.from && t < r.to).length;
  const firstsPrev = await firstDebitAt([...new Set(dp.map((d) => d.userId))]);
  const newPayingPrev = [...firstsPrev.entries()].filter(([, t]) => t >= r.prevFrom && t < r.prevTo).length;

  // Daily earned series (local days).
  const keys = localDayKeys(r);
  const idx = new Map(keys.map((k, i) => [k, i]));
  const series = keys.map(() => 0);
  for (const d of dc) {
    const i = idx.get(bucketOf(d.createdAt, r.tz));
    if (i !== undefined) series[i] += d.amountCents;
  }
  const mrrStart = mrrSnaps.find((s) => s.date.getTime() >= r.from.getTime() - DAY)?.value ?? null;
  const mrrEnd = mrrSnaps.length ? mrrSnaps[mrrSnaps.length - 1].value : null;

  const byProduct = new Map<string, { n: number; cents: number; prevCents: number }>();
  for (const d of dc) {
    const p = productOf(d.description);
    const e = byProduct.get(p) ?? { n: 0, cents: 0, prevCents: 0 };
    e.n++;
    e.cents += d.amountCents;
    byProduct.set(p, e);
  }
  for (const d of dp) {
    const p = productOf(d.description);
    const e = byProduct.get(p) ?? { n: 0, cents: 0, prevCents: 0 };
    e.prevCents += d.amountCents;
    byProduct.set(p, e);
  }

  const metrics: Metric[] = [
    { key: "earned", domain: "revenue", label: "Revenue earned", unit: "cents", cur: sum(dc), prev: sum(dp), n: dc.length, prevN: dp.length, baseline: base, higherIsBetter: true, spark: series, drill: "orders" },
    { key: "cash_in", domain: "revenue", label: "Cash in (card / PayPal / crypto)", unit: "cents", cur: cc.cents, prev: cp.cents, n: cc.n, prevN: cp.n, higherIsBetter: true },
    { key: "new_orders", domain: "revenue", label: "New orders", unit: "count", cur: dc.filter(isNew).length, prev: dp.filter(isNew).length, higherIsBetter: true, drill: "orders" },
    { key: "new_order_revenue", domain: "revenue", label: "New-order revenue", unit: "cents", cur: sum(dc, isNew), prev: sum(dp, isNew), n: dc.filter(isNew).length, prevN: dp.filter(isNew).length, higherIsBetter: true },
    { key: "renewal_revenue", domain: "revenue", label: "Renewal revenue", unit: "cents", cur: sum(dc, isRenew), prev: sum(dp, isRenew), n: dc.filter(isRenew).length, prevN: dp.filter(isRenew).length, higherIsBetter: true },
    { key: "new_paying", domain: "revenue", label: "New paying customers", unit: "count", cur: newPaying, prev: newPayingPrev, higherIsBetter: true },
    { key: "refunds", domain: "revenue", label: "Refunds & write-offs", unit: "cents", cur: rev.refunds.cents, prev: rev.refundsPrev.cents, n: rev.refunds.count, prevN: rev.refundsPrev.count, higherIsBetter: false, drill: "refunds" },
    { key: "mrr", domain: "revenue", label: "MRR now", unit: "cents", cur: rev.mrrCents, prev: mrrStart, higherIsBetter: true, note: mrrStart == null ? "No MRR snapshot at the period start yet." : "Compared with the daily MRR snapshot at the period start." },
    { key: "arpu", domain: "revenue", label: "ARPU (MRR ÷ paying customers)", unit: "cents", cur: rev.arpuCents, prev: null, higherIsBetter: true },
    { key: "paying_customers", domain: "revenue", label: "Paying customers now", unit: "count", cur: rev.payingCustomers, prev: null, higherIsBetter: true },
  ];
  const tables: ReportSection["tables"] = [
    {
      key: "by_product",
      title: "Revenue by product",
      head: ["Product", "Charges", "Revenue", "Previous period"],
      rows: [...byProduct.entries()].sort((a, b) => b[1].cents - a[1].cents).map(([p, v]) => [p, v.n, `$${(v.cents / 100).toFixed(2)}`, `$${(v.prevCents / 100).toFixed(2)}`]),
    },
  ];
  if (coupons.length) tables.push({ key: "coupons", title: "Coupons redeemed", head: ["Code", "Redemptions", "Discount given"], rows: coupons.map((c) => [c.code, c.n, `$${(c.cents / 100).toFixed(2)}`]) });
  if (promos.length) tables.push({ key: "promos", title: "Promotions (first month free etc.)", head: ["Campaign", "Claimed in period", "Renewed in period", "Renewal rate, all time (35d+ old)"], rows: promos.map((p) => [p.campaign, p.n, p.renewed, p.due ? `${p.dueRenewed} of ${p.due}` : "—"]) });
  if (partners && partners.rows.length)
    tables.push({
      key: "partners",
      title: "Partner / creator attribution",
      head: ["Partner", "Clicks", "Customers attached", "Commission base", "Commission"],
      rows: partners.rows.slice(0, 10).map((p) => [p.name, p.clicks, p.attached, `$${(p.revenueBaseCents / 100).toFixed(2)}`, `$${(p.commissionCents / 100).toFixed(2)}`]),
    });
  const promoDue = promos.reduce((a, p) => a + p.due, 0);
  const promoRenewed = promos.reduce((a, p) => a + p.dueRenewed, 0);
  return {
    section: {
      domain: "revenue",
      metrics,
      tables,
      ranked: [],
      series: [{ key: "earned_daily", title: "Revenue earned per day", keys, values: series, unit: "cents" }],
      notes: [
        mrrEnd != null ? `MRR history comes from the worker's daily snapshot; latest snapshot $${(mrrEnd / 100).toFixed(2)}.` : "MRR history starts when the worker's daily snapshot started.",
        "Earned revenue = wallet debits for service (same definition as /admin/insights); a top-up counts when it is spent.",
      ],
    },
    avgOrderCents,
    arpuCents: rev.arpuCents,
    payingCustomers: rev.payingCustomers,
    promo: { due: promoDue, renewed: promoRenewed },
  };
}

// ---------------------------------------------------------------------------
// Payments
// ---------------------------------------------------------------------------

type PayEv = { userId: string | null; amountCents: number | null; method: string | null; cardBrand: string | null; cardCountry: string | null; failureCode: string | null; declineCode: string | null; threeDS: boolean; billingCountry: string | null; outcome: string };

async function paymentEvents(s: Span): Promise<PayEv[] | null> {
  try {
    return await db.$queryRaw<PayEv[]>`
      SELECT p."userId", p."amountCents", p.method, p."cardBrand", p."cardCountry", p."failureCode", p."declineCode", p."threeDS", u."billingCountry", p.outcome
      FROM "PaymentEvent" p LEFT JOIN "User" u ON u.id = p."userId"
      WHERE p."createdAt" >= ${s.from} AND p."createdAt" < ${s.to} AND (p."userId" IS NULL OR ${realUser("u")})
      LIMIT 50000`;
  } catch {
    return null; // table not deployed yet
  }
}

async function successesByCountry(s: Span): Promise<Map<string, number>> {
  const rows = await db.$queryRaw<{ c: string | null; n: number }[]>`
    SELECT u."billingCountry" AS c, count(*)::int AS n FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${realCashIn("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to} GROUP BY 1`;
  return new Map(rows.map((r) => [r.c ?? "Unknown", r.n]));
}

export async function collectPayments(r: ReportRange): Promise<{ section: ReportSection; friction: Pick<FrictionInputs, "declinesByCountry" | "declinesByBrand" | "declineReasons" | "authFailures" | "renewalDeclines">; instrumented: boolean }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [pe, pep, cc, cp, okCountry, renew, renewPrev, unusable, pi] = await Promise.all([
    paymentEvents(cur),
    paymentEvents(prev),
    cashIn(cur),
    cashIn(prev),
    successesByCountry(cur),
    db.$queryRaw<{ userId: string | null; detail: string | null }[]>`
      SELECT a."userId", a.detail FROM "AuditLog" a LEFT JOIN "User" u ON u.id = a."userId"
      WHERE a.action = 'billing.card_declined' AND a."createdAt" >= ${r.from} AND a."createdAt" < ${r.to} AND (a."userId" IS NULL OR ${realUser("u")}) LIMIT 5000`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "AuditLog" WHERE action = 'billing.card_declined' AND "createdAt" >= ${r.prevFrom} AND "createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "AuditLog" WHERE action = 'card.unusable' AND "createdAt" >= ${r.from} AND "createdAt" < ${r.to}`,
    paymentInsights(r),
  ]);
  const instrumented = pe !== null;
  const fails = (pe ?? []).filter((p) => p.outcome === "failed");
  const failsPrev = (pep ?? []).filter((p) => p.outcome === "failed");

  const group = (key: (p: PayEv) => string, okMap: Map<string, number> | null): GroupRate[] => {
    const m = new Map<string, GroupRate>();
    for (const p of fails) {
      const k = key(p);
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, userIds: [] };
      g.failed++;
      g.total++;
      if (p.userId && g.userIds!.length < 100) g.userIds!.push(p.userId);
      m.set(k, g);
    }
    if (okMap) for (const [k, n] of okMap) {
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, userIds: [] };
      g.total += n;
      m.set(k, g);
    }
    return [...m.values()].sort((a, b) => b.failed - a.failed);
  };
  const declinesByCountry = group((p) => p.cardCountry ?? p.billingCountry ?? "Unknown", okCountry);
  const declinesByBrand = group((p) => p.cardBrand ?? p.method ?? "Unknown", null);
  const reasons = new Map<string, number>();
  for (const p of fails) {
    const k = p.declineCode ?? p.failureCode ?? "unknown";
    reasons.set(k, (reasons.get(k) ?? 0) + 1);
  }
  const declineReasons: Ranked[] = [...reasons.entries()].sort((a, b) => b[1] - a[1]).map(([label, value]) => ({ label, value }));
  const renewReasons = new Map<string, number>();
  for (const a of renew) {
    const reason = normalizeMessage((a.detail ?? "").split("—").slice(1).join("—") || a.detail || "unknown", 90);
    renewReasons.set(reason, (renewReasons.get(reason) ?? 0) + 1);
  }
  const attempts = cc.n + fails.length;
  const attemptsPrev = cp.n + failsPrev.length;
  const metrics: Metric[] = [
    { key: "payments_ok", domain: "payments", label: "Successful payments", unit: "count", cur: cc.n, prev: cp.n, higherIsBetter: true },
    { key: "payments_failed", domain: "payments", label: "Failed card attempts (checkout)", unit: "count", cur: instrumented ? fails.length : null, prev: pep ? failsPrev.length : null, higherIsBetter: false, drill: "declines", note: instrumented ? undefined : "Recording starts once PaymentEvent is deployed." },
    {
      key: "payment_success_rate",
      domain: "payments",
      label: "Payment success rate",
      unit: "ratio",
      cur: instrumented && attempts ? cc.n / attempts : null,
      prev: pep && attemptsPrev ? cp.n / attemptsPrev : null,
      num: cc.n,
      den: attempts,
      prevNum: cp.n,
      prevDen: attemptsPrev,
      higherIsBetter: true,
    },
    { key: "renewal_declines", domain: "payments", label: "Renewal charges declined", unit: "count", cur: renew.length, prev: renewPrev[0]?.n ?? 0, higherIsBetter: false, drill: "renewal_declines" },
    { key: "failure_emails", domain: "payments", label: "Payment-failure emails sent", unit: "count", cur: pi.failureEmails.reduce((a, b) => a + b.count, 0), prev: pi.failureEmailsPrev, higherIsBetter: false },
  ];
  const tables: ReportSection["tables"] = [];
  if (instrumented && fails.length) {
    tables.push({ key: "decline_country", title: "Failed card attempts by country", head: ["Country", "Failed", "Succeeded", "Failure rate"], rows: declinesByCountry.slice(0, 12).map((g) => [g.label, g.failed, g.total - g.failed, g.total ? `${Math.round((g.failed / g.total) * 100)}%` : "—"]) });
    tables.push({ key: "decline_brand", title: "Failed attempts by card brand / method", head: ["Brand / method", "Failed"], rows: declinesByBrand.slice(0, 8).map((g) => [g.label, g.failed]) });
  }
  if (pi.dunningNow.length) tables.push({ key: "dunning", title: "Servers in dunning right now", head: ["Failed attempts so far", "Servers"], rows: pi.dunningNow.map((d) => [d.stage, d.count]) });
  return {
    section: {
      domain: "payments",
      metrics,
      tables,
      ranked: [
        { key: "decline_reasons", title: "Checkout decline reasons", rows: declineReasons.slice(0, 8) },
        { key: "renewal_reasons", title: "Renewal decline reasons", rows: [...renewReasons.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map(([label, value]) => ({ label, value })) },
      ],
      notes: [
        instrumented
          ? "Checkout failures come from Stripe's payment_intent.payment_failed webhook (PaymentEvent). Card data kept: brand + issuing country only."
          : "Checkout decline details are not recorded yet — they start once the PaymentEvent table is deployed. Renewal declines come from the billing sweep's audit log.",
        `${unusable[0]?.n ?? 0} saved card(s) were retired as unusable in this period. Overdue invoices (7d+): ${pi.overdueInvoices.count}.`,
      ],
    },
    friction: {
      declinesByCountry,
      declinesByBrand,
      declineReasons,
      authFailures: fails.filter((p) => p.threeDS).length,
      renewalDeclines: { count: renew.length, users: new Set(renew.map((a) => a.userId).filter(Boolean)).size, reasons: [...renewReasons.entries()].map(([label, value]) => ({ label, value })), userIds: [...new Set(renew.map((a) => a.userId).filter((u): u is string => !!u))] },
    },
    instrumented,
  };
}

// ---------------------------------------------------------------------------
// Retention & churn
// ---------------------------------------------------------------------------

export async function collectRetention(r: ReportRange, mrr: { mrrCents: number; payingCustomers: number }): Promise<{ section: ReportSection; winback: FrictionInputs["winback"] }> {
  const [churn, cancels, cancelsPrev, expired, expiredPrev, wb] = await Promise.all([
    churnInsights(r, mrr),
    db.$queryRaw<{ action: string; n: number }[]>`
      SELECT a.action, count(*)::int AS n FROM "AuditLog" a JOIN "User" u ON u.id = a."userId"
      WHERE a.action IN ('server.cancel_period_end', 'server.cancel_immediate') AND ${realUser("u")} AND a."createdAt" >= ${r.from} AND a."createdAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ n: number }[]>`
      SELECT count(*)::int AS n FROM "AuditLog" a JOIN "User" u ON u.id = a."userId"
      WHERE a.action IN ('server.cancel_period_end', 'server.cancel_immediate') AND ${realUser("u")} AND a."createdAt" >= ${r.prevFrom} AND a."createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ reason: string; n: number; cents: number }[]>`
      SELECT a.reason, count(*)::int AS n, coalesce(sum(a."totalSpentCents"), 0)::int AS cents FROM "ServerArchive" a JOIN "User" u ON u.id = a."userId"
      WHERE ${realUser("u")} AND a."totalSpentCents" > 0 AND a."deletedAt" >= ${r.from} AND a."deletedAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ n: number }[]>`
      SELECT count(*)::int AS n FROM "ServerArchive" a JOIN "User" u ON u.id = a."userId"
      WHERE ${realUser("u")} AND a."totalSpentCents" > 0 AND a."deletedAt" >= ${r.prevFrom} AND a."deletedAt" < ${r.prevTo}`,
    // Win-back results: recipients in period; "converted" = deployed or paid AFTER the email.
    db.$queryRaw<{ template: string; sent: number; clicked: number; converted: number }[]>`
      WITH m AS (
        SELECT e.template, e."userId", min(e."createdAt") AS t, bool_or(e."clickedAt" IS NOT NULL) AS clicked
        FROM "EmailLog" e WHERE e.template IN ('deploy_winback', 'dormant_winback') AND e.status = 'SENT' AND e."userId" IS NOT NULL
          AND e."createdAt" >= ${r.from} AND e."createdAt" < ${r.to}
        GROUP BY 1, 2
      )
      SELECT m.template, count(*)::int AS sent, count(*) FILTER (WHERE m.clicked)::int AS clicked,
        count(*) FILTER (WHERE EXISTS (SELECT 1 FROM "Server" s WHERE s."userId" = m."userId" AND s."createdAt" > m.t)
          OR EXISTS (SELECT 1 FROM "WalletTransaction" w WHERE w."userId" = m."userId" AND w."createdAt" > m.t AND ${revenueDebit("w")}))::int AS converted
      FROM m GROUP BY 1`,
  ]);
  const cancelN = cancels.reduce((a, b) => a + b.n, 0);
  const lost = expired.reduce((a, b) => a + b.n, 0);
  const metrics: Metric[] = [
    { key: "churned_customers", domain: "retention", label: "Paying customers lost", unit: "count", cur: churn.churned, prev: null, higherIsBetter: false, drill: "churned", note: `${churn.startCustomers} paying at the start, ${churn.endCustomers} now.` },
    {
      key: "churn_rate",
      domain: "retention",
      label: "Customer churn (period)",
      unit: "ratio",
      cur: churn.churnRate.ok ? churn.churnRate.value : null,
      prev: churn.churnRatePrev.ok ? churn.churnRatePrev.value : null,
      num: churn.churned,
      den: churn.startCustomers,
      higherIsBetter: false,
      note: churn.churnRate.ok ? undefined : churn.churnRate.reason,
    },
    { key: "cancellations", domain: "retention", label: "Cancellations requested", unit: "count", cur: cancelN, prev: cancelsPrev[0]?.n ?? 0, higherIsBetter: false },
    { key: "paid_servers_deleted", domain: "retention", label: "Paid servers that ended", unit: "count", cur: lost, prev: expiredPrev[0]?.n ?? 0, higherIsBetter: false },
    { key: "new_paying_churn", domain: "retention", label: "New paying customers (lifetime model)", unit: "count", cur: churn.newPaying, prev: null, higherIsBetter: true },
  ];
  const tables: ReportSection["tables"] = [];
  if (expired.length) tables.push({ key: "ended", title: "Paid servers that ended, by reason", head: ["Reason", "Servers", "Lifetime spend"], rows: expired.map((e) => [e.reason, e.n, `$${(e.cents / 100).toFixed(2)}`]) });
  if (wb.length) tables.push({ key: "winback", title: "Win-back emails", head: ["Campaign", "Recipients", "Clicked", "Came back (deployed or paid after)"], rows: wb.map((w) => [w.template, w.sent, w.clicked, w.converted]) });
  if (churn.cohorts.ok)
    tables.push({
      key: "cohorts",
      title: "Paying cohorts — share still paying after N months",
      head: ["First paid", "Customers", "M1", "M2", "M3", "M6"],
      rows: churn.cohorts.value.slice(-8).map((c) => [c.month, c.size, ...[1, 2, 3, 6].map((k) => (c.retained[k] == null ? "—" : `${Math.round((c.retained[k] as number) * 100)}%`))]),
    });
  return {
    section: { domain: "retention", metrics, tables, ranked: [], notes: ["Churn uses the paid-server lifetime model from /admin/insights (live paid servers + archived servers that ever took money)."] },
    winback: wb,
  };
}

toolu_01NnBsAexLgyYeGwkcH9RMtT.content:
/**
 * Report aggregation: orders & revenue, payments, retention & churn. Reuses
 * the audited lib/insights/* figures (MRR, earned revenue, cash in, churn) so
 * a number in a report never disagrees with the same number on /admin/insights.
 */
import { db } from "@/lib/db";
import { revenueInsights, churnInsights } from "@/lib/insights/revenue";
import { paymentInsights, partnerInsights } from "@/lib/insights/growth";
import { orderKind, productOf, normalizeMessage } from "./classify";
import { realUser, realCashIn, revenueDebit, type Span } from "./sql";
import type { ReportRange } from "./range";
import { localDayKeys, bucketOf } from "./range";
import type { FrictionInputs, GroupRate, Metric, Ranked, ReportSection } from "./types";

const DAY = 86_400_000;

type Debit = { id: string; userId: string; amountCents: number; description: string; createdAt: Date };

async function debits(s: Span): Promise<Debit[]> {
  return db.$queryRaw<Debit[]>`
    SELECT w.id, w."userId", -w."amountCents" AS "amountCents", w.description, w."createdAt"
    FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${revenueDebit("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to}
    ORDER BY w."createdAt" ASC LIMIT 100000`;
}

async function cashIn(s: Span): Promise<{ n: number; cents: number; users: number }> {
  const [r] = await db.$queryRaw<{ n: number; cents: number; users: number }[]>`
    SELECT count(*)::int AS n, coalesce(sum(w."amountCents"), 0)::int AS cents, count(DISTINCT w."userId")::int AS users
    FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${realCashIn("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to}`;
  return r ?? { n: 0, cents: 0, users: 0 };
}

/** First-ever revenue debit per user (to tell a new paying customer from a returning one). */
async function firstDebitAt(userIds: string[]): Promise<Map<string, Date>> {
  if (!userIds.length) return new Map();
  const rows = await db.$queryRaw<{ userId: string; t: Date }[]>`
    SELECT w."userId", min(w."createdAt") AS t FROM "WalletTransaction" w
    WHERE w."userId" = ANY(${userIds}::text[]) AND ${revenueDebit("w")} GROUP BY 1`;
  return new Map(rows.map((r) => [r.userId, r.t]));
}

export async function collectRevenue(r: ReportRange): Promise<{ section: ReportSection; avgOrderCents: number | null; arpuCents: number | null; payingCustomers: number; promo: FrictionInputs["promoRenewals"] }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [dc, dp, base, cc, cp, rev, recent, coupons, promos, partners, mrrSnaps] = await Promise.all([
    debits(cur),
    debits(prev),
    Promise.all(r.baseline.map((b) => debits(b).then((d) => d.reduce((a, x) => a + x.amountCents, 0)))),
    cashIn(cur),
    cashIn(prev),
    revenueInsights(r),
    // Average NEW order over the 90 days up to the end of the period: the engine's "what is one customer worth".
    debits({ from: new Date(r.to.getTime() - 90 * DAY), to: r.to }),
    db.$queryRaw<{ code: string; n: number; cents: number }[]>`
      SELECT c.code, count(*)::int AS n, coalesce(sum(cr."amountCents"), 0)::int AS cents
      FROM "CouponRedemption" cr JOIN "Coupon" c ON c.id = cr."couponId" JOIN "User" u ON u.id = cr."userId"
      WHERE cr.state = 'CONSUMED' AND ${realUser("u")} AND cr."createdAt" >= ${r.from} AND cr."createdAt" < ${r.to}
      GROUP BY 1 ORDER BY 2 DESC`,
    db.$queryRaw<{ campaign: string; n: number; renewed: number; due: number; dueRenewed: number }[]>`
      SELECT coalesce(nullif(p.campaign, ''), 'first-month-free') AS campaign,
        count(*) FILTER (WHERE p."createdAt" >= ${r.from} AND p."createdAt" < ${r.to})::int AS n,
        count(*) FILTER (WHERE p.renewed AND p."renewedAt" >= ${r.from} AND p."renewedAt" < ${r.to})::int AS renewed,
        count(*) FILTER (WHERE p."createdAt" < now() - interval '35 days')::int AS due,
        count(*) FILTER (WHERE p."createdAt" < now() - interval '35 days' AND p.renewed)::int AS "dueRenewed"
      FROM "PromoRedemption" p JOIN "User" u ON u.id = p."userId"
      WHERE p.state = 'CONSUMED' AND ${realUser("u")} GROUP BY 1`,
    partnerInsights(r).catch(() => null),
    db.insightsSnapshot.findMany({ where: { metric: "mrr_cents", scopeId: "", date: { gte: new Date(r.from.getTime() - 2 * DAY), lte: r.to } }, orderBy: { date: "asc" } }).catch(() => []),
  ]);
  const sum = (d: Debit[], f?: (x: Debit) => boolean) => d.filter((x) => !f || f(x)).reduce((a, x) => a + x.amountCents, 0);
  const isNew = (x: Debit) => orderKind(x.description) === "new";
  const isRenew = (x: Debit) => orderKind(x.description) === "renewal";
  const newOrders = recent.filter(isNew).map((x) => x.amountCents);
  const avgOrderCents = newOrders.length >= 3 ? Math.round(newOrders.reduce((a, b) => a + b, 0) / newOrders.length) : null;

  const firsts = await firstDebitAt([...new Set(dc.map((d) => d.userId))]);
  const newPaying = [...firsts.entries()].filter(([, t]) => t >= r.from && t < r.to).length;
  const firstsPrev = await firstDebitAt([...new Set(dp.map((d) => d.userId))]);
  const newPayingPrev = [...firstsPrev.entries()].filter(([, t]) => t >= r.prevFrom && t < r.prevTo).length;

  // Daily earned series (local days).
  const keys = localDayKeys(r);
  const idx = new Map(keys.map((k, i) => [k, i]));
  const series = keys.map(() => 0);
  for (const d of dc) {
    const i = idx.get(bucketOf(d.createdAt, r.tz));
    if (i !== undefined) series[i] += d.amountCents;
  }
  const mrrStart = mrrSnaps.find((s) => s.date.getTime() >= r.from.getTime() - DAY)?.value ?? null;
  const mrrEnd = mrrSnaps.length ? mrrSnaps[mrrSnaps.length - 1].value : null;

  const byProduct = new Map<string, { n: number; cents: number; prevCents: number }>();
  for (const d of dc) {
    const p = productOf(d.description);
    const e = byProduct.get(p) ?? { n: 0, cents: 0, prevCents: 0 };
    e.n++;
    e.cents += d.amountCents;
    byProduct.set(p, e);
  }
  for (const d of dp) {
    const p = productOf(d.description);
    const e = byProduct.get(p) ?? { n: 0, cents: 0, prevCents: 0 };
    e.prevCents += d.amountCents;
    byProduct.set(p, e);
  }

  const metrics: Metric[] = [
    { key: "earned", domain: "revenue", label: "Revenue earned", unit: "cents", cur: sum(dc), prev: sum(dp), n: dc.length, prevN: dp.length, baseline: base, higherIsBetter: true, spark: series, drill: "orders" },
    { key: "cash_in", domain: "revenue", label: "Cash in (card / PayPal / crypto)", unit: "cents", cur: cc.cents, prev: cp.cents, n: cc.n, prevN: cp.n, higherIsBetter: true },
    { key: "new_orders", domain: "revenue", label: "New orders", unit: "count", cur: dc.filter(isNew).length, prev: dp.filter(isNew).length, higherIsBetter: true, drill: "orders" },
    { key: "new_order_revenue", domain: "revenue", label: "New-order revenue", unit: "cents", cur: sum(dc, isNew), prev: sum(dp, isNew), n: dc.filter(isNew).length, prevN: dp.filter(isNew).length, higherIsBetter: true },
    { key: "renewal_revenue", domain: "revenue", label: "Renewal revenue", unit: "cents", cur: sum(dc, isRenew), prev: sum(dp, isRenew), n: dc.filter(isRenew).length, prevN: dp.filter(isRenew).length, higherIsBetter: true },
    { key: "new_paying", domain: "revenue", label: "New paying customers", unit: "count", cur: newPaying, prev: newPayingPrev, higherIsBetter: true },
    { key: "refunds", domain: "revenue", label: "Refunds & write-offs", unit: "cents", cur: rev.refunds.cents, prev: rev.refundsPrev.cents, n: rev.refunds.count, prevN: rev.refundsPrev.count, higherIsBetter: false, drill: "refunds" },
    { key: "mrr", domain: "revenue", label: "MRR now", unit: "cents", cur: rev.mrrCents, prev: mrrStart, higherIsBetter: true, note: mrrStart == null ? "No MRR snapshot at the period start yet." : "Compared with the daily MRR snapshot at the period start." },
    { key: "arpu", domain: "revenue", label: "ARPU (MRR ÷ paying customers)", unit: "cents", cur: rev.arpuCents, prev: null, higherIsBetter: true },
    { key: "paying_customers", domain: "revenue", label: "Paying customers now", unit: "count", cur: rev.payingCustomers, prev: null, higherIsBetter: true },
  ];
  const tables: ReportSection["tables"] = [
    {
      key: "by_product",
      title: "Revenue by product",
      head: ["Product", "Charges", "Revenue", "Previous period"],
      rows: [...byProduct.entries()].sort((a, b) => b[1].cents - a[1].cents).map(([p, v]) => [p, v.n, `$${(v.cents / 100).toFixed(2)}`, `$${(v.prevCents / 100).toFixed(2)}`]),
    },
  ];
  if (coupons.length) tables.push({ key: "coupons", title: "Coupons redeemed", head: ["Code", "Redemptions", "Discount given"], rows: coupons.map((c) => [c.code, c.n, `$${(c.cents / 100).toFixed(2)}`]) });
  if (promos.length) tables.push({ key: "promos", title: "Promotions (first month free etc.)", head: ["Campaign", "Claimed in period", "Renewed in period", "Renewal rate, all time (35d+ old)"], rows: promos.map((p) => [p.campaign, p.n, p.renewed, p.due ? `${p.dueRenewed} of ${p.due}` : "—"]) });
  if (partners && partners.rows.length)
    tables.push({
      key: "partners",
      title: "Partner / creator attribution",
      head: ["Partner", "Clicks", "Customers attached", "Commission base", "Commission"],
      rows: partners.rows.slice(0, 10).map((p) => [p.name, p.clicks, p.attached, `$${(p.revenueBaseCents / 100).toFixed(2)}`, `$${(p.commissionCents / 100).toFixed(2)}`]),
    });
  const promoDue = promos.reduce((a, p) => a + p.due, 0);
  const promoRenewed = promos.reduce((a, p) => a + p.dueRenewed, 0);
  return {
    section: {
      domain: "revenue",
      metrics,
      tables,
      ranked: [],
      series: [{ key: "earned_daily", title: "Revenue earned per day", keys, values: series, unit: "cents" }],
      notes: [
        mrrEnd != null ? `MRR history comes from the worker's daily snapshot; latest snapshot $${(mrrEnd / 100).toFixed(2)}.` : "MRR history starts when the worker's daily snapshot started.",
        "Earned revenue = wallet debits for service (same definition as /admin/insights); a top-up counts when it is spent.",
      ],
    },
    avgOrderCents,
    arpuCents: rev.arpuCents,
    payingCustomers: rev.payingCustomers,
    promo: { due: promoDue, renewed: promoRenewed },
  };
}

// ---------------------------------------------------------------------------
// Payments
// ---------------------------------------------------------------------------

type PayEv = { userId: string | null; amountCents: number | null; method: string | null; cardBrand: string | null; cardCountry: string | null; failureCode: string | null; declineCode: string | null; threeDS: boolean; billingCountry: string | null; outcome: string };

async function paymentEvents(s: Span): Promise<PayEv[] | null> {
  try {
    return await db.$queryRaw<PayEv[]>`
      SELECT p."userId", p."amountCents", p.method, p."cardBrand", p."cardCountry", p."failureCode", p."declineCode", p."threeDS", u."billingCountry", p.outcome
      FROM "PaymentEvent" p LEFT JOIN "User" u ON u.id = p."userId"
      WHERE p."createdAt" >= ${s.from} AND p."createdAt" < ${s.to} AND (p."userId" IS NULL OR ${realUser("u")})
      LIMIT 50000`;
  } catch {
    return null; // table not deployed yet
  }
}

async function successesByCountry(s: Span): Promise<Map<string, number>> {
  const rows = await db.$queryRaw<{ c: string | null; n: number }[]>`
    SELECT u."billingCountry" AS c, count(*)::int AS n FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
    WHERE ${realCashIn("w")} AND ${realUser("u")} AND w."createdAt" >= ${s.from} AND w."createdAt" < ${s.to} GROUP BY 1`;
  return new Map(rows.map((r) => [r.c ?? "Unknown", r.n]));
}

export async function collectPayments(r: ReportRange): Promise<{ section: ReportSection; friction: Pick<FrictionInputs, "declinesByCountry" | "declinesByBrand" | "declineReasons" | "authFailures" | "renewalDeclines">; instrumented: boolean }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [pe, pep, cc, cp, okCountry, renew, renewPrev, unusable, pi] = await Promise.all([
    paymentEvents(cur),
    paymentEvents(prev),
    cashIn(cur),
    cashIn(prev),
    successesByCountry(cur),
    db.$queryRaw<{ userId: string | null; detail: string | null }[]>`
      SELECT a."userId", a.detail FROM "AuditLog" a LEFT JOIN "User" u ON u.id = a."userId"
      WHERE a.action = 'billing.card_declined' AND a."createdAt" >= ${r.from} AND a."createdAt" < ${r.to} AND (a."userId" IS NULL OR ${realUser("u")}) LIMIT 5000`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "AuditLog" WHERE action = 'billing.card_declined' AND "createdAt" >= ${r.prevFrom} AND "createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "AuditLog" WHERE action = 'card.unusable' AND "createdAt" >= ${r.from} AND "createdAt" < ${r.to}`,
    paymentInsights(r),
  ]);
  const instrumented = pe !== null;
  const fails = (pe ?? []).filter((p) => p.outcome === "failed");
  const failsPrev = (pep ?? []).filter((p) => p.outcome === "failed");

  const group = (key: (p: PayEv) => string, okMap: Map<string, number> | null): GroupRate[] => {
    const m = new Map<string, GroupRate>();
    for (const p of fails) {
      const k = key(p);
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, userIds: [] };
      g.failed++;
      g.total++;
      if (p.userId && g.userIds!.length < 100) g.userIds!.push(p.userId);
      m.set(k, g);
    }
    if (okMap) for (const [k, n] of okMap) {
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, userIds: [] };
      g.total += n;
      m.set(k, g);
    }
    return [...m.values()].sort((a, b) => b.failed - a.failed);
  };
  const declinesByCountry = group((p) => p.cardCountry ?? p.billingCountry ?? "Unknown", okCountry);
  const declinesByBrand = group((p) => p.cardBrand ?? p.method ?? "Unknown", null);
  const reasons = new Map<string, number>();
  for (const p of fails) {
    const k = p.declineCode ?? p.failureCode ?? "unknown";
    reasons.set(k, (reasons.get(k) ?? 0) + 1);
  }
  const declineReasons: Ranked[] = [...reasons.entries()].sort((a, b) => b[1] - a[1]).map(([label, value]) => ({ label, value }));
  const renewReasons = new Map<string, number>();
  for (const a of renew) {
    const reason = normalizeMessage((a.detail ?? "").split("—").slice(1).join("—") || a.detail || "unknown", 90);
    renewReasons.set(reason, (renewReasons.get(reason) ?? 0) + 1);
  }
  const attempts = cc.n + fails.length;
  const attemptsPrev = cp.n + failsPrev.length;
  const metrics: Metric[] = [
    { key: "payments_ok", domain: "payments", label: "Successful payments", unit: "count", cur: cc.n, prev: cp.n, higherIsBetter: true },
    { key: "payments_failed", domain: "payments", label: "Failed card attempts (checkout)", unit: "count", cur: instrumented ? fails.length : null, prev: pep ? failsPrev.length : null, higherIsBetter: false, drill: "declines", note: instrumented ? undefined : "Recording starts once PaymentEvent is deployed." },
    {
      key: "payment_success_rate",
      domain: "payments",
      label: "Payment success rate",
      unit: "ratio",
      cur: instrumented && attempts ? cc.n / attempts : null,
      prev: pep && attemptsPrev ? cp.n / attemptsPrev : null,
      num: cc.n,
      den: attempts,
      prevNum: cp.n,
      prevDen: attemptsPrev,
      higherIsBetter: true,
    },
    { key: "renewal_declines", domain: "payments", label: "Renewal charges declined", unit: "count", cur: renew.length, prev: renewPrev[0]?.n ?? 0, higherIsBetter: false, drill: "renewal_declines" },
    { key: "failure_emails", domain: "payments", label: "Payment-failure emails sent", unit: "count", cur: pi.failureEmails.reduce((a, b) => a + b.count, 0), prev: pi.failureEmailsPrev, higherIsBetter: false },
  ];
  const tables: ReportSection["tables"] = [];
  if (instrumented && fails.length) {
    tables.push({ key: "decline_country", title: "Failed card attempts by country", head: ["Country", "Failed", "Succeeded", "Failure rate"], rows: declinesByCountry.slice(0, 12).map((g) => [g.label, g.failed, g.total - g.failed, g.total ? `${Math.round((g.failed / g.total) * 100)}%` : "—"]) });
    tables.push({ key: "decline_brand", title: "Failed attempts by card brand / method", head: ["Brand / method", "Failed"], rows: declinesByBrand.slice(0, 8).map((g) => [g.label, g.failed]) });
  }
  if (pi.dunningNow.length) tables.push({ key: "dunning", title: "Servers in dunning right now", head: ["Failed attempts so far", "Servers"], rows: pi.dunningNow.map((d) => [d.stage, d.count]) });
  return {
    section: {
      domain: "payments",
      metrics,
      tables,
      ranked: [
        { key: "decline_reasons", title: "Checkout decline reasons", rows: declineReasons.slice(0, 8) },
        { key: "renewal_reasons", title: "Renewal decline reasons", rows: [...renewReasons.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map(([label, value]) => ({ label, value })) },
      ],
      notes: [
        instrumented
          ? "Checkout failures come from Stripe's payment_intent.payment_failed webhook (PaymentEvent). Card data kept: brand + issuing country only."
          : "Checkout decline details are not recorded yet — they start once the PaymentEvent table is deployed. Renewal declines come from the billing sweep's audit log.",
        `${unusable[0]?.n ?? 0} saved card(s) were retired as unusable in this period. Overdue invoices (7d+): ${pi.overdueInvoices.count}.`,
      ],
    },
    friction: {
      declinesByCountry,
      declinesByBrand,
      declineReasons,
      authFailures: fails.filter((p) => p.threeDS).length,
      renewalDeclines: { count: renew.length, users: new Set(renew.map((a) => a.userId).filter(Boolean)).size, reasons: [...renewReasons.entries()].map(([label, value]) => ({ label, value })), userIds: [...new Set(renew.map((a) => a.userId).filter((u): u is string => !!u))] },
    },
    instrumented,
  };
}

// ---------------------------------------------------------------------------
// Retention & churn
// ---------------------------------------------------------------------------

export async function collectRetention(r: ReportRange, mrr: { mrrCents: number; payingCustomers: number }): Promise<{ section: ReportSection; winback: FrictionInputs["winback"] }> {
  const [churn, cancels, cancelsPrev, expired, expiredPrev, wb] = await Promise.all([
    churnInsights(r, mrr),
    db.$queryRaw<{ action: string; n: number }[]>`
      SELECT a.action, count(*)::int AS n FROM "AuditLog" a JOIN "User" u ON u.id = a."userId"
      WHERE a.action IN ('server.cancel_period_end', 'server.cancel_immediate') AND ${realUser("u")} AND a."createdAt" >= ${r.from} AND a."createdAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ n: number }[]>`
      SELECT count(*)::int AS n FROM "AuditLog" a JOIN "User" u ON u.id = a."userId"
      WHERE a.action IN ('server.cancel_period_end', 'server.cancel_immediate') AND ${realUser("u")} AND a."createdAt" >= ${r.prevFrom} AND a."createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ reason: string; n: number; cents: number }[]>`
      SELECT a.reason, count(*)::int AS n, coalesce(sum(a."totalSpentCents"), 0)::int AS cents FROM "ServerArchive" a JOIN "User" u ON u.id = a."userId"
      WHERE ${realUser("u")} AND a."totalSpentCents" > 0 AND a."deletedAt" >= ${r.from} AND a."deletedAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ n: number }[]>`
      SELECT count(*)::int AS n FROM "ServerArchive" a JOIN "User" u ON u.id = a."userId"
      WHERE ${realUser("u")} AND a."totalSpentCents" > 0 AND a."deletedAt" >= ${r.prevFrom} AND a."deletedAt" < ${r.prevTo}`,
    // Win-back results: recipients in period; "converted" = deployed or paid AFTER the email.
    db.$queryRaw<{ template: string; sent: number; clicked: number; converted: number }[]>`
      WITH m AS (
        SELECT e.template, e."userId", min(e."createdAt") AS t, bool_or(e."clickedAt" IS NOT NULL) AS clicked
        FROM "EmailLog" e WHERE e.template IN ('deploy_winback', 'dormant_winback') AND e.status = 'SENT' AND e."userId" IS NOT NULL
          AND e."createdAt" >= ${r.from} AND e."createdAt" < ${r.to}
        GROUP BY 1, 2
      )
      SELECT m.template, count(*)::int AS sent, count(*) FILTER (WHERE m.clicked)::int AS clicked,
        count(*) FILTER (WHERE EXISTS (SELECT 1 FROM "Server" s WHERE s."userId" = m."userId" AND s."createdAt" > m.t)
          OR EXISTS (SELECT 1 FROM "WalletTransaction" w WHERE w."userId" = m."userId" AND w."createdAt" > m.t AND ${revenueDebit("w")}))::int AS converted
      FROM m GROUP BY 1`,
  ]);
  const cancelN = cancels.reduce((a, b) => a + b.n, 0);
  const lost = expired.reduce((a, b) => a + b.n, 0);
  const metrics: Metric[] = [
    { key: "churned_customers", domain: "retention", label: "Paying customers lost", unit: "count", cur: churn.churned, prev: null, higherIsBetter: false, drill: "churned", note: `${churn.startCustomers} paying at the start, ${churn.endCustomers} now.` },
    {
      key: "churn_rate",
      domain: "retention",
      label: "Customer churn (period)",
      unit: "ratio",
      cur: churn.churnRate.ok ? churn.churnRate.value : null,
      prev: churn.churnRatePrev.ok ? churn.churnRatePrev.value : null,
      num: churn.churned,
      den: churn.startCustomers,
      higherIsBetter: false,
      note: churn.churnRate.ok ? undefined : churn.churnRate.reason,
    },
    { key: "cancellations", domain: "retention", label: "Cancellations requested", unit: "count", cur: cancelN, prev: cancelsPrev[0]?.n ?? 0, higherIsBetter: false },
    { key: "paid_servers_deleted", domain: "retention", label: "Paid servers that ended", unit: "count", cur: lost, prev: expiredPrev[0]?.n ?? 0, higherIsBetter: false },
    { key: "new_paying_churn", domain: "retention", label: "New paying customers (lifetime model)", unit: "count", cur: churn.newPaying, prev: null, higherIsBetter: true },
  ];
  const tables: ReportSection["tables"] = [];
  if (expired.length) tables.push({ key: "ended", title: "Paid servers that ended, by reason", head: ["Reason", "Servers", "Lifetime spend"], rows: expired.map((e) => [e.reason, e.n, `$${(e.cents / 100).toFixed(2)}`]) });
  if (wb.length) tables.push({ key: "winback", title: "Win-back emails", head: ["Campaign", "Recipients", "Clicked", "Came back (deployed or paid after)"], rows: wb.map((w) => [w.template, w.sent, w.clicked, w.converted]) });
  if (churn.cohorts.ok)
    tables.push({
      key: "cohorts",
      title: "Paying cohorts — share still paying after N months",
      head: ["First paid", "Customers", "M1", "M2", "M3", "M6"],
      rows: churn.cohorts.value.slice(-8).map((c) => [c.month, c.size, ...[1, 2, 3, 6].map((k) => (c.retained[k] == null ? "—" : `${Math.round((c.retained[k] as number) * 100)}%`))]),
    });
  return {
    section: { domain: "retention", metrics, tables, ranked: [], notes: ["Churn uses the paid-server lifetime model from /admin/insights (live paid servers + archived servers that ever took money)."] },
    winback: wb,
  };
}

