/**
 * Report aggregation: provisioning, product usage, support, errors, fleet &
 * capacity, email deliverability.
 */
import { db } from "@/lib/db";
import { supportInsights } from "@/lib/insights/ops";
import { capacityInsights } from "@/lib/insights/products";
import { percentile } from "@/lib/insights/stats";
import { normalizeMessage, topicOf, usageCategory } from "./classify";
import { isMoneyPath } from "./routes";
import { realUser, type Span } from "./sql";
import type { ReportRange } from "./range";
import type { FrictionInputs, GroupRate, Metric, Ranked, ReportSection } from "./types";

// ---------------------------------------------------------------------------
// Provisioning
// ---------------------------------------------------------------------------

type ProvRow = { id: string; userId: string; game: string | null; node: string | null; createdAt: Date; status: string | null; archived: boolean };

/** Every server a real customer ordered in the span (live + since-deleted), with its game and node. */
async function serversOrdered(s: Span): Promise<ProvRow[]> {
  return db.$queryRaw<ProvRow[]>`
    SELECT x.id, x."userId", coalesce(gp."gameFamily", x."gameVariant") AS game, n.name AS node, x."createdAt", x.status::text AS status, false AS archived
    FROM "Server" x JOIN "User" u ON u.id = x."userId" LEFT JOIN "GamePlan" gp ON gp.id = x."gamePlanId" LEFT JOIN "Node" n ON n.id = x."nodeId"
    WHERE ${realUser("u")} AND x."createdAt" >= ${s.from} AND x."createdAt" < ${s.to}
    UNION ALL
    SELECT a."originalId", a."userId", a."gameFamily", a."nodeName", a."provisionedAt", NULL, true
    FROM "ServerArchive" a JOIN "User" u ON u.id = a."userId"
    WHERE ${realUser("u")} AND a."provisionedAt" >= ${s.from} AND a."provisionedAt" < ${s.to}`;
}

type ReadyRow = { game: string | null; node: string | null; ms: number };

async function timeToReady(s: Span): Promise<ReadyRow[]> {
  return db.$queryRaw<ReadyRow[]>`
    SELECT coalesce(gp."gameFamily", x."gameVariant", 'VPS') AS game, n.name AS node,
      (EXTRACT(EPOCH FROM (coalesce(j."finishedAt", j."updatedAt") - j."createdAt")) * 1000)::float AS ms
    FROM "Job" j JOIN "Server" x ON x.id = j."serverId" JOIN "User" u ON u.id = x."userId"
    LEFT JOIN "GamePlan" gp ON gp.id = x."gamePlanId" LEFT JOIN "Node" n ON n.id = x."nodeId"
    WHERE j.type = 'PROVISION' AND j.status = 'DONE' AND ${realUser("u")} AND j."createdAt" >= ${s.from} AND j."createdAt" < ${s.to}`;
}

export async function collectProvisioning(
  r: ReportRange,
  provisionFails: { userId: string | null; game: string | null; nodeId: string | null; serverId: string | null; msg: string | null }[],
  prevFailCount: number,
): Promise<{ section: ReportSection; byGame: GroupRate[]; byNode: GroupRate[]; stale: { id: string; hostname: string; userId: string; step: string; since: Date }[] }> {
  const cur: Span = { from: r.from, to: r.to };
  const [ordered, orderedPrev, ready, readyPrev, stale, nodes] = await Promise.all([
    serversOrdered(cur),
    serversOrdered({ from: r.prevFrom, to: r.prevTo }),
    timeToReady(cur),
    timeToReady({ from: r.prevFrom, to: r.prevTo }),
    db.$queryRaw<{ id: string; hostname: string; userId: string; step: string; since: Date }[]>`
      SELECT x.id, x.hostname, x."userId", left(x."provisioningStep", 120) AS step, x."updatedAt" AS since
      FROM "Server" x JOIN "User" u ON u.id = x."userId"
      WHERE ${realUser("u")} AND x.status = 'RUNNING' AND x."provisioningStep" IS NOT NULL AND x."provisioningStep" <> ''
        AND x."updatedAt" < now() - interval '30 minutes'
      ORDER BY x."updatedAt" ASC LIMIT 50`,
    db.node.findMany({ select: { id: true, name: true } }),
  ]);
  const nodeName = new Map(nodes.map((n) => [n.id, n.name]));

  // Attribute each PROVISION_FAILED (real users only — the funnel query already
  // dropped internal accounts) to a game: from the event's own detail (new
  // events), else the same user's most recent server ordered in the period.
  const byUser = new Map<string, ProvRow[]>();
  for (const o of ordered) {
    const a = byUser.get(o.userId) ?? [];
    a.push(o);
    byUser.set(o.userId, a);
  }
  const gameOfFail = (f: (typeof provisionFails)[number]) => {
    if (f.game) return f.game;
    if (f.serverId) {
      const hit = ordered.find((o) => o.id === f.serverId);
      if (hit?.game) return hit.game;
    }
    const cands = (f.userId && byUser.get(f.userId)) || [];
    const last = cands.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())[0];
    return last ? last.game ?? "VPS" : "Unknown";
  };
  const nodeOfFail = (f: (typeof provisionFails)[number]) => {
    if (f.nodeId) return nodeName.get(f.nodeId) ?? f.nodeId;
    const cands = (f.userId && byUser.get(f.userId)) || [];
    const last = cands.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())[0];
    return last?.node ?? "Unknown";
  };
  const groupRates = (keyOrder: (o: ProvRow) => string, keyFail: (f: (typeof provisionFails)[number]) => string): GroupRate[] => {
    const m = new Map<string, GroupRate>();
    for (const o of ordered) {
      const k = keyOrder(o);
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, examples: [], userIds: [] };
      g.total++;
      m.set(k, g);
    }
    for (const f of provisionFails) {
      const k = keyFail(f);
      const g = m.get(k) ?? { key: k, label: k, total: 0, failed: 0, examples: [], userIds: [] };
      g.failed++;
      if (f.msg && g.examples!.length < 3) {
        const msg = normalizeMessage(f.msg, 120);
        if (!g.examples!.includes(msg)) g.examples!.push(msg);
      }
      if (f.userId && !g.userIds!.includes(f.userId)) g.userIds!.push(f.userId);
      m.set(k, g);
    }
    // Attempts can fail several times for one order: total is "orders + failed attempts" so a rate stays ≤ 100%.
    for (const g of m.values()) g.total = Math.max(g.total, 0) + g.failed;
    return [...m.values()].sort((a, b) => b.failed - a.failed || b.total - a.total);
  };
  const byGame = groupRates((o) => o.game ?? "VPS", gameOfFail);
  const byNode = groupRates((o) => o.node ?? "Unknown", nodeOfFail);
  const ms = ready.map((x) => x.ms).filter((x) => x > 0);
  const msPrev = readyPrev.map((x) => x.ms).filter((x) => x > 0);
  const readyByGame = new Map<string, number[]>();
  for (const x of ready) {
    const a = readyByGame.get(x.game ?? "VPS") ?? [];
    a.push(x.ms);
    readyByGame.set(x.game ?? "VPS", a);
  }
  const fails = provisionFails.length;
  const attempts = ordered.length + fails;
  const prevAttempts = orderedPrev.length + prevFailCount;
  const metrics: Metric[] = [
    { key: "servers_ordered", domain: "provisioning", label: "Servers ordered (real customers)", unit: "count", cur: ordered.length, prev: orderedPrev.length, higherIsBetter: true },
    { key: "provision_failures", domain: "provisioning", label: "Provisioning failures", unit: "count", cur: fails, prev: prevFailCount, higherIsBetter: false, drill: "provision_failures" },
    {
      key: "provision_fail_rate",
      domain: "provisioning",
      label: "Provisioning failure rate (per attempt)",
      unit: "ratio",
      cur: attempts ? fails / attempts : null,
      prev: prevAttempts ? prevFailCount / prevAttempts : null,
      num: fails,
      den: attempts,
      prevNum: prevFailCount,
      prevDen: prevAttempts,
      higherIsBetter: false,
    },
    { key: "time_to_ready_p50", domain: "provisioning", label: "Time to ready (median)", unit: "ms", cur: percentile(ms, 50), prev: percentile(msPrev, 50), n: ms.length, prevN: msPrev.length, higherIsBetter: false },
    { key: "time_to_ready_p90", domain: "provisioning", label: "Time to ready (90th percentile)", unit: "ms", cur: percentile(ms, 90), prev: percentile(msPrev, 90), n: ms.length, prevN: msPrev.length, higherIsBetter: false },
    { key: "stale_provisioning", domain: "provisioning", label: "Running servers still showing an install step", unit: "count", cur: stale.length, prev: null, higherIsBetter: false, note: "Right now, not period-bound." },
  ];
  const fmtMin = (v: number | null) => (v == null ? "—" : `${(v / 60_000).toFixed(1)} min`);
  return {
    section: {
      domain: "provisioning",
      metrics,
      tables: [
        {
          key: "prov_game",
          title: "Provisioning by game / product",
          head: ["Game / product", "Attempts", "Failed", "Failure rate", "Median time to ready", "Typical error"],
          rows: byGame.slice(0, 15).map((g) => [g.label, g.total, g.failed, g.total ? `${Math.round((g.failed / g.total) * 100)}%` : "—", fmtMin(percentile(readyByGame.get(g.key) ?? [], 50)), g.examples?.[0] ?? ""]),
        },
        { key: "prov_node", title: "Provisioning by node", head: ["Node", "Attempts", "Failed", "Failure rate"], rows: byNode.slice(0, 10).map((g) => [g.label, g.total, g.failed, g.total ? `${Math.round((g.failed / g.total) * 100)}%` : "—"]) },
        ...(stale.length
          ? [{ key: "stale", title: "Running servers whose install step never cleared", head: ["Server", "Step text", "Unchanged since"], rows: stale.slice(0, 15).map((s) => [s.hostname, s.step, s.since.toISOString().slice(0, 16).replace("T", " ")]) }]
          : []),
      ],
      ranked: [],
      notes: [
        "Failures are the worker's terminal PROVISION_FAILED events for real customers; QA/internal accounts are excluded. Older failure events carry no game, so they are attributed to that customer's most recent order in the period.",
        "Time to ready = PROVISION job created → finished, for servers that still exist.",
      ],
    },
    byGame,
    byNode,
    stale,
  };
}

// ---------------------------------------------------------------------------
// Product usage
// ---------------------------------------------------------------------------

async function usageRows(s: Span): Promise<{ action: string; n: number; users: number }[]> {
  return db.$queryRaw<{ action: string; n: number; users: number }[]>`
    SELECT a.action, count(*)::int AS n, count(DISTINCT a."userId")::int AS users
    FROM "AuditLog" a JOIN "User" u ON u.id = a."userId"
    WHERE ${realUser("u")} AND a."createdAt" >= ${s.from} AND a."createdAt" < ${s.to}
      AND (a.detail IS NULL OR a.detail NOT LIKE '%[admin:%')
    GROUP BY 1`;
}

export async function collectUsage(r: ReportRange): Promise<{ section: ReportSection }> {
  const [cur, prev, active, activePrev] = await Promise.all([
    usageRows({ from: r.from, to: r.to }),
    usageRows({ from: r.prevFrom, to: r.prevTo }),
    db.$queryRaw<{ n: number }[]>`SELECT count(DISTINCT s."userId")::int AS n FROM "UserSession" s JOIN "User" u ON u.id = s."userId" WHERE ${realUser("u")} AND s."lastSeenAt" >= ${r.from} AND s."createdAt" < ${r.to}`,
    db.$queryRaw<{ n: number }[]>`SELECT count(DISTINCT v."userId")::int AS n FROM "Visit" v JOIN "User" u ON u.id = v."userId" WHERE ${realUser("u")} AND v.kind = 'portal' AND v."createdAt" >= ${r.from} AND v."createdAt" < ${r.to}`,
  ]);
  const cat = (rows: typeof cur) => {
    const m = new Map<string, { n: number; users: number }>();
    for (const x of rows) {
      const c = usageCategory(x.action);
      if (!c) continue;
      const e = m.get(c) ?? { n: 0, users: 0 };
      e.n += x.n;
      e.users = Math.max(e.users, x.users); // distinct-users per category is approximated by its busiest action
      m.set(c, e);
    }
    return m;
  };
  const c = cat(cur);
  const p = cat(prev);
  const total = [...c.values()].reduce((a, b) => a + b.n, 0);
  const totalPrev = [...p.values()].reduce((a, b) => a + b.n, 0);
  const ranked: Ranked[] = [...c.entries()].sort((a, b) => b[1].n - a[1].n).map(([label, v]) => ({ label, value: v.n, prev: p.get(label)?.n ?? 0, hint: `${v.users}+ customers` }));
  const actions = cur.filter((x) => usageCategory(x.action)).sort((a, b) => b.n - a.n).slice(0, 15);
  return {
    section: {
      domain: "usage",
      metrics: [
        { key: "panel_actions", domain: "usage", label: "Panel actions by customers", unit: "count", cur: total, prev: totalPrev, higherIsBetter: true },
        { key: "portal_active", domain: "usage", label: "Customers active in the portal", unit: "count", cur: activePrev[0]?.n ?? 0, prev: null, higherIsBetter: true, note: `${active[0]?.n ?? 0} had a signed-in session in the period.` },
      ],
      tables: [{ key: "actions", title: "Most used panel actions", head: ["Action", "Times", "Customers"], rows: actions.map((a) => [a.action, a.n, a.users]) }],
      ranked: [{ key: "usage_categories", title: "Panel usage by area", rows: ranked }],
      notes: ["From the audit log: customer-initiated actions only (admin-on-behalf actions are excluded). File-manager browsing and SFTP are not audited, so Files is under-counted."],
    },
  };
}

// ---------------------------------------------------------------------------
// Support
// ---------------------------------------------------------------------------

export async function collectSupport(r: ReportRange, payingCustomers: number): Promise<{ section: ReportSection; friction: Pick<FrictionInputs, "unansweredTickets" | "ticketFirstResponseP50Ms" | "ticketFirstResponsePrevP50Ms" | "chatHandoffs" | "botUnanswered"> }> {
  const [sup, tickets, chats, chatsPrev, bot] = await Promise.all([
    supportInsights(r, payingCustomers),
    db.$queryRaw<{ subject: string }[]>`
      SELECT t.subject FROM "Ticket" t JOIN "User" u ON u.id = t."userId" WHERE ${realUser("u")} AND t."createdAt" >= ${r.from} AND t."createdAt" < ${r.to} LIMIT 5000`,
    db.$queryRaw<{ n: number; esc: number; first: string | null }[]>`
      SELECT count(*)::int AS n, count(*) FILTER (WHERE c."botEscalatedAt" IS NOT NULL)::int AS esc, NULL AS first
      FROM "ChatConversation" c LEFT JOIN "User" u ON u.id = c."userId"
      WHERE c."createdAt" >= ${r.from} AND c."createdAt" < ${r.to} AND (c."userId" IS NULL OR ${realUser("u")})`,
    db.$queryRaw<{ n: number; esc: number }[]>`
      SELECT count(*)::int AS n, count(*) FILTER (WHERE c."botEscalatedAt" IS NOT NULL)::int AS esc
      FROM "ChatConversation" c WHERE c."createdAt" >= ${r.prevFrom} AND c."createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ kind: string; q: string }[]>`
      SELECT kind, left(question, 160) AS q FROM "KbBotLog" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to} LIMIT 5000`,
  ]);
  const chatFirst = await db.$queryRaw<{ body: string }[]>`
    SELECT DISTINCT ON (m."conversationId") left(m.body, 200) AS body FROM "ChatMessage" m JOIN "ChatConversation" c ON c.id = m."conversationId"
    WHERE c."createdAt" >= ${r.from} AND c."createdAt" < ${r.to} AND m.sender = 'user' ORDER BY m."conversationId", m."createdAt" ASC LIMIT 2000`.catch(() => []);
  const topics = new Map<string, number>();
  for (const t of tickets) topics.set(topicOf(t.subject), (topics.get(topicOf(t.subject)) ?? 0) + 1);
  for (const c of chatFirst) topics.set(topicOf(c.body), (topics.get(topicOf(c.body)) ?? 0) + 1);
  const botKinds = new Map<string, number>();
  for (const b of bot) botKinds.set(b.kind, (botKinds.get(b.kind) ?? 0) + 1);
  const unanswered = bot.filter((b) => /miss|none|fallback|unanswered|no_match/i.test(b.kind));
  const uq = new Map<string, number>();
  for (const b of unanswered) {
    const k = normalizeMessage(b.q, 80).toLowerCase();
    uq.set(k, (uq.get(k) ?? 0) + 1);
  }
  const ch = chats[0] ?? { n: 0, esc: 0 };
  const chp = chatsPrev[0] ?? { n: 0, esc: 0 };
  const metrics: Metric[] = [
    { key: "tickets", domain: "support", label: "Tickets opened", unit: "count", cur: sup.created, prev: sup.createdPrev, higherIsBetter: false, drill: "tickets" },
    { key: "chats", domain: "support", label: "Live-chat conversations", unit: "count", cur: ch.n, prev: chp.n, higherIsBetter: true },
    { key: "chat_handoff_rate", domain: "support", label: "Chats escalated from the bot to a human", unit: "ratio", cur: ch.n ? ch.esc / ch.n : null, prev: chp.n ? chp.esc / chp.n : null, num: ch.esc, den: ch.n, prevNum: chp.esc, prevDen: chp.n, higherIsBetter: false },
    { key: "first_response_p50", domain: "support", label: "Ticket first response (median)", unit: "ms", cur: sup.firstResponse.ok ? sup.firstResponse.value.p50 : null, prev: sup.firstResponsePrev.ok ? sup.firstResponsePrev.value.p50 : null, n: sup.firstResponse.ok ? sup.firstResponse.value.n : 0, prevN: sup.firstResponsePrev.ok ? 10 : 0, higherIsBetter: false },
    { key: "unanswered_tickets", domain: "support", label: "Tickets with no staff reply yet", unit: "count", cur: sup.unanswered, prev: null, higherIsBetter: false },
    { key: "awaiting_staff", domain: "support", label: "Tickets awaiting staff right now", unit: "count", cur: sup.awaitingStaffNow, prev: null, higherIsBetter: false },
  ];
  return {
    section: {
      domain: "support",
      metrics,
      tables: sup.oldestAwaiting.length
        ? [{ key: "awaiting", title: "Oldest tickets waiting on staff", head: ["Subject", "Waiting"], rows: sup.oldestAwaiting.map((t) => [t.subject, `${Math.round(t.waitingMs / 3_600_000)}h`]) }]
        : [],
      ranked: [
        { key: "topics", title: "What customers asked about (tickets + first chat message)", rows: [...topics.entries()].sort((a, b) => b[1] - a[1]).map(([label, value]) => ({ label, value })) },
        { key: "bot_kinds", title: "Help-bot answers by kind", rows: [...botKinds.entries()].sort((a, b) => b[1] - a[1]).map(([label, value]) => ({ label, value })) },
      ],
      notes: ["Topics are keyword-classified (no AI): billing, connection, mods, setup, performance, account, provisioning, sales."],
    },
    friction: {
      unansweredTickets: sup.unanswered,
      ticketFirstResponseP50Ms: sup.firstResponse.ok ? sup.firstResponse.value.p50 : null,
      ticketFirstResponsePrevP50Ms: sup.firstResponsePrev.ok ? sup.firstResponsePrev.value.p50 : null,
      chatHandoffs: { conversations: ch.n, escalated: ch.esc, prevConversations: chp.n, prevEscalated: chp.esc },
      botUnanswered: { count: unanswered.length, top: [...uq.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([label, value]) => ({ label, value })) },
    },
  };
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

type ErrAgg = { context: string; source: string; n: number };

async function errorDaily(s: Span): Promise<ErrAgg[] | null> {
  try {
    return await db.$queryRaw<ErrAgg[]>`
      SELECT context, source, sum(count)::int AS n FROM "ErrorDaily" WHERE date >= date_trunc('day', ${s.from}::timestamp) AND date < ${s.to} GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 200`;
  } catch {
    return null;
  }
}

async function http5xx(s: Span): Promise<{ route: string; status: number; hits: number }[] | null> {
  try {
    return await db.$queryRaw<{ route: string; status: number; hits: number }[]>`
      SELECT route, status, sum(hits)::int AS hits FROM "HttpErrorDaily" WHERE date >= date_trunc('day', ${s.from}::timestamp) AND date < ${s.to} GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 100`;
  } catch {
    return null;
  }
}

export async function collectErrors(r: ReportRange): Promise<{ section: ReportSection; friction: Pick<FrictionInputs, "deployPathErrors" | "newErrorTypes"> }> {
  const cur: Span = { from: r.from, to: r.to };
  const prev: Span = { from: r.prevFrom, to: r.prevTo };
  const [ed, edp, h, hp, fresh, recent] = await Promise.all([
    errorDaily(cur),
    errorDaily(prev),
    http5xx(cur),
    http5xx(prev),
    db.$queryRaw<{ context: string; message: string; count: number; source: string }[]>`
      SELECT context, left(message, 200) AS message, count, source FROM "ErrorLog"
      WHERE "firstSeen" >= ${r.from} AND "firstSeen" < ${r.to} AND level = 'error' ORDER BY count DESC LIMIT 25`,
    // Fallback when ErrorDaily isn't deployed: fingerprints active in the period (lifetime counts — approximate).
    db.$queryRaw<ErrAgg[]>`
      SELECT context, source, sum(count)::int AS n FROM "ErrorLog" WHERE "lastSeen" >= ${r.from} AND "lastSeen" < ${r.to} GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 100`,
  ]);
  const precise = ed !== null && ed.length > 0;
  const rows = precise ? ed! : recent;
  const total = rows.reduce((a, b) => a + b.n, 0);
  const totalPrev = precise && edp ? edp.reduce((a, b) => a + b.n, 0) : null;
  const money = rows.filter((x) => isMoneyPath(x.context));
  const moneyPrev = precise && edp ? edp.filter((x) => isMoneyPath(x.context)) : null;
  const h5 = h ?? [];
  const h5money = h5.filter((x) => isMoneyPath(x.route));
  const h5prevMoney = (hp ?? []).filter((x) => isMoneyPath(x.route));
  const metrics: Metric[] = [
    { key: "error_events", domain: "errors", label: precise ? "Logged errors & warnings" : "Logged errors (active fingerprints, lifetime counts)", unit: "count", cur: total, prev: totalPrev, higherIsBetter: false, drill: "/admin/logs?tab=errors" },
    { key: "money_path_errors", domain: "errors", label: "Errors on signup / deploy / payment code", unit: "count", cur: money.reduce((a, b) => a + b.n, 0), prev: moneyPrev ? moneyPrev.reduce((a, b) => a + b.n, 0) : null, higherIsBetter: false },
    { key: "http_5xx", domain: "errors", label: "Server errors (HTTP 5xx) seen by people", unit: "count", cur: h ? h5.reduce((a, b) => a + b.hits, 0) : null, prev: hp ? (hp ?? []).reduce((a, b) => a + b.hits, 0) : null, higherIsBetter: false, note: h ? undefined : "Counting starts once HttpErrorDaily is deployed." },
    { key: "new_error_types", domain: "errors", label: "New kinds of error first seen", unit: "count", cur: fresh.length, prev: null, higherIsBetter: false },
  ];
  return {
    section: {
      domain: "errors",
      metrics,
      tables: [
        { key: "by_context", title: "Errors by where they happened", head: ["Context", "Source", "Occurrences"], rows: rows.slice(0, 15).map((x) => [x.context, x.source, x.n]) },
        ...(h5.length ? [{ key: "http5xx", title: "HTTP 5xx by route (human traffic)", head: ["Route", "Status", "Hits"], rows: h5.slice(0, 15).map((x) => [x.route, x.status, x.hits]) }] : []),
        ...(fresh.length ? [{ key: "fresh", title: "New kinds of error", head: ["Context", "Message", "Count"], rows: fresh.slice(0, 10).map((x) => [x.context, x.message, x.count]) }] : []),
      ],
      ranked: [],
      notes: [
        precise
          ? "Per-day counts from ErrorDaily (every logError/logEvent call, deduped by fingerprint)."
          : "ErrorDaily has no rows for this period yet, so these are lifetime counts of error fingerprints that were active in the period — read them as 'which errors are live', not exact period counts.",
      ],
    },
    friction: {
      deployPathErrors: {
        events: money.reduce((a, b) => a + b.n, 0) + h5money.reduce((a, b) => a + b.hits, 0),
        prevEvents: (moneyPrev ?? []).reduce((a, b) => a + b.n, 0) + h5prevMoney.reduce((a, b) => a + b.hits, 0),
        contexts: [...money.map((x) => ({ label: x.context, value: x.n })), ...h5money.map((x) => ({ label: `HTTP ${x.status} ${x.route}`, value: x.hits }))].sort((a, b) => b.value - a.value).slice(0, 6),
        instrumented: precise,
      },
      newErrorTypes: fresh.map((f) => ({ context: f.context, message: f.message, count: f.count, source: f.source })),
    },
  };
}

// ---------------------------------------------------------------------------
// Fleet & capacity
// ---------------------------------------------------------------------------

export async function collectFleet(r: ReportRange): Promise<{ section: ReportSection; friction: Pick<FrictionInputs, "nodeAlerts" | "capacity"> }> {
  const [alerts, openNow, cap] = await Promise.all([
    db.$queryRaw<{ severity: string; nodeName: string; dimension: string; n: number }[]>`
      SELECT severity, "nodeName", dimension, count(*)::int AS n FROM "NodeAlert" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to} GROUP BY 1, 2, 3 ORDER BY 4 DESC`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "NodeAlert" WHERE status = 'OPEN'`,
    capacityInsights().catch(() => []),
  ]);
  const crit = alerts.filter((a) => /crit/i.test(a.severity)).reduce((s, a) => s + a.n, 0);
  const warn = alerts.filter((a) => !/crit/i.test(a.severity)).reduce((s, a) => s + a.n, 0);
  const capacity = (cap as Awaited<ReturnType<typeof capacityInsights>>).map((c) => {
    const x = c as unknown as { name?: string; node?: string; daysToFull?: { ok: boolean; value?: number } | number | null; usedPct?: number; committedPct?: number; capacityRamMB?: number; committedRamMB?: number };
    const days = typeof x.daysToFull === "number" ? x.daysToFull : x.daysToFull && typeof x.daysToFull === "object" && x.daysToFull.ok ? x.daysToFull.value ?? null : null;
    const used = x.committedPct ?? x.usedPct ?? (x.capacityRamMB && x.committedRamMB ? x.committedRamMB / x.capacityRamMB : 0);
    return { node: x.name ?? x.node ?? "node", daysToFull: days, usedPct: used > 1 ? used / 100 : used };
  });
  return {
    section: {
      domain: "fleet",
      metrics: [
        { key: "node_alerts_critical", domain: "fleet", label: "Critical node alerts raised", unit: "count", cur: crit, prev: null, higherIsBetter: false, drill: "/admin/monitoring" },
        { key: "node_alerts_warning", domain: "fleet", label: "Warning node alerts raised", unit: "count", cur: warn, prev: null, higherIsBetter: false },
        { key: "node_alerts_open", domain: "fleet", label: "Node alerts open now", unit: "count", cur: openNow[0]?.n ?? 0, prev: null, higherIsBetter: false },
      ],
      tables: [
        ...(alerts.length ? [{ key: "alerts", title: "Node alerts in this period", head: ["Node", "Dimension", "Severity", "Times"], rows: alerts.slice(0, 15).map((a) => [a.nodeName, a.dimension, a.severity, a.n]) }] : []),
        ...(capacity.length ? [{ key: "capacity", title: "RAM commitment by node (now)", head: ["Node", "Committed", "Days until full at current growth"], rows: capacity.map((c) => [c.node, `${Math.round(c.usedPct * 100)}%`, c.daysToFull == null ? "not growing" : c.daysToFull]) }] : []),
      ],
      ranked: [],
    },
    friction: { nodeAlerts: { critical: crit, warning: warn, open: openNow[0]?.n ?? 0, top: alerts.slice(0, 5).map((a) => ({ label: `${a.nodeName} ${a.dimension} (${a.severity})`, value: a.n })) }, capacity },
  };
}

// ---------------------------------------------------------------------------
// Email deliverability
// ---------------------------------------------------------------------------

const TRANSACTIONAL = /^(email_verify|password_reset|invoice_new|payment_|server_|ticket_reply|card_|renewal_|provision|welcome|receipt|staff_dm|generic_notification|checkout_payment_retry)/;

export async function collectEmail(r: ReportRange): Promise<{ section: ReportSection; failures: GroupRate[] }> {
  const [rows, prev, supp] = await Promise.all([
    db.$queryRaw<{ template: string | null; sent: number; failed: number; opened: number; clicked: number }[]>`
      SELECT template, count(*) FILTER (WHERE status = 'SENT')::int AS sent, count(*) FILTER (WHERE status = 'FAILED')::int AS failed,
        count(*) FILTER (WHERE "openedAt" IS NOT NULL)::int AS opened, count(*) FILTER (WHERE "clickedAt" IS NOT NULL)::int AS clicked
      FROM "EmailLog" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to} GROUP BY 1`,
    db.$queryRaw<{ sent: number; failed: number; opened: number }[]>`
      SELECT count(*) FILTER (WHERE status = 'SENT')::int AS sent, count(*) FILTER (WHERE status = 'FAILED')::int AS failed, count(*) FILTER (WHERE "openedAt" IS NOT NULL)::int AS opened
      FROM "EmailLog" WHERE "createdAt" >= ${r.prevFrom} AND "createdAt" < ${r.prevTo}`,
    db.$queryRaw<{ n: number }[]>`SELECT count(*)::int AS n FROM "Suppression" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to}`.catch(() => [{ n: 0 }]),
  ]);
  // Template keys like "checkout_payment_retry:<pi id>" collapse to their prefix.
  const m = new Map<string, { sent: number; failed: number; opened: number; clicked: number }>();
  for (const x of rows) {
    const k = (x.template ?? "(untemplated)").split(":")[0];
    const e = m.get(k) ?? { sent: 0, failed: 0, opened: 0, clicked: 0 };
    e.sent += x.sent;
    e.failed += x.failed;
    e.opened += x.opened;
    e.clicked += x.clicked;
    m.set(k, e);
  }
  const all = [...m.entries()].map(([k, v]) => ({ k, ...v })).sort((a, b) => b.sent + b.failed - (a.sent + a.failed));
  const sent = all.reduce((a, b) => a + b.sent, 0);
  const failed = all.reduce((a, b) => a + b.failed, 0);
  const opened = all.reduce((a, b) => a + b.opened, 0);
  const clicked = all.reduce((a, b) => a + b.clicked, 0);
  const p = prev[0] ?? { sent: 0, failed: 0, opened: 0 };
  const failures: GroupRate[] = all.filter((x) => x.failed > 0).map((x) => ({ key: x.k, label: x.k, total: x.sent + x.failed, failed: x.failed, examples: [TRANSACTIONAL.test(x.k) ? "transactional" : "marketing"] }));
  return {
    section: {
      domain: "email",
      metrics: [
        { key: "emails_sent", domain: "email", label: "Emails sent", unit: "count", cur: sent, prev: p.sent, higherIsBetter: true, drill: "/admin/logs?tab=email" },
        { key: "email_fail_rate", domain: "email", label: "Emails that failed to send", unit: "ratio", cur: sent + failed ? failed / (sent + failed) : null, prev: p.sent + p.failed ? p.failed / (p.sent + p.failed) : null, num: failed, den: sent + failed, prevNum: p.failed, prevDen: p.sent + p.failed, higherIsBetter: false },
        { key: "email_open_rate", domain: "email", label: "Open rate (pixel — inflated by privacy proxies)", unit: "ratio", cur: sent ? opened / sent : null, prev: p.sent ? p.opened / p.sent : null, num: opened, den: sent, prevNum: p.opened, prevDen: p.sent, higherIsBetter: true },
        { key: "email_click_rate", domain: "email", label: "Click rate", unit: "ratio", cur: sent ? clicked / sent : null, prev: null, num: clicked, den: sent, higherIsBetter: true },
        { key: "suppressions", domain: "email", label: "New suppressions (bounce / complaint / unsubscribe)", unit: "count", cur: supp[0]?.n ?? 0, prev: null, higherIsBetter: false },
      ],
      tables: [
        {
          key: "templates",
          title: "Email by template",
          head: ["Template", "Sent", "Failed", "Opened", "Clicked"],
          rows: all.slice(0, 20).map((x) => [x.k, x.sent, x.failed, x.sent ? `${Math.round((x.opened / x.sent) * 100)}%` : "—", x.sent ? `${Math.round((x.clicked / x.sent) * 100)}%` : "—"]),
        },
      ],
      ranked: [],
      notes: ["'Failed' means our SMTP send was refused; a later bounce is not visible here. Opens are pixel-based and overstated by Apple Mail Privacy Protection."],
    },
    failures,
  };
}

