  let shape: ActivityShape | null = null;
  try {
    const rows = await db.$queryRaw<{ table_name: string; column_name: string }[]>`
      SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = ANY(${TABLES}::text[])`;
    for (const t of TABLES) {
      const cols = new Set(rows.filter((r) => r.table_name === t).map((r) => r.column_name));
      if (!cols.size) continue;
      const pick = (c: readonly string[]) => c.find((x) => cols.has(x)) ?? null;
      const kind = pick(COLS.kind);
      const at = pick(COLS.at);
      if (!kind || !at) continue;
      shape = { table: t, kind, at, user: pick(COLS.user), data: pick(COLS.data), session: pick(COLS.session) };
      break;
    }
  } catch {
    shape = null;
  }
  cached = { shape, t: Date.now() };
  return shape;
}

export type ActivityRow = { kind: string; at: Date; userId: string | null; sessionId: string | null; data: Record<string, unknown> };

const q = (s: string) => Prisma.raw(`"${s.replace(/"/g, "")}"`);

/** Activity rows in a span whose kind matches `kindPattern` (a SQL ~* regex). null = table absent. */
export async function activityRows(s: Span, kindPattern: string, opts: { userId?: string; limit?: number } = {}): Promise<ActivityRow[] | null> {
  const sh = await activityShape();
  if (!sh) return null;
  try {
    const dataSel = sh.data ? Prisma.sql`${q(sh.data)}::text` : Prisma.sql`NULL::text`;
    const userSel = sh.user ? Prisma.sql`${q(sh.user)}` : Prisma.sql`NULL::text`;
    const sessSel = sh.session ? Prisma.sql`${q(sh.session)}` : Prisma.sql`NULL::text`;
    const userWhere = opts.userId && sh.user ? Prisma.sql`AND ${q(sh.user)} = ${opts.userId}` : Prisma.empty;
    const rows = await db.$queryRaw<{ kind: string; at: Date; userId: string | null; sessionId: string | null; data: string | null }[]>`
      SELECT ${q(sh.kind)}::text AS kind, ${q(sh.at)} AS at, ${userSel} AS "userId", ${sessSel} AS "sessionId", ${dataSel} AS data
      FROM ${q(sh.table)}
      WHERE ${q(sh.at)} >= ${s.from} AND ${q(sh.at)} < ${s.to} AND ${q(sh.kind)}::text ~* ${kindPattern} ${userWhere}
      ORDER BY ${q(sh.at)} ASC LIMIT ${opts.limit ?? 50_000}`;
    return rows.map((r) => ({ kind: r.kind, at: r.at, userId: r.userId, sessionId: r.sessionId, data: parseData(r.data) }));
  } catch {
    return null;
  }
}

function parseData(s: string | null): Record<string, unknown> {
  if (!s) return {};
  try {
    const v = JSON.parse(s);
    return v && typeof v === "object" ? (v as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

/** First string value found under any of `keys` (snake or camel case), uppercased if `upper`. */
export function field(d: Record<string, unknown>, keys: string[], upper = false): string | null {
  for (const k of keys) {
    const v = d[k];
    if (typeof v === "string" && v) return upper ? v.toUpperCase() : v;
  }
  return null;
}

export const PAYMENT_KINDS = "(payment|checkout|refund|dispute|chargeback|renewal|dunning|topup|top_up)";
export const FAILED_KIND = /(fail|declin|error)/i;
export const SUCCESS_KIND = /(succeed|success|paid|completed|captured)/i;
export const SOLD_OUT_KIND = "(sold_?out|capacity_refus|region_unavailable)";

