/**
 * Report aggregation entry point: `collectReport(range)` runs every domain's
 * queries (in parallel where independent), assembles one JSON-able ReportData,
 * and records — never hides — any domain whose queries failed.
 *
 * All SQL is SELECT-only. A short in-process cache keeps a page reload, a CSV
 * export and a print view of the same range from re-running the whole set.
 */
import { db } from "@/lib/db";
import { activityRows, field, SOLD_OUT_KIND } from "./activity-source";
import { collectAcquisition, collectFunnel, collectSignups } from "./collect-growth";
import { collectPayments, collectRetention, collectRevenue } from "./collect-money";
import { collectEmail, collectErrors, collectFleet, collectProvisioning, collectSupport, collectUsage } from "./collect-ops";
import { realUser } from "./sql";
import type { ReportRange } from "./range";
import type { Domain, FrictionInputs, ReportData, ReportSection } from "./types";

const CACHE_MS = 60_000;
const cache = new Map<string, { at: number; data: Promise<ReportData> }>();

function cacheKey(r: ReportRange): string {
  // Running periods move with "now"; round to the minute so the cache still helps.
  return `${r.from.toISOString()}|${Math.floor(r.to.getTime() / 60_000)}|${r.tz}|${r.compare}`;
}

export function collectReport(r: ReportRange, opts: { fresh?: boolean } = {}): Promise<ReportData> {
  const k = cacheKey(r);
  const hit = cache.get(k);
  if (!opts.fresh && hit && Date.now() - hit.at < CACHE_MS) return hit.data;
  const p = build(r);
  cache.set(k, { at: Date.now(), data: p });
  p.catch(() => cache.delete(k));
  if (cache.size > 30) for (const [key, v] of cache) if (Date.now() - v.at > CACHE_MS) cache.delete(key);
  return p;
}

async function safe<T>(domain: Domain, failures: ReportData["failures"], fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch (e) {
    failures.push({ domain, message: String((e as Error)?.message ?? e).split("\n")[0].slice(0, 300) });
    console.error(`[reports] ${domain} failed`, e);
    return null;
  }
}

async function freeMcStats(r: ReportRange): Promise<FrictionInputs["freeMc"]> {
  const [row] = await db.$queryRaw<FrictionInputs["freeMc"][]>`
    WITH f AS (
      SELECT f.id, f."userId", f."firstWakeAt", f."firstMultiplayerAt", f."createdAt" FROM "FreeMinecraftServer" f JOIN "User" u ON u.id = f."userId"
      WHERE ${realUser("u")} AND f."createdAt" >= ${r.from} AND f."createdAt" < ${r.to}
    )
    SELECT count(*)::int AS created,
      count(*) FILTER (WHERE "firstWakeAt" IS NOT NULL)::int AS woken,
      count(*) FILTER (WHERE "firstMultiplayerAt" IS NOT NULL)::int AS multiplayer,
      (SELECT count(*) FROM "FreeMinecraftUpsellEvent" e WHERE e."userId" IN (SELECT "userId" FROM f) AND e.action = 'SHOWN')::int AS "upsellShown",
      (SELECT count(*) FROM "FreeMinecraftUpsellEvent" e WHERE e."userId" IN (SELECT "userId" FROM f) AND e.action = 'CLICKED')::int AS "upsellClicked",
      (SELECT count(DISTINCT s."userId") FROM "Server" s WHERE s."isFree" = false AND s."userId" IN (SELECT "userId" FROM f))::int AS upgraded
    FROM f`;
  return row ?? { created: 0, woken: 0, multiplayer: 0, upsellShown: 0, upsellClicked: 0, upgraded: 0 };
}

const EMPTY_FRICTION: FrictionInputs = {
  verification: { eligible: 0, unverified: 0, prevEligible: 0, prevUnverified: 0, verifyEmailsSent: 0, verifyEmailsFailed: 0, unverifiedUserIds: [] },
  activation: { signups: 0, activated: 0, prevSignups: 0, prevActivated: 0, medianHoursToDeploy: null },
  declinesByCountry: [],
  declinesByBrand: [],
  declineReasons: [],
  authFailures: 0,
  renewalDeclines: { count: 0, users: 0, reasons: [], userIds: [] },
  soldOut: { sessionsShown: 0, sessionsShownCompleted: 0, picks: [], instrumented: false },
  provisionByGame: [],
  provisionByNode: [],
  deployPathErrors: { events: 0, prevEvents: 0, contexts: [], instrumented: false },
  orderErrors: [],
  devices: [],
  emailFailures: [],
  newErrorTypes: [],
  unansweredTickets: 0,
  ticketFirstResponseP50Ms: null,
  ticketFirstResponsePrevP50Ms: null,
  chatHandoffs: { conversations: 0, escalated: 0, prevConversations: 0, prevEscalated: 0 },
  botUnanswered: { count: 0, top: [] },
  promoRenewals: { due: 0, renewed: 0 },
  winback: [],
  nodeAlerts: { critical: 0, warning: 0, open: 0, top: [] },
  capacity: [],
  capacityRefusals: [],
  segments: [],
  paymentByCountry: [],
  deviceSteps: [],
  internalUnflagged: 0,
  freeMc: { created: 0, woken: 0, multiplayer: 0, upsellShown: 0, upsellClicked: 0, upgraded: 0 },
  staleProvisioning: 0,
};

async function build(r: ReportRange): Promise<ReportData> {
  const failures: ReportData["failures"] = [];
  const f: FrictionInputs = structuredClone(EMPTY_FRICTION);

  const [acq, sig, fun, rev, pay, sup0, usage, err, fleet, email, freeMc] = await Promise.all([
    safe("acquisition", failures, () => collectAcquisition(r)),
    safe("signups", failures, () => collectSignups(r)),
    safe("funnel", failures, () => collectFunnel(r)),
    safe("revenue", failures, () => collectRevenue(r)),
    safe("payments", failures, () => collectPayments(r)),
    Promise.resolve(null),
    safe("usage", failures, () => collectUsage(r)),
    safe("errors", failures, () => collectErrors(r)),
    safe("fleet", failures, () => collectFleet(r)),
    safe("email", failures, () => collectEmail(r)),
    safe("signups", failures, () => freeMcStats(r)),
  ]);
  void sup0;
  const paying = rev?.payingCustomers ?? 0;
  const [prov, ret, sup] = await Promise.all([
    safe("provisioning", failures, () => collectProvisioning(r, fun?.agg.provisionFails ?? [], fun?.prevAgg.provisionFails.length ?? 0)),
    safe("retention", failures, () => collectRetention(r, { mrrCents: rev?.section.metrics.find((m) => m.key === "mrr")?.cur ?? 0, payingCustomers: paying })),
    safe("support", failures, () => collectSupport(r, paying)),
  ]);

  // Sold-out exposure from the shared activity table (if deployed).
  const sold = await safe("funnel", failures, () => activityRows({ from: r.from, to: r.to }, SOLD_OUT_KIND));

  if (sig) {
    f.verification = sig.verification;
    f.activation = sig.activation;
    f.segments = sig.segments.map(({ userIds: _u, ...rest }) => rest);
    f.internalUnflagged = sig.internalUnflagged;
    const devVisitors = new Map((acq?.section.ranked.find((x) => x.key === "devices")?.rows ?? []).map((x) => [x.label, x.value]));
    f.devices = sig.devices.map((d) => ({ ...d, visitors: devVisitors.get(d.device) ?? 0 }));
    for (const [k, v] of devVisitors) if (!f.devices.some((d) => d.device === k)) f.devices.push({ device: k, visitors: v, signups: 0, payers: 0 });
  }
  if (fun) {
    f.orderErrors = fun.agg.orderErrors;
    f.paymentByCountry = fun.agg.paymentByCountry;
    f.deviceSteps = fun.agg.deviceSteps;
    f.soldOut = fun.agg.soldOut;
  }
  if (sold && sold.length) {
    const keys = new Set(sold.map((s) => s.sessionId ?? s.userId ?? `${s.at.getTime()}`));
    const picks = new Map<string, number>();
    for (const s of sold) {
      const reg = field(s.data, ["region", "regionKey", "value"]) ?? "unknown";
      picks.set(reg, (picks.get(reg) ?? 0) + 1);
    }
    f.soldOut = { sessionsShown: keys.size, sessionsShownCompleted: 0, picks: [...picks.entries()].map(([region, count]) => ({ region, count })).sort((a, b) => b.count - a.count), instrumented: true };
  } else if (sold) f.soldOut.instrumented = true;
  if (pay) Object.assign(f, pay.friction);
  if (prov) {
    f.provisionByGame = prov.byGame;
    f.provisionByNode = prov.byNode;
    f.staleProvisioning = prov.stale.length;
  }
  if (err) {
    Object.assign(f, err.friction);
    f.capacityRefusals = err.capacityRefusals;
  }
  if (sup) Object.assign(f, sup.friction);
  if (fleet) Object.assign(f, fleet.friction);
  if (email) f.emailFailures = email.failures;
  if (rev) f.promoRenewals = rev.promo;
  if (ret) f.winback = ret.winback;
  if (freeMc) f.freeMc = freeMc;

  const sections: ReportSection[] = [
    acq?.section,
    sig?.section,
    fun?.section,
    rev?.section,
    pay?.section,
    prov?.section,
    usage?.section,
    ret?.section,
    sup?.section,
    err?.section,
    fleet?.section,
    email?.section,
  ].filter((s): s is ReportSection => !!s);

  return {
    generatedAt: new Date().toISOString(),
    range: {
      from: r.from.toISOString(),
      to: r.to.toISOString(),
      prevFrom: r.prevFrom.toISOString(),
      prevTo: r.prevTo.toISOString(),
      fromStr: r.fromStr,
      toStr: r.toStr,
      label: r.label,
      prevLabel: r.prevLabel,
      days: r.days,
      partial: r.partial,
      tz: r.tz,
      compare: r.compare,
      preset: r.preset,
    },
    avgOrderCents: rev?.avgOrderCents ?? null,
    arpuCents: rev?.arpuCents ?? null,
    sections,
    friction: f,
    failures,
  };
}

