];

function funnelsOf(d: ReportData) {
  // The full funnel objects aren't in sections (only their tables), so the
  // collector mirrors payment counts into friction via the funnel tables.
  return (d as ReportData & { funnels?: import("./types").ProductFunnel[] }).funnels ?? [];
}

// ---------------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------------

export function analyze(d: ReportData): ReportSummary {
  const ctx: Ctx = {
    d,
    cust: d.avgOrderCents ?? d.arpuCents ?? 1000,
    prevLabel: d.range.prevLabel,
    compare: d.range.compare !== "none",
    qs: rangeQuery({ preset: d.range.preset, fromStr: d.range.fromStr, toStr: d.range.toStr, tz: d.range.tz, compare: d.range.compare }),
  };
  const all: Finding[] = [...metricRules(ctx)];
  for (const rule of FRICTION_RULES) {
    try {
      all.push(...rule.run(ctx));
    } catch {
      /* a broken rule must never take the report down */
    }
  }
  // De-duplicate: a friction finding beats a generic change on the same thing.
  const seen = new Set<string>();
  const ranked = all
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
    .filter((f) => {
      if (seen.has(f.id)) return false;
      seen.add(f.id);
      return true;
    });
  // Executive summary: up to 8, at most 2 positives, at least the top 5 when there are 5.
  const findings: Finding[] = [];
  let positives = 0;
  for (const f of ranked) {
    if (findings.length >= 8) break;
    if (f.severity === "positive") {
      if (positives >= 2) continue;
      positives++;
    }
    findings.push(f);
  }
  return { headline: headline(d, ctx), findings, all: ranked, narrative: narrative(d, ctx) };
}

function changeWord(cur: number | null | undefined, prev: number | null | undefined, unit: Metric["unit"], ctx: Ctx): string {
  if (!ctx.compare || cur == null || prev == null) return "";
  if (prev === 0) return cur === 0 ? " (none in the previous period either)" : " (none the previous period)";
  const r = (cur - prev) / Math.abs(prev);
  if (Math.abs(r) < 0.03) return " (flat)";
  return ` (${r > 0 ? "up" : "down"} ${pctMove(r)} from ${fmtValue(prev, unit)})`;
}

export function headline(d: ReportData, ctx: Ctx): string {
  const e = metric(d, "earned");
  const o = metric(d, "new_orders");
  const s = metric(d, "signups");
  const mrr = metric(d, "mrr");
  const parts: string[] = [];
  const when = d.range.preset === "today" ? "So far today" : `Over ${d.range.label.toLowerCase().startsWith("last") ? `the ${d.range.label.toLowerCase()}` : d.range.label}`;
  if (e?.cur != null) parts.push(`Nxeon earned ${fmtCents(e.cur)}${changeWord(e.cur, e.prev, "cents", ctx)}`);
  if (o?.cur != null) parts.push(`took ${plural(o.cur, "new order")}${changeWord(o.cur, o.prev, "count", ctx)}`);
  if (s?.cur != null) parts.push(`and gained ${plural(s.cur, "new account")}${changeWord(s.cur, s.prev, "count", ctx)}`);
  let text = parts.length ? `${when}, ${parts.join(", ")}.` : `${when}: not enough data to summarise.`;
  if (mrr?.cur != null) text += ` MRR stands at ${fmtCents(mrr.cur)}.`;
  if (d.range.partial) text += " The period is still running, so comparisons use the same elapsed time.";
  return text;
}

function narrative(d: ReportData, ctx: Ctx): Partial<Record<Domain, string>> {
  const out: Partial<Record<Domain, string>> = {};
  for (const s of d.sections) {
    const shown = s.metrics.filter((m) => m.cur != null).slice(0, 4);
    if (!shown.length) {
      out[s.domain] = `No ${DOMAIN_LABELS[s.domain].toLowerCase()} data in this period.`;
      continue;
    }
    const lines = shown.map((m) => {
      const base = `${m.label}: ${fmtValue(m.cur, m.unit)}`;
      if (!ctx.compare || m.prev == null) return base;
      if (m.unit === "ratio") return `${base} (${fmtValue(m.prev, m.unit)} before)`;
      return `${base}${changeWord(m.cur, m.prev, m.unit, ctx)}`;
    });
    out[s.domain] = `${lines.join("; ")}.`;
  }
  for (const f of d.failures) out[f.domain] = `This section could not be computed: ${f.message}`;
  return out;
}

