/**
 * The report insight engine. PURE: takes a ReportData (lib/reports/collect.ts)
 * and returns ranked, plain-English findings + an executive summary + one
 * narrative paragraph per section. No database, no network, no LLM — every
 * sentence is a template filled with numbers from the data, so the same data
 * always produces the same report. Unit tested in test/reports-engine.test.ts.
 *
 * Three kinds of rule:
 *   1. CHANGE   — a metric moved significantly against the previous equal
 *                 period (lib/reports/stats.ts tests, with minimum samples).
 *   2. ANOMALY  — a metric is far outside the spread of the 4 periods before.
 *   3. FRICTION — known ways customers get stuck, each one a pattern first
 *                 found by hand (signup-friction analysis, 2026-10-06) and
 *                 turned into a rule so nobody has to find it by hand again.
 *
 * Ranking: estimated revenue at stake (cents) + customers affected × the
 * average first order, weighted by severity and confidence. "Early signal"
 * marks a finding whose sample is below the comfortable minimum — it is shown,
 * but ranked down and labelled.
 */
import { fmtCents } from "../insights/stats";
import { anomaly, countChange, latencyChange, moneyChange, ratioChange, sampleConfidence, MIN_COUNT, MIN_DEN } from "./stats";
import { rangeQuery } from "./range";
import { DOMAIN_LABELS, type Confidence, type Domain, type Finding, type Metric, type ReportData, type ReportSummary, type Severity } from "./types";

// ---------------------------------------------------------------------------
// Formatting
// ---------------------------------------------------------------------------

export function fmtN(n: number): string {
  return Math.round(n).toLocaleString("en-US");
}

export function fmtP(frac: number | null | undefined, digits = 0): string {
  if (frac == null || !Number.isFinite(frac)) return "—";
  return `${(frac * 100).toFixed(digits)}%`;
}

export function fmtDur(ms: number | null | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return "—";
  const s = ms / 1000;
  if (s < 90) return `${Math.round(s)} s`;
  const m = s / 60;
  if (m < 90) return `${m.toFixed(m < 10 ? 1 : 0)} min`;
  const h = m / 60;
  if (h < 48) return `${h.toFixed(h < 10 ? 1 : 0)} h`;
  return `${(h / 24).toFixed(1)} days`;
}

export function fmtValue(v: number | null | undefined, unit: Metric["unit"]): string {
  if (v == null || !Number.isFinite(v)) return "—";
  if (unit === "cents") return fmtCents(v);
  if (unit === "ratio") return fmtP(v, v < 0.1 && v > 0 ? 1 : 0);
  if (unit === "ms") return fmtDur(v);
  return fmtN(v);
}

function pctMove(rel: number): string {
  const p = Math.abs(rel * 100);
  return `${p >= 10 ? Math.round(p) : p.toFixed(1)}%`;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${fmtN(n)} ${n === 1 ? one : many}`;
}

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

type Ctx = {
  d: ReportData;
  /** One customer's worth in cents: average first order, else ARPU, else $10. */
  cust: number;
  prevLabel: string;
  compare: boolean;
  qs: string;
};

function drill(ctx: Ctx, target: string | undefined, label: string): Finding["drill"] {
  if (!target) return undefined;
  if (target.startsWith("/")) return { href: target, label };
  return { href: `/admin/reports/drill/${target}?${ctx.qs}`, label };
}

const SEV_W: Record<Severity, number> = { critical: 3, warning: 2, info: 0.6, positive: 0.8 };
const CONF_W: Record<Confidence, number> = { high: 1, medium: 0.8, early: 0.35 };

function mk(ctx: Ctx, f: Omit<Finding, "score" | "id"> & { id?: string }): Finding {
  const raw = Math.max(0, f.impactCents) + Math.max(0, f.impactCustomers) * ctx.cust;
  // A floor so a real but money-less finding (a broken email template) still outranks nothing.
  const score = Math.round((raw + 100) * SEV_W[f.severity] * CONF_W[f.confidence]);
  return { ...f, id: f.id ?? `${f.rule}:${f.domain}`, score };
}

function metric(d: ReportData, key: string): Metric | undefined {
  for (const s of d.sections) {
    const m = s.metrics.find((x) => x.key === key);
    if (m) return m;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// 1 + 2. Generic change / anomaly rules over every metric
// ---------------------------------------------------------------------------

/** Per-metric copy: why it matters + what to do, by direction. Generic fallback below. */
const COPY: Record<string, { bad: [string, string]; good?: [string, string]; valueOfUnit?: (ctx: Ctx) => number }> = {
  visitors: { bad: ["Fewer visitors means fewer signups a week or two later.", "Check the channel table below for which source fell; if it is ChatGPT or Google, look at the pages they used to land on."], good: ["More people are arriving.", "Make sure the landing pages that grew lead to something they can buy."], valueOfUnit: (c) => c.cust * 0.002 },
  sessions: { bad: ["Fewer sessions usually means fewer wizard opens.", "Compare against visitors: if both fell it is traffic, if only sessions fell people visit less often."] },
  pageviews: { bad: ["Lower engagement or less traffic.", "Check which landing pages lost visits."] },
  signups: { bad: ["Signups are the top of the paying funnel.", "Look at the channel and landing-page tables to see which source dried up."], good: ["More new accounts.", "Check the segment tables: growth from segments that never pay (free-intent pages, mobile) does not add revenue."], valueOfUnit: (c) => c.cust * 0.05 },
  verify_rate: { bad: ["Unverified accounts cannot receive billing and ready emails reliably.", "Check the verification email is arriving (email section) and the link works; consider re-sending to the drill-down list."], valueOfUnit: (c) => c.cust * 0.05 },
  activation_rate: { bad: ["An account that never deploys anything almost never pays.", "Look at the deploy-funnel section for where new accounts stop, and at the first screen after signup."], good: ["More new accounts are deploying something.", "Keep it — check which segment drove it."], valueOfUnit: (c) => c.cust * 0.2 },
