  payment_conversion: { bad: ["People who reach Payment have chosen everything — losing them is the most expensive leak.", "Check the payment-step table by country and the decline reasons; follow up the signed-in leavers in the drill-down."], good: ["More of the people who reach Payment are paying.", "Keep the current payment step."], valueOfUnit: (c) => c.cust },
  earned: { bad: ["Less revenue earned than the period before.", "See revenue by product to find which line fell, and check renewals vs new orders."], good: ["Revenue grew.", "See revenue by product for what drove it."] },
  cash_in: { bad: ["Less money actually arrived from cards / PayPal / crypto.", "Compare with earned revenue: if earned held up, customers are spending existing wallet balance."] },
