  new_order_revenue: { bad: ["Less money from new orders.", "Check the deploy funnel and payment step."] },
  renewal_revenue: { bad: ["Renewal revenue fell — existing customers are paying less.", "Check churn, cancellations and renewal declines below."] },
  new_paying: { bad: ["Fewer first-time paying customers.", "Look at the Payment step and payment failures."], good: ["More first-time paying customers.", "Welcome them: check their servers provisioned cleanly."], valueOfUnit: (c) => c.cust },
  refunds: { bad: ["More money was given back.", "Open the refunds drill-down and look for a shared cause (one game, one node, one failure)."] },
  mrr: { bad: ["Recurring revenue shrank over the period.", "See churn and cancellations below."], good: ["Recurring revenue grew.", "Check the growth came from several customers, not one."] },
  payments_failed: { bad: ["More card attempts were refused.", "Check the decline reasons and countries; offer a local method or PayPal where cards fail."] },
  payment_success_rate: { bad: ["A larger share of payment attempts fail.", "Check decline reasons by country and card brand."], valueOfUnit: (c) => c.cust },
  renewal_declines: { bad: ["Declined renewals turn into suspensions and churn if nobody acts.", "Check the dunning emails went out and contact the customers in the drill-down."], valueOfUnit: (c) => c.cust },
  provision_failures: { bad: ["A customer whose first server fails rarely buys again.", "Open the provisioning-by-game table and fix the top failing game first."], valueOfUnit: (c) => c.cust * 0.5 },
  provision_fail_rate: { bad: ["Provisioning is failing more often.", "See which game and node the failures concentrate on."], valueOfUnit: (c) => c.cust * 0.5 },
  time_to_ready_p50: { bad: ["Customers wait longer for their server.", "See time to ready by game; a large download or a slow node is the usual cause."] },
  churned_customers: { bad: ["Paying customers left.", "Open the churned list and look for a shared cause."], valueOfUnit: (c) => c.cust },
  cancellations: { bad: ["More customers asked to cancel.", "Read the cancelled customers' recent tickets and chats for the reason."], valueOfUnit: (c) => c.cust },
  tickets: { bad: ["More support load.", "See the topics table for what people are asking about; a spike in one topic usually has one cause."] },
  chat_handoff_rate: { bad: ["The help bot is handing more chats to a human.", "Read the bot's unanswered questions and add knowledge-base answers for the top ones."] },
  first_response_p50: { bad: ["Customers wait longer for a first reply.", "Check the oldest tickets waiting on staff."] },
  error_events: { bad: ["More errors were logged.", "See errors by context for the one that grew."] },
  money_path_errors: { bad: ["Errors on signup / deploy / payment code cost orders directly.", "Open the error log filtered to these contexts."], valueOfUnit: (c) => c.cust * 0.1 },
  http_5xx: { bad: ["Visitors saw server errors.", "See HTTP 5xx by route; a burst usually lines up with a deploy or a crash."] },
  email_fail_rate: { bad: ["More emails failed to send.", "Check the email-by-template table and the SMTP logs."] },
};

function metricRules(ctx: Ctx): Finding[] {
  if (!ctx.compare) return [];
  const out: Finding[] = [];
  for (const s of ctx.d.sections) {
    for (const m of s.metrics) {
      if (m.cur == null) continue;
      const copy = COPY[m.key];
      const f = changeFinding(ctx, m, copy) ?? anomalyFinding(ctx, m, copy);
      if (f) out.push(f);
    }
  }
  return out;
}

function changeFinding(ctx: Ctx, m: Metric, copy: (typeof COPY)[string] | undefined): Finding | null {
  if (m.prev == null || m.cur == null) return null;
  let sig;
  if (m.unit === "count") sig = countChange(m.cur, m.prev);
  else if (m.unit === "ratio") {
    if (m.num == null || m.den == null || m.prevNum == null || m.prevDen == null) return null;
    sig = ratioChange(m.num, m.den, m.prevNum, m.prevDen);
  } else if (m.unit === "cents") sig = moneyChange(m.cur, m.prev, m.n ?? 0, m.prevN ?? 0);
  else sig = latencyChange(m.cur, m.prev, m.n ?? 0, m.prevN ?? 0);
  if (!sig.significant) return null;
  const up = m.cur > m.prev;
  const good = up === m.higherIsBetter;
  const severity: Severity = good ? "positive" : Math.abs(sig.rel ?? 1) >= 0.5 && ["earned", "new_orders", "signups", "payment_conversion", "new_paying", "provision_fail_rate", "payment_success_rate"].includes(m.key) ? "critical" : "warning";
  const unitVal = copy?.valueOfUnit?.(ctx) ?? (m.unit === "cents" ? 1 : ctx.cust * 0.05);
  let impactCents = 0;
  let impactCustomers = 0;
  if (m.unit === "cents") impactCents = Math.abs(m.cur - m.prev);
  else if (m.unit === "ratio") impactCents = Math.abs(m.cur - m.prev) * (m.den ?? 0) * unitVal;
  else if (m.unit === "count") impactCents = Math.abs(m.cur - m.prev) * unitVal;
  else impactCustomers = 0.5;
  const verb = m.unit === "ratio" ? (up ? "rose" : "fell") : up ? "rose" : "fell";
  const moved = m.unit === "ratio" ? `${Math.abs(Math.round((m.cur - m.prev) * 100))} points` : sig.rel == null ? "from zero" : pctMove(sig.rel);
  const text =
    m.unit === "ratio"
      ? `${m.label} ${verb} to ${fmtValue(m.cur, m.unit)} (${fmtN(m.num ?? 0)} of ${fmtN(m.den ?? 0)}), ${moved} ${up ? "above" : "below"} ${ctx.prevLabel} (${fmtValue(m.prev, m.unit)}).`
      : `${m.label} ${verb} ${moved} to ${fmtValue(m.cur, m.unit)}, against ${fmtValue(m.prev, m.unit)} ${ctx.prevLabel}.`;
  const [why, action] = good ? copy?.good ?? ["A real improvement, not noise (it clears the minimum-sample and significance checks).", "Note what changed so it can be repeated."] : copy?.bad ?? ["A real deterioration, not noise (it clears the minimum-sample and significance checks).", "Open the section below for the breakdown."];
  return mk(ctx, {
    id: `change:${m.key}`,
    rule: "change",
    domain: m.domain,
    severity,
    confidence: sig.confidence,
    text,
    why,
    action,
    impactCents: Math.round(impactCents),
    impactCustomers,
    drill: drill(ctx, m.drill, "See the detail"),
  });
}

function anomalyFinding(ctx: Ctx, m: Metric, copy: (typeof COPY)[string] | undefined): Finding | null {
  if (m.cur == null || !m.baseline || m.unit === "ratio") return null;
  const minMean = m.unit === "cents" ? 2_000 : MIN_COUNT;
  const a = anomaly(m.cur, m.baseline, minMean);
  if (!a.anomalous || a.lo == null || a.hi == null) return null;
  const up = m.cur > a.hi;
  const good = up === m.higherIsBetter;
  const [why, action] = good ? copy?.good ?? ["Unusually good — far outside the normal range.", "Find out what happened so it can be repeated."] : copy?.bad ?? ["Unusually bad — far outside the normal range.", "Open the section below for the breakdown."];
  return mk(ctx, {
    id: `anomaly:${m.key}`,
    rule: "anomaly",
    domain: m.domain,
    severity: good ? "positive" : "warning",
    confidence: "medium",
    text: `${m.label} was ${fmtValue(m.cur, m.unit)} — ${up ? "above" : "below"} anything in the ${m.baseline.length} periods before (usual range ${fmtValue(a.lo, m.unit)}–${fmtValue(a.hi, m.unit)}).`,
    why,
    action,
    impactCents: m.unit === "cents" ? Math.abs(m.cur - (a.mean ?? m.cur)) : Math.abs(m.cur - (a.mean ?? m.cur)) * (copy?.valueOfUnit?.(ctx) ?? ctx.cust * 0.05),
    impactCustomers: 0,
    drill: drill(ctx, m.drill, "See the detail"),
  });
}

// ---------------------------------------------------------------------------
// 3. Friction rules
// ---------------------------------------------------------------------------

export type FrictionRule = { id: string; title: string; source: string; run: (ctx: Ctx) => Finding[] };

const productName = (p: string) => ({ vps: "VPS", game: "game-server", hosting: "web-hosting", email: "business-email" })[p] ?? p;

export const FRICTION_RULES: FrictionRule[] = [
  {
    id: "payment_left",
    title: "Reached Payment and left",
    source: "Signup-friction analysis 2026-10-06 §3: 34 reached Payment, 9 paid.",
    run(ctx) {
      const out: Finding[] = [];
      const funnels = ctx.d.sections.find((s) => s.domain === "funnel") ? funnelsOf(ctx.d) : [];
      for (const f of funnels) {
        if (f.paymentReached < 3 || f.paymentLeft < 3) continue;
        const rate = f.paymentLeft / f.paymentReached;
        if (rate < 0.4) continue;
        const conf = sampleConfidence(f.paymentReached);
        const prevRate = f.prevPaymentReached >= MIN_DEN / 2 ? f.prevPaymentLeft / f.prevPaymentReached : null;
        const cmp = prevRate != null && ctx.compare ? ` (${fmtP(prevRate)} ${ctx.prevLabel})` : "";
        out.push(
          mk(ctx, {
            id: `payment_left:${f.product}`,
            rule: "payment_left",
            domain: "funnel",
            severity: rate >= 0.6 && conf !== "early" ? "critical" : "warning",
            confidence: conf,
            text: `${fmtN(f.paymentLeft)} of ${fmtN(f.paymentReached)} sessions that reached Payment in the ${productName(f.product)} wizard left without ordering — ${fmtP(rate)}${cmp}.`,
            why: `These visitors had already picked a product, plan and region. At the average first order of ${fmtCents(ctx.cust)} that is up to ${fmtCents(f.paymentLeft * ctx.cust)} of orders not taken.`,
            action: `Check the payment step (total shown before card entry, local payment methods for the countries in the payment-by-country table, mobile layout). ${f.paymentLeftUserIds.length ? `${plural(f.paymentLeftUserIds.length, "signed-in leaver")} can be contacted from the drill-down.` : ""}`.trim(),
            impactCents: Math.round(f.paymentLeft * ctx.cust * 0.25),
            impactCustomers: 0,
            drill: drill(ctx, "payment_leavers", "Who left at Payment"),
          }),
        );
      }
      return out;
    },
  },
  {
    id: "payment_country",
    title: "Payment step fails in specific countries",
    source: "Friction §3: India 7 reached / 1 paid, Indonesia 5/0, Singapore 6/0, Bangladesh 3/0.",
    run(ctx) {
      const rows = ctx.d.friction.paymentByCountry;
      const reached = rows.reduce((a, b) => a + b.reached, 0);
      const done = rows.reduce((a, b) => a + b.completed, 0);
      if (reached < 10 || done === 0) return [];
      const overall = done / reached;
      const bad = rows.filter((c) => c.country !== "Unknown" && c.reached >= 3 && c.completed / c.reached <= overall / 3);
      if (bad.length < 2 && !(bad.length === 1 && bad[0].reached >= 6)) return [];
      const lost = bad.reduce((a, b) => a + (b.reached - b.completed), 0);
      const list = bad.slice(0, 5).map((c) => `${c.country} ${c.completed}/${c.reached}`).join(", ");
      return [
        mk(ctx, {
          id: "payment_country",
          rule: "payment_country",
          domain: "payments",
          severity: "warning",
          confidence: sampleConfidence(bad.reduce((a, b) => a + b.reached, 0)),
          text: `Payment-step sessions from ${list} (ordered/reached) almost never convert, against ${fmtP(overall)} overall.`,
          why: "When one group of countries fails together the usual causes are card acceptance, currency, or a missing local payment method — not interest.",
          action: "Check which payment methods those visitors see at the Payment step (local methods such as UPI, GrabPay, FPX, QRIS; PayPal), and the decline reasons in the payments section once checkout events are recorded.",
          impactCents: Math.round(lost * ctx.cust * 0.2),
          impactCustomers: 0,
          drill: drill(ctx, "payment_leavers", "Payment-step leavers"),
        }),
      ];
    },
  },
  {
    id: "card_declines_country",
    title: "Card declined by country / reason",
    source: "Friction §3 data gap: no record of declines. Reads the shared activity-event table.",
    run(ctx) {
      const out: Finding[] = [];
      for (const g of ctx.d.friction.declinesByCountry) {
        if (g.failed < 2 || g.label === "Unknown") continue;
        const rate = g.total ? g.failed / g.total : 1;
        if (rate < 0.4) continue;
        out.push(
          mk(ctx, {
            id: `declines:${g.key}`,
            rule: "card_declines_country",
            domain: "payments",
            severity: g.failed >= 5 ? "warning" : "info",
            confidence: sampleConfidence(g.total, 5),
            text: `${plural(g.failed, "card payment")} from ${g.label} failed${g.total > g.failed ? ` (${fmtP(rate)} of attempts)` : ""}.`,
            why: "Repeated declines from one country point at the card network or currency, and those customers usually give up rather than try another card.",
            action: "Offer that country's local payment method or PayPal at the Payment step; check the decline codes in the payments section.",
            impactCents: Math.round(g.failed * ctx.cust * 0.5),
            impactCustomers: 0,
            drill: drill(ctx, "declines", "Declined payments"),
          }),
        );
      }
      const reasons = ctx.d.friction.declineReasons;
      const totalFails = reasons.reduce((a, b) => a + b.value, 0);
      if (totalFails >= 5 && reasons[0]) {
        out.push(
          mk(ctx, {
            id: "declines:reason",
            rule: "card_declines_country",
            domain: "payments",
            severity: "info",
            confidence: sampleConfidence(totalFails, 5),
            text: `The most common decline reason was "${reasons[0].label}" (${fmtN(reasons[0].value)} of ${fmtN(totalFails)} failed attempts).`,
            why: reasons[0].label.includes("insufficient") ? "Insufficient funds usually means the price, not the payment method." : "The decline reason tells you whether to change the method, the flow, or nothing.",
            action: reasons[0].label.includes("insufficient") ? "Consider a smaller first-month option or a monthly term for these buyers." : "Look up the code in Stripe's decline-code list and fix the flow if it is ours (e.g. authentication).",
            impactCents: 0,
            impactCustomers: Math.min(reasons[0].value, 20) * 0.3,
          }),
        );
      }
      if (ctx.d.friction.authFailures >= 2)
        out.push(
          mk(ctx, {
            id: "declines:3ds",
            rule: "card_declines_country",
            domain: "payments",
            severity: "warning",
            confidence: sampleConfidence(ctx.d.friction.authFailures, 5),
            text: `${plural(ctx.d.friction.authFailures, "payment")} failed at the 3-D Secure / bank-authentication step.`,
            why: "Authentication failures are often the embedded bank pop-up failing to load, not the customer saying no.",
            action: "Test checkout with a 3-D Secure test card on mobile; make sure the hosted-checkout fallback link is offered.",
            impactCents: Math.round(ctx.d.friction.authFailures * ctx.cust * 0.5),
            impactCustomers: 0,
          }),
        );
      return out;
    },
  },
  {
    id: "renewal_declines",
    title: "Renewal charge declined",
    source: "billing.card_declined audit events.",
    run(ctx) {
      const r = ctx.d.friction.renewalDeclines;
      if (r.count < 1) return [];
      return [
        mk(ctx, {
          id: "renewal_declines",
          rule: "renewal_declines",
          domain: "payments",
          severity: r.users >= 3 ? "warning" : "info",
          confidence: sampleConfidence(r.count, 3),
          text: `${plural(r.count, "renewal charge")} for ${plural(r.users, "customer")} ${r.count === 1 ? "was" : "were"} declined${r.reasons[0] ? ` — mostly "${r.reasons[0].label}"` : ""}.`,
          why: "An existing customer whose renewal fails is revenue already earned once; losing them to a card problem is avoidable churn.",
          action: "Check each one is in the dunning flow and got the pay-link email; a personal note works better than the automated one for long-standing customers.",
          impactCents: Math.round(r.users * (ctx.d.arpuCents ?? ctx.cust)),
          impactCustomers: 0,
          drill: drill(ctx, "renewal_declines", "Customers with declined renewals"),
        }),
      ];
    },
  },
  {
    id: "verification_never_clicked",
    title: "Verification email never clicked",
    source: "Friction §8: 8 of 31 email signups never verified; verify link broken until 2026-10-05.",
    run(ctx) {
      const v = ctx.d.friction.verification;
      if (v.eligible < 5 || v.unverified < 3) return [];
      const rate = v.unverified / v.eligible;
      if (rate < 0.2) return [];
      const failNote = v.verifyEmailsFailed ? ` ${plural(v.verifyEmailsFailed, "verification email")} failed to send.` : "";
      return [
        mk(ctx, {
          id: "verification",
          rule: "verification_never_clicked",
          domain: "signups",
          severity: rate >= 0.35 ? "warning" : "info",
          confidence: sampleConfidence(v.eligible),
          text: `${fmtN(v.unverified)} of ${fmtN(v.eligible)} email-and-password signups (24h+ old) never verified their address — ${fmtP(rate)}.${failNote}`,
          why: "Unverified accounts miss order, ready and billing emails, and are excluded from win-back mail.",
          action: "Click a fresh verification link yourself to confirm it lands on the right host; offer a 'resend verification' prompt in the dashboard; check the email section for delivery failures.",
          impactCents: 0,
          impactCustomers: v.unverified * 0.05,
          drill: drill(ctx, "unverified", "Unverified signups"),
        }),
      ];
    },
  },
  {
    id: "no_activation",
    title: "Signed up but never deployed anything",
    source: "Friction summary: 9% of this week's signups have a server.",
    run(ctx) {
      const a = ctx.d.friction.activation;
      if (a.signups < 10) return [];
      const rate = a.activated / a.signups;
      if (rate >= 0.5) return [];
      const never = a.signups - a.activated;
      return [
        mk(ctx, {
          id: "no_activation",
          rule: "no_activation",
          domain: "signups",
          severity: rate < 0.25 ? "warning" : "info",
          confidence: sampleConfidence(a.signups),
          text: `${fmtN(never)} of ${fmtN(a.signups)} new accounts (${fmtP(1 - rate)}) have not deployed anything yet, not even a free server${a.medianHoursToDeploy != null ? `; those who did took a median ${fmtDur(a.medianHoursToDeploy * 3_600_000)}` : ""}.`,
          why: "An account that never deploys almost never pays; the first session after signup is where they are won or lost.",
          action: "Look at the first screen a new account sees, and at the segment tables: if the non-deployers cluster on one landing page or device, fix that path first.",
          impactCents: 0,
          impactCustomers: never * 0.03,
          drill: drill(ctx, "unactivated", "Accounts that never deployed"),
        }),
      ];
    },
  },
  {
    id: "dead_segment",
    title: "A signup segment that never converts (free-intent page, channel, device)",
    source: "Friction §1/§2: 83 /free-vps signups → 0 servers, 0 paid; 68 mobile signups → 0 paid.",
    run(ctx) {
      const segs = ctx.d.friction.segments;
      const total = segs.filter((s) => s.segment === "Channel").reduce((a, b) => a + b.signups, 0);
      const paid = segs.filter((s) => s.segment === "Channel").reduce((a, b) => a + b.paid, 0);
      if (total < 20 || paid === 0) return [];
      const overall = paid / total;
      const out: Finding[] = [];
      for (const s of segs) {
        if (s.key === "Unknown" || s.segment === "Sign-in method" || s.segment === "Country") continue;
        if (s.signups < 15 || s.signups < total * 0.1) continue;
        if (s.paid > 0 && s.paid / s.signups > overall / 4) continue;
        out.push(
          mk(ctx, {
            id: `dead_segment:${s.segment}:${s.key}`,
            rule: "dead_segment",
            domain: "signups",
            severity: s.signups >= total * 0.2 ? "warning" : "info",
            confidence: sampleConfidence(s.signups),
            text: `${fmtN(s.signups)} signups came from ${s.segment.toLowerCase()} "${s.key}" (${fmtP(s.signups / total)} of all signups); ${fmtN(s.activated)} deployed and ${fmtN(s.paid)} paid, against ${fmtP(overall)} paying overall.`,
            why:
              s.segment === "Landing page"
                ? "A page that brings signups who never buy usually promises something the product doesn't sell (e.g. 'free VPS'), and those signups also hide the real conversion rate."
                : s.segment === "Device"
                  ? "If one device signs up but never orders, the order flow is probably harder on that device — not the audience."
                  : "A large source that never pays inflates signups without adding revenue.",
            action:
              s.segment === "Landing page"
                ? `Rewrite the ${s.key} hero to say plainly what is free and show the cheapest paid option; consider reporting its signups separately.`
                : s.segment === "Device"
                  ? `Walk the deploy wizard on a ${s.key.toLowerCase()} screen (plan cards, region step, sticky continue button, keyboard over the button); compare the device step table in the funnel section.`
                  : "Decide whether this audience is worth chasing; if so, give it a path it can buy (a cheap first plan, a free-to-paid bridge).",
            impactCents: 0,
            impactCustomers: s.signups * overall * 0.5,
            drill: drill(ctx, "signups", "These signups"),
          }),
        );
      }
      return out.sort((a, b) => b.score - a.score).slice(0, 3);
    },
  },
  {
    id: "device_step_gap",
    title: "Mobile wizard drop between steps",
    source: "Friction §2: game wizard keeps 28% of mobile users from plan to region vs 52% on desktop.",
    run(ctx) {
      const out: Finding[] = [];
      const byProduct = new Map<string, typeof ctx.d.friction.deviceSteps>();
      for (const d of ctx.d.friction.deviceSteps) byProduct.set(d.product, [...(byProduct.get(d.product) ?? []), d]);
      for (const [product, devs] of byProduct) {
        const desk = devs.find((d) => d.device === "Desktop");
        if (!desk) continue;
        for (const dev of devs) {
          if (dev.device === "Desktop" || dev.device === "Unknown") continue;
          const first = dev.steps[0];
          if (!first || first.reached < 10) continue;
          // Worst step-to-step keep ratio vs desktop at the same transition.
          let worst: { from: number; to: number; m: number; d: number } | null = null;
          for (let i = 1; i < dev.steps.length; i++) {
            const a = dev.steps[i - 1];
            const b = dev.steps[i];
            const da = desk.steps.find((s) => s.index === a.index);
            const db = desk.steps.find((s) => s.index === b.index);
            if (!da || !db || a.reached < 8 || da.reached < 8) continue;
            const m = b.reached / a.reached;
            const d = db.reached / da.reached;
            if (d - m >= 0.2 && m < d * 0.6 && (!worst || d - m > worst.d - worst.m)) worst = { from: a.index, to: b.index, m, d };
          }
          if (!worst) continue;
          const steps = ctx.d.sections.find((s) => s.domain === "funnel")?.tables.find((t) => t.key === `funnel_${product}`)?.rows ?? [];
          const label = (i: number) => String(steps.find((r) => r[0] === i)?.[1] ?? `step ${i}`);
          out.push(
            mk(ctx, {
              id: `device_step_gap:${product}:${dev.device}`,
              rule: "device_step_gap",
              domain: "funnel",
              severity: "warning",
              confidence: sampleConfidence(first.reached),
