import { test } from "node:test";
import assert from "node:assert/strict";
import { parseReportRange, zonedMidnight, localYmd, addDaysYmd, rangeQuery, localDayKeys, isValidTimeZone } from "../lib/reports/range.ts";

const H = 3_600_000;
const D = 24 * H;

test("7d preset: 7 whole local days ending today, previous 7 before it, 4 baseline periods", () => {
  const now = new Date("2026-10-06T15:00:00Z");
  const r = parseReportRange({ preset: "7d" }, now);
  assert.equal(r.fromStr, "2026-09-30");
  assert.equal(r.toStr, "2026-10-06");
  assert.equal(r.calendarDays, 7);
  assert.equal(r.from.toISOString(), "2026-09-30T00:00:00.000Z");
  assert.equal(r.partial, true, "today is still running");
  assert.equal(r.to.getTime(), now.getTime(), "a running period ends at now, not midnight");
  assert.equal(r.prevFrom.toISOString(), "2026-09-23T00:00:00.000Z");
  // Partial fairness: previous period truncated to the same elapsed time.
  assert.equal(r.prevTo.getTime() - r.prevFrom.getTime(), r.to.getTime() - r.from.getTime());
  assert.equal(r.baseline.length, 4);
  assert.equal(r.baseline[0].from.toISOString(), "2026-09-16T00:00:00.000Z");
  assert.equal(r.baseline[3].from.toISOString(), "2026-08-26T00:00:00.000Z");
});

test("today preset compares with the same hours yesterday", () => {
  const now = new Date("2026-10-06T10:30:00Z");
  const r = parseReportRange({ preset: "today" }, now);
  assert.equal(r.from.toISOString(), "2026-10-06T00:00:00.000Z");
  assert.equal(r.prevFrom.toISOString(), "2026-10-05T00:00:00.000Z");
  assert.equal(r.prevTo.toISOString(), "2026-10-05T10:30:00.000Z");
  assert.equal(r.prevLabel, "the same hours yesterday");
  assert.ok(r.days > 0.43 && r.days < 0.44);
});

test("a closed custom range is not truncated", () => {
  const r = parseReportRange({ from: "2026-09-01", to: "2026-09-10" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(r.partial, false);
  assert.equal(r.calendarDays, 10);
  assert.equal(r.to.toISOString(), "2026-09-11T00:00:00.000Z");
  assert.equal(r.prevFrom.toISOString(), "2026-08-22T00:00:00.000Z");
  assert.equal(r.prevTo.toISOString(), "2026-09-01T00:00:00.000Z");
  assert.equal(r.preset, null);
});

test("custom range clamps a future end date and swaps nothing silently", () => {
  const r = parseReportRange({ from: "2026-10-01", to: "2027-01-01" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(r.toStr, "2026-10-06");
  const bad = parseReportRange({ from: "2026-10-05", to: "2026-10-01" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(bad.preset, "7d", "an inverted range falls back to the default preset");
  const junk = parseReportRange({ from: "not-a-date" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(junk.preset, "7d");
});

test("month to date starts on the 1st in the chosen zone", () => {
  const r = parseReportRange({ preset: "mtd", tz: "Asia/Singapore" }, new Date("2026-09-30T20:00:00Z")); // already Oct 1 in SGT
  assert.equal(r.fromStr, "2026-10-01");
  assert.equal(r.from.toISOString(), "2026-09-30T16:00:00.000Z", "SGT midnight = 16:00 UTC the day before");
});

test("time-zone boundaries are DST-correct", () => {
  // New York: DST ends 2026-11-01 (UTC-4 → UTC-5).
  assert.equal(zonedMidnight(2026, 10, 31, "America/New_York").toISOString(), "2026-10-31T04:00:00.000Z");
  assert.equal(zonedMidnight(2026, 11, 2, "America/New_York").toISOString(), "2026-11-02T05:00:00.000Z");
  const r = parseReportRange({ from: "2026-11-01", to: "2026-11-01", tz: "America/New_York" }, new Date("2026-12-01T00:00:00Z"));
  assert.equal(r.to.getTime() - r.from.getTime(), 25 * H, "the fall-back day has 25 hours");
  assert.equal(localYmd(new Date("2026-10-06T03:00:00Z"), "America/New_York"), "2026-10-05");
  assert.equal(localYmd(new Date("2026-10-06T03:00:00Z"), "UTC"), "2026-10-06");
});

test("invalid time zone falls back to UTC; helpers", () => {
  assert.equal(isValidTimeZone("Mars/Olympus"), false);
  assert.equal(parseReportRange({ tz: "Mars/Olympus" }, new Date("2026-10-06T12:00:00Z")).tz, "UTC");
  assert.equal(addDaysYmd("2026-02-28", 1), "2026-03-01");
  assert.equal(addDaysYmd("2026-03-01", -1), "2026-02-28");
  const r = parseReportRange({ preset: "7d", tz: "Asia/Singapore", compare: "none" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(rangeQuery(r), "preset=7d&tz=Asia%2FSingapore&compare=none");
  assert.equal(localDayKeys(r).length, 7);
  assert.equal(r.compare, "none");
});

test("a 400-day cap stops a typo from scanning a decade", () => {
  const r = parseReportRange({ from: "2010-01-01", to: "2026-10-01" }, new Date("2026-10-06T12:00:00Z"));
  assert.equal(r.calendarDays, 400);
  assert.ok(r.to.getTime() - r.from.getTime() <= 401 * D);
});

