import { test } from "node:test";
import assert from "node:assert/strict";
import { countChange, ratioChange, moneyChange, anomaly, sampleConfidence } from "../lib/reports/stats.ts";
import { analyze, FRICTION_RULES, fmtValue } from "../lib/reports/engine.ts";
import { channelOf, maskEmail, isInternalEmail, orderKind, topicOf, usageCategory, cleanLanding, normalizeMessage, gameOfDescription } from "../lib/reports/classify.ts";
import { routeGroup, isMoneyPath } from "../lib/reports/routes.ts";
import type { FrictionInputs, Metric, ReportData } from "../lib/reports/types.ts";

// ---------------------------------------------------------------------------
// Fixture
// ---------------------------------------------------------------------------

function friction(over: Partial<FrictionInputs> = {}): FrictionInputs {
  return {
    verification: { eligible: 0, unverified: 0, prevEligible: 0, prevUnverified: 0, verifyEmailsSent: 0, verifyEmailsFailed: 0, unverifiedUserIds: [] },
    activation: { signups: 0, activated: 0, prevSignups: 0, prevActivated: 0, medianHoursToDeploy: null },
    declinesByCountry: [],
    declinesByBrand: [],
    declineReasons: [],
    authFailures: 0,
    renewalDeclines: { count: 0, users: 0, reasons: [], userIds: [] },
    soldOut: { sessionsShown: 0, sessionsShownCompleted: 0, picks: [], instrumented: false },
    provisionByGame: [],
    provisionByNode: [],
    deployPathErrors: { events: 0, prevEvents: 0, contexts: [], instrumented: true },
    orderErrors: [],
    devices: [],
    emailFailures: [],
    newErrorTypes: [],
    unansweredTickets: 0,
    ticketFirstResponseP50Ms: null,
    ticketFirstResponsePrevP50Ms: null,
    chatHandoffs: { conversations: 0, escalated: 0, prevConversations: 0, prevEscalated: 0 },
    botUnanswered: { count: 0, top: [] },
    promoRenewals: { due: 0, renewed: 0 },
    winback: [],
    nodeAlerts: { critical: 0, warning: 0, open: 0, top: [] },
    capacity: [],
    capacityRefusals: [],
    segments: [],
    paymentByCountry: [],
    deviceSteps: [],
    funnels: [],
    internalUnflagged: 0,
    freeMc: { created: 0, woken: 0, multiplayer: 0, upsellShown: 0, upsellClicked: 0, upgraded: 0 },
    staleProvisioning: 0,
    ...over,
  };
}

function report(metrics: Metric[] = [], f: Partial<FrictionInputs> = {}, compare: "previous" | "none" = "previous"): ReportData {
  const domains = [...new Set(metrics.map((m) => m.domain))];
  return {
    generatedAt: "2026-10-06T00:00:00Z",
    range: { from: "", to: "", prevFrom: "", prevTo: "", fromStr: "2026-09-30", toStr: "2026-10-06", label: "Last 7 days", prevLabel: "the previous 7 days", days: 7, partial: false, tz: "UTC", compare, preset: "7d" },
    avgOrderCents: 1200,
    arpuCents: 1500,
    sections: domains.map((d) => ({ domain: d, metrics: metrics.filter((m) => m.domain === d), tables: [], ranked: [] })),
    friction: friction(f),
    failures: [],
  };
}

const count = (key: string, cur: number, prev: number, extra: Partial<Metric> = {}): Metric => ({ key, domain: "signups", label: key, unit: "count", cur, prev, higherIsBetter: true, ...extra });

// ---------------------------------------------------------------------------
// Significance + minimum samples
// ---------------------------------------------------------------------------

test("count changes: tiny samples are never news", () => {
  assert.equal(countChange(2, 1).significant, false, "2 vs 1 is not 'up 100%'");
  assert.equal(countChange(9, 3).significant, false, "below the 10-event minimum");
  assert.equal(countChange(12, 11).significant, false, "moved < 25%");
  assert.equal(countChange(150, 96).significant, true, "the real 56% signup jump");
  assert.equal(countChange(150, 96).confidence, "high");
  assert.equal(countChange(30, 0).significant, true, "from zero, clears the minimum on its own");
  assert.equal(countChange(5, 0).significant, false);
});

test("ratio changes need 20 trials per side and 5 points", () => {
  assert.equal(ratioChange(9, 34, 9, 42).significant, false, "26% vs 21% on 34/42 trials: noise");
  assert.equal(ratioChange(5, 10, 1, 10).significant, false, "below the minimum denominator");
  assert.equal(ratioChange(80, 100, 40, 100).significant, true);
  assert.equal(ratioChange(51, 100, 50, 100).significant, false, "1 point is not a move");
});

test("money needs transactions on both sides, and real dollars", () => {
  assert.equal(moneyChange(5000, 1000, 3, 2).significant, false, "too few transactions");
  assert.equal(moneyChange(10_500, 10_000, 30, 30).significant, false, "5% is not news");
  assert.equal(moneyChange(30_000, 10_000, 30, 25).significant, true);
  assert.equal(moneyChange(1200, 600, 6, 6).significant, false, "$6 of movement is below the $20 floor");
});

test("anomaly needs 3 baseline periods with spread and must leave the observed range", () => {
  assert.equal(anomaly(100, [10, 11]).anomalous, false, "two periods is not a baseline");
  assert.equal(anomaly(100, [10, 10, 10]).anomalous, false, "zero spread → no z-score");
  assert.equal(anomaly(100, [10, 12, 9, 11]).anomalous, true);
  assert.equal(anomaly(3, [1, 2, 1, 2]).anomalous, false, "below the minimum mean");
  assert.equal(sampleConfidence(4), "early");
  assert.equal(sampleConfidence(12), "medium");
  assert.equal(sampleConfidence(40), "high");
});

// ---------------------------------------------------------------------------
// Period comparison
// ---------------------------------------------------------------------------

test("a significant drop becomes a ranked finding with number, comparison, why and action", () => {
  const s = analyze(report([count("signups", 60, 150)]));
  const f = s.all.find((x) => x.id === "change:signups");
  assert.ok(f, "finding produced");
  assert.equal(f!.severity, "critical", "a ≥50% drop in signups is critical");
  assert.match(f!.text, /fell 60% to 60, against 150 the previous 7 days/);
  assert.ok(f!.why.length > 10 && f!.action.length > 10);
  assert.ok(s.findings.includes(f!));
});

test("compare toggle off: no change findings, friction rules still run", () => {
  const s = analyze(report([count("signups", 60, 150)], { staleProvisioning: 2 }, "none"));
  assert.equal(s.all.some((x) => x.rule === "change"), false);
  assert.ok(s.all.some((x) => x.rule === "stale_provisioning"));
  assert.doesNotMatch(s.headline, /up|down/);
});

test("noise produces no findings and the summary says nothing alarming", () => {
  const s = analyze(report([count("signups", 11, 10), count("new_orders", 2, 1, { domain: "revenue" })]));
  assert.equal(s.all.length, 0);
  assert.equal(s.findings.length, 0);
});

test("anomaly vs baseline when the previous period alone is not decisive", () => {
  const s = analyze(report([count("tickets", 40, 33, { domain: "support", higherIsBetter: false, baseline: [8, 10, 9, 11] })]));
  const f = s.all.find((x) => x.id === "anomaly:tickets");
  assert.ok(f);
  assert.match(f!.text, /above anything in the 4 periods before \(usual range 8–11\)/);
});

// ---------------------------------------------------------------------------
// Friction rules (each one a hand-found pattern from the 2026-10-06 analysis)
// ---------------------------------------------------------------------------

test("reached Payment and left", () => {
  const funnel = { product: "game", sessions: 60, completed: 9, prevSessions: 50, prevCompleted: 9, steps: [], paymentReached: 34, paymentLeft: 25, prevPaymentReached: 42, prevPaymentLeft: 33, paymentLeftUserIds: ["u1", "u2"], topErrors: [] };
  const s = analyze(report([], { funnels: [funnel] }));
  const f = s.all.find((x) => x.rule === "payment_left")!;
  assert.match(f.text, /25 of 34 sessions that reached Payment in the game-server wizard left/);
  assert.equal(f.confidence, "high");
  assert.ok(f.drill?.href.startsWith("/admin/reports/drill/payment_leavers?preset=7d"));
  // Tiny sample → no finding.
  const tiny = analyze(report([], { funnels: [{ ...funnel, paymentReached: 2, paymentLeft: 2 }] }));
  assert.equal(tiny.all.some((x) => x.rule === "payment_left"), false);
});

test("payment step dead in a group of countries", () => {
  const s = analyze(report([], { paymentByCountry: [
    { country: "IN", reached: 7, completed: 1 * 0 },
    { country: "ID", reached: 5, completed: 0 },
    { country: "SG", reached: 6, completed: 0 },
    { country: "PH", reached: 7, completed: 3 },
    { country: "VN", reached: 5, completed: 3 },
    { country: "US", reached: 10, completed: 5 },
  ] }));
  const f = s.all.find((x) => x.rule === "payment_country")!;
  assert.ok(f);
  assert.match(f.text, /IN 0\/7, SG 0\/6, ID 0\/5/);
});

test("card declined by country, decline reason, 3DS", () => {
  const s = analyze(report([], {
    declinesByCountry: [{ key: "IN", label: "IN", total: 8, failed: 6 }, { key: "US", label: "US", total: 40, failed: 2 }],
    declineReasons: [{ label: "insufficient_funds", value: 5 }, { label: "do_not_honor", value: 3 }],
    authFailures: 3,
  }));
  assert.ok(s.all.find((x) => x.id === "declines:IN"));
  assert.equal(s.all.some((x) => x.id === "declines:US"), false, "5% failure is normal");
  assert.match(s.all.find((x) => x.id === "declines:reason")!.text, /insufficient_funds/);
  assert.ok(s.all.find((x) => x.id === "declines:3ds"));
});

test("verification never clicked", () => {
  const s = analyze(report([], { verification: { eligible: 31, unverified: 8, prevEligible: 23, prevUnverified: 7, verifyEmailsSent: 36, verifyEmailsFailed: 0, unverifiedUserIds: [] } }));
  assert.match(s.all.find((x) => x.rule === "verification_never_clicked")!.text, /8 of 31 .* 26%/);
  const fine = analyze(report([], { verification: { eligible: 31, unverified: 2, prevEligible: 0, prevUnverified: 0, verifyEmailsSent: 0, verifyEmailsFailed: 0, unverifiedUserIds: [] } }));
  assert.equal(fine.all.some((x) => x.rule === "verification_never_clicked"), false);
});

test("free-intent landing page and mobile segments that never pay", () => {
  const segs = [
    { segment: "Channel", key: "ChatGPT", signups: 91, activated: 7, paid: 6 },
    { segment: "Channel", key: "Google (organic)", signups: 59, activated: 7, paid: 4 },
    { segment: "Landing page", key: "/free-vps", signups: 58, activated: 0, paid: 0 },
    { segment: "Landing page", key: "/minecraft-server-hosting", signups: 30, activated: 9, paid: 6 },
    { segment: "Device", key: "Mobile", signups: 68, activated: 1, paid: 0 },
    { segment: "Device", key: "Desktop", signups: 82, activated: 13, paid: 10 },
  ];
  const s = analyze(report([], { segments: segs }));
  const ids = s.all.filter((x) => x.rule === "dead_segment").map((x) => x.id);
  assert.ok(ids.includes("dead_segment:Landing page:/free-vps"));
  assert.ok(ids.includes("dead_segment:Device:Mobile"));
  assert.equal(ids.includes("dead_segment:Device:Desktop"), false);
});

test("mobile wizard step gap vs desktop", () => {
  const s = analyze(report([], { deviceSteps: [
    { product: "game", device: "Desktop", steps: [{ index: 1, reached: 49 }, { index: 2, reached: 48 }, { index: 3, reached: 25 }] },
    { product: "game", device: "Mobile", steps: [{ index: 1, reached: 25 }, { index: 2, reached: 18 }, { index: 3, reached: 5 }] },
  ] }));
  const f = s.all.find((x) => x.rule === "device_step_gap")!;
  assert.ok(f);
  assert.match(f.text, /only 28% .* against 52% on desktop/);
});

test("provision failed for game X (and not for a game with one blip)", () => {
  const s = analyze(report([], { provisionByGame: [
    { key: "valheim", label: "valheim", total: 6, failed: 4, examples: ["game port #/udp never opened"], userIds: ["a", "b"] },
    { key: "minecraft", label: "minecraft", total: 40, failed: 1 },
  ] }));
  const f = s.all.find((x) => x.id === "provision:game:valheim")!;
  assert.equal(f.severity, "critical");
  assert.match(f.text, /failed 4 times for valheim — 67% of attempts, affecting 2 customers/);
  assert.equal(s.all.some((x) => x.id === "provision:game:minecraft"), false);
});

test("sold out / capacity refusals, money-path errors, late validation, email failures, internal accounts", () => {
