/**
 * Drill-downs behind report findings: the actual customers / orders a number
 * is made of. SELECT-only. Every row carries a userId so the page can link to
 * that customer's journey (/admin/reports/journey/[userId]).
 */
import { db } from "@/lib/db";
import { churnInsights, mrrNow } from "@/lib/insights/revenue";
import { activityRows, field, FAILED_KIND, PAYMENT_KINDS } from "./activity-source";
import { realUser, revenueDebit } from "./sql";
import type { ReportRange } from "./range";

export type DrillRow = { userId: string | null; email: string | null; when: Date | null; cols: (string | number | null)[] };
export type Drill = { kind: string; title: string; sub: string; head: string[]; rows: DrillRow[]; note?: string };

export const DRILL_KINDS: Record<string, { title: string; sub: string }> = {
  signups: { title: "New accounts", sub: "Real customer accounts created in the period." },
  unverified: { title: "Email signups that never verified", sub: "Email-and-password accounts more than 24 hours old with no verified address." },
  unactivated: { title: "New accounts that never deployed", sub: "No server, free VPS or free Minecraft server yet." },
  payment_leavers: { title: "Reached Payment and left", sub: "Signed-in customers whose wizard session reached the Payment step without a paid order in the period." },
  orders: { title: "Orders & charges", sub: "Every revenue charge (new orders, renewals, add-ons) in the period." },
  refunds: { title: "Refunds & write-offs", sub: "Money given back in the period." },
  declines: { title: "Declined payments", sub: "Failed checkout payments (activity-event capture) and declined renewals." },
  renewal_declines: { title: "Declined renewals", sub: "Renewal charges the billing sweep could not collect." },
  provision_failures: { title: "Failed provisions", sub: "Terminal provisioning failures for real customers." },
  churned: { title: "Paying customers lost", sub: "Paying at the start of the period, no live paid server at the end." },
  tickets: { title: "Support tickets", sub: "Tickets opened in the period." },
};

const dollars = (c: number | null | undefined) => (c == null ? null : `$${(c / 100).toFixed(2)}`);

export async function drill(kind: string, r: ReportRange): Promise<Drill | null> {
  const meta = DRILL_KINDS[kind];
  if (!meta) return null;
  const base = { kind, ...meta };
  const a = r.from;
  const b = r.to;
  switch (kind) {
    case "signups":
    case "unverified":
    case "unactivated": {
      const rows = await db.$queryRaw<{ id: string; email: string; createdAt: Date; google: boolean; verified: boolean; deployed: boolean; paid: boolean }[]>`
        SELECT u.id, u.email, u."createdAt", (u."googleId" IS NOT NULL) AS google, (u."emailVerifiedAt" IS NOT NULL) AS verified,
          (EXISTS (SELECT 1 FROM "Server" x WHERE x."userId" = u.id) OR EXISTS (SELECT 1 FROM "ServerArchive" x WHERE x."userId" = u.id) OR EXISTS (SELECT 1 FROM "FreeMinecraftServer" f WHERE f."userId" = u.id)) AS deployed,
          EXISTS (SELECT 1 FROM "WalletTransaction" w WHERE w."userId" = u.id AND ${revenueDebit("w")}) AS paid
        FROM "User" u WHERE ${realUser("u")} AND u."createdAt" >= ${a} AND u."createdAt" < ${b}
        ORDER BY u."createdAt" DESC LIMIT 2000`;
      const cutoff = Math.min(b.getTime(), Date.now()) - 86_400_000;
      const filtered = rows.filter((x) => (kind === "unverified" ? !x.google && !x.verified && x.createdAt.getTime() < cutoff : kind === "unactivated" ? !x.deployed : true));
      return {
        ...base,
        head: ["Signed up", "Method", "Verified", "Deployed", "Paid"],
        rows: filtered.map((x) => ({ userId: x.id, email: x.email, when: x.createdAt, cols: [x.google ? "Google" : "Email", x.verified ? "yes" : "no", x.deployed ? "yes" : "no", x.paid ? "yes" : "no"] })),
      };
    }
    case "payment_leavers": {
      const rows = await db.$queryRaw<{ userId: string; email: string; product: string; at: Date; ordered: boolean }[]>`
        SELECT e."userId", u.email, e.product, max(e."createdAt") AS at,
          (EXISTS (SELECT 1 FROM "Server" x WHERE x."userId" = e."userId" AND x."isFree" = false AND x."createdAt" >= ${a})
            OR EXISTS (SELECT 1 FROM "ServerArchive" x WHERE x."userId" = e."userId" AND x."totalSpentCents" > 0 AND x."provisionedAt" >= ${a})
            OR EXISTS (SELECT 1 FROM "DeployFunnelEvent" c WHERE c."userId" = e."userId" AND c.type = 'complete' AND c."createdAt" >= ${a})) AS ordered
        FROM "DeployFunnelEvent" e JOIN "User" u ON u.id = e."userId"
        WHERE ${realUser("u")} AND e.type = 'step' AND e.step ILIKE 'payment' AND e."createdAt" >= ${a} AND e."createdAt" < ${b}
        GROUP BY 1, 2, 3 ORDER BY 4 DESC LIMIT 2000`;
      return { ...base, head: ["Last reached Payment", "Wizard"], rows: rows.filter((x) => !x.ordered).map((x) => ({ userId: x.userId, email: x.email, when: x.at, cols: [x.product] })) };
    }
    case "orders":
    case "refunds": {
      const rows =
        kind === "orders"
          ? await db.$queryRaw<{ userId: string; email: string; createdAt: Date; description: string; cents: number }[]>`
              SELECT w."userId", u.email, w."createdAt", w.description, -w."amountCents" AS cents FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
              WHERE ${revenueDebit("w")} AND ${realUser("u")} AND w."createdAt" >= ${a} AND w."createdAt" < ${b} ORDER BY w."createdAt" DESC LIMIT 2000`
          : await db.$queryRaw<{ userId: string; email: string; createdAt: Date; description: string; cents: number }[]>`
              SELECT w."userId", u.email, w."createdAt", w.description, -w."amountCents" AS cents FROM "WalletTransaction" w JOIN "User" u ON u.id = w."userId"
              WHERE w."amountCents" < 0 AND (w.description LIKE 'Refund%' OR w.description LIKE 'Write-off%') AND w."createdAt" >= ${a} AND w."createdAt" < ${b} ORDER BY w."createdAt" DESC LIMIT 2000`;
      return { ...base, head: ["When", "Description", "Amount"], rows: rows.map((x) => ({ userId: x.userId, email: x.email, when: x.createdAt, cols: [x.description.slice(0, 120), dollars(x.cents)] })) };
    }
    case "declines":
    case "renewal_declines": {
      const renew = await db.$queryRaw<{ userId: string | null; email: string | null; createdAt: Date; detail: string | null }[]>`
        SELECT a."userId", u.email, a."createdAt", a.detail FROM "AuditLog" a LEFT JOIN "User" u ON u.id = a."userId"
        WHERE a.action = 'billing.card_declined' AND a."createdAt" >= ${a} AND a."createdAt" < ${b} ORDER BY a."createdAt" DESC LIMIT 1000`;
      const out: DrillRow[] = renew.map((x) => ({ userId: x.userId, email: x.email, when: x.createdAt, cols: ["renewal", (x.detail ?? "").split(":").slice(1).join(":").trim().slice(0, 140) || x.detail, null] }));
      let note: string | undefined;
      if (kind === "declines") {
        const act = await activityRows({ from: a, to: b }, PAYMENT_KINDS);
        if (!act) note = "Checkout declines appear here once the activity-event capture (lib/activity-events.ts) is deployed; until then only renewal declines are listed.";
        else {
          const fails = act.filter((x) => FAILED_KIND.test(x.kind));
          const ids = [...new Set(fails.map((f) => f.userId).filter((u): u is string => !!u))];
          const emails = ids.length ? new Map((await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } })).map((u) => [u.id, u.email])) : new Map<string, string>();
          for (const f of fails)
            out.push({
              userId: f.userId,
              email: f.userId ? emails.get(f.userId) ?? null : null,
              when: f.at,
              cols: ["checkout", [field(f.data, ["declineCode", "decline_code", "failureCode", "code"]), field(f.data, ["cardBrand", "brand"]), field(f.data, ["cardCountry", "country"], true)].filter(Boolean).join(" · "), null],
            });
          out.sort((x, y) => (y.when?.getTime() ?? 0) - (x.when?.getTime() ?? 0));
        }
      }
      return { ...base, head: ["When", "Kind", "Reason", ""], rows: out, note };
    }
    case "provision_failures": {
      const rows = await db.$queryRaw<{ userId: string; email: string; createdAt: Date; msg: string | null; detail: string | null }[]>`
        SELECT e."userId", u.email, e."createdAt", left(e."errorMessage", 200) AS msg, e.detail FROM "DeployFunnelEvent" e JOIN "User" u ON u.id = e."userId"
        WHERE ${realUser("u")} AND e."errorCode" = 'PROVISION_FAILED' AND e."createdAt" >= ${a} AND e."createdAt" < ${b} ORDER BY e."createdAt" DESC LIMIT 1000`;
      return {
        ...base,
        head: ["When", "Game", "Error"],
        rows: rows.map((x) => {
          let game: string | null = null;
          try {
            game = x.detail ? (JSON.parse(x.detail).game as string) ?? null : null;
          } catch {
            game = null;
          }
          return { userId: x.userId, email: x.email, when: x.createdAt, cols: [game ?? "—", x.msg] };
        }),
      };
    }
    case "churned": {
      const m = await mrrNow();
      const c = await churnInsights(r, m);
      return { ...base, head: ["Last paid server ended"], rows: c.churnedList.map((x) => ({ userId: x.userId, email: x.email, when: x.since, cols: [] })) };
    }
    case "tickets": {
      const rows = await db.$queryRaw<{ userId: string; email: string; createdAt: Date; subject: string; status: string; replied: boolean }[]>`
        SELECT t."userId", u.email, t."createdAt", t.subject, t.status::text AS status,
          EXISTS (SELECT 1 FROM "TicketMessage" m WHERE m."ticketId" = t.id AND m."isStaff") AS replied
        FROM "Ticket" t JOIN "User" u ON u.id = t."userId" WHERE ${realUser("u")} AND t."createdAt" >= ${a} AND t."createdAt" < ${b} ORDER BY t."createdAt" DESC LIMIT 1000`;
      return { ...base, head: ["Opened", "Subject", "Status", "Staff replied"], rows: rows.map((x) => ({ userId: x.userId, email: x.email, when: x.createdAt, cols: [x.subject.slice(0, 120), x.status, x.replied ? "yes" : "no"] })) };
    }
  }
  return null;
}

