    db.serverArchive.findMany({ where: { userId }, select: { hostname: true, serviceName: true, provisionedAt: true, deletedAt: true, reason: true, totalSpentCents: true } }),
    db.$queryRaw<{ type: string; status: string; createdAt: Date; finishedAt: Date | null; error: string | null; hostname: string }[]>`
      SELECT j.type::text, j.status::text, j."createdAt", j."finishedAt", left(j.error, 200) AS error, x.hostname FROM "Job" j JOIN "Server" x ON x.id = j."serverId"
      WHERE x."userId" = ${userId} AND j.type IN ('PROVISION', 'REINSTALL', 'DELETE') ORDER BY j."createdAt" ASC LIMIT 500`,
    db.auditLog.findMany({ where: { userId }, orderBy: { createdAt: "asc" }, take: 2000, select: { action: true, createdAt: true, detail: true } }),
    db.ticket.findMany({ where: { userId }, select: { id: true, subject: true, status: true, createdAt: true, messages: { select: { isStaff: true, createdAt: true }, orderBy: { createdAt: "asc" } } } }),
    db.chatConversation.findMany({ where: { userId }, select: { createdAt: true, botEscalatedAt: true, status: true, _count: { select: { messages: true } } } }),
    db.emailLog.findMany({ where: { userId }, orderBy: { createdAt: "asc" }, take: 1000, select: { template: true, subject: true, status: true, createdAt: true, openedAt: true, clickedAt: true } }),
    db.couponRedemption.findMany({ where: { userId }, select: { createdAt: true, amountCents: true, state: true, coupon: { select: { code: true } } } }),
    activityRows({ from: since, to: new Date(Date.now() + 60_000) }, ".", { userId, limit: 3000 }),
  ]);

  const ev: JourneyEvent[] = [];
  // Visits → one event per session (landing page + how many pages).
  const sessions = new Map<string, { first: (typeof visits)[number]; n: number; portal: number }>();
  for (const v of visits) {
    const k = v.sessionId ?? `${v.createdAt.getTime()}`;
    const s = sessions.get(k);
    if (s) {
      s.n++;
      if (v.kind === "portal") s.portal++;
    } else sessions.set(k, { first: v, n: 1, portal: v.kind === "portal" ? 1 : 0 });
  }
  const host = (r: string | null) => (r ? (/^[a-z]+:\/\/([^/?#:]+)/i.exec(r)?.[1] ?? null) : null);
  let firstTouch: Journey["firstTouch"] = null;
  for (const { first: v, n, portal } of sessions.values()) {
    const channel = channelOf({ host: host(v.referrer)?.replace(/^www\./, "") ?? null, utmSource: v.utmSource, utmMedium: v.utmMedium, gclid: !!v.gclid }, ["nxeon.cloud"]);
    if (!firstTouch) firstTouch = { path: cleanLanding(v.path), channel, device: v.deviceType, country: v.country, at: v.createdAt };
    ev.push({ at: v.createdAt, kind: "visit", title: portal ? `Dashboard session — ${n} page${n === 1 ? "" : "s"}` : `Visit from ${channel} — landed on ${cleanLanding(v.path)}`, detail: [v.deviceType, v.country, n > 1 ? `${n} pages` : null].filter(Boolean).join(" · ") });
  }
  ev.push({ at: u.createdAt, kind: "signup", title: `Signed up with ${u.googleId ? "Google" : "email & password"}`, detail: u.heardAboutUs ? `Heard about us: ${u.heardAboutUs}` : undefined, tone: "good" });
  if (u.emailVerifiedAt && !u.googleId) ev.push({ at: u.emailVerifiedAt, kind: "signup", title: "Verified email address", tone: "good" });

  // Wizard: collapse consecutive steps of one product into one line per step change.
  let lastKey = "";
  for (const f of funnel) {
    if (f.type === "step") {
      const k = `${f.product}|${f.step}`;
      if (k === lastKey) continue;
      lastKey = k;
      ev.push({ at: f.createdAt, kind: "wizard", title: `${f.product.toUpperCase()} wizard — reached ${f.step}` });
    } else if (f.type === "select") {
      let v = "";
      try {
        v = String(JSON.parse(f.detail ?? "{}").value ?? "");
      } catch {
        v = "";
      }
      ev.push({ at: f.createdAt, kind: "wizard", title: `Picked ${f.step}: ${v.length > 30 ? `${v.slice(0, 8)}…` : v}` });
    } else if (f.type === "error") ev.push({ at: f.createdAt, kind: f.errorCode === "PROVISION_FAILED" ? "provision" : "wizard", title: `${f.errorCode === "PROVISION_FAILED" ? "Provisioning failed" : `Error at ${f.step}`}`, detail: f.msg ?? undefined, tone: "bad" });
    else if (f.type === "complete") ev.push({ at: f.createdAt, kind: "order", title: `${f.product.toUpperCase()} order completed`, tone: "good" });
  }
  let paid = 0;
  let spent = 0;
  for (const w of wallet) {
    const real = w.amountCents > 0 && (w.stripeSessionId || w.stripePaymentIntentId);
    if (real) paid += w.amountCents;
    if (w.amountCents < 0 && !/^(Refund|Write-off|Admin balance|Affiliate|Reversed)/.test(w.description)) spent += -w.amountCents;
    ev.push({
      at: w.createdAt,
      kind: w.amountCents > 0 ? "payment" : "order",
      title: w.amountCents > 0 ? `${real ? "Paid" : "Credited"} $${(w.amountCents / 100).toFixed(2)}` : `Charged $${(-w.amountCents / 100).toFixed(2)}`,
      // Strip Stripe ids from descriptions — not secret, but noise here.
      detail: w.description.replace(/\((cs|pi)_[A-Za-z0-9_]+\)/g, "").slice(0, 140),
      tone: w.amountCents > 0 && real ? "good" : w.description.startsWith("Refund") ? "bad" : "neutral",
    });
  }
  for (const s of servers) {
    ev.push({ at: s.createdAt, kind: "provision", title: `Server ordered: ${s.gamePlan?.name ?? s.plan?.name ?? "server"}${s.isFree ? " (free)" : ""}`, detail: `${s.hostname} · now ${s.status}${s.provisionError ? ` · ${s.provisionError.slice(0, 120)}` : ""}`, tone: s.status === "ERROR" ? "bad" : "neutral" });
  }
  for (const a of archived) {
    ev.push({ at: a.deletedAt, kind: "provision", title: `Server removed: ${a.serviceName}`, detail: `${a.hostname} · ${a.reason}${a.totalSpentCents ? ` · lifetime spend $${(a.totalSpentCents / 100).toFixed(2)}` : ""}`, tone: "neutral" });
  }
  for (const j of jobs) {
    if (!j.finishedAt && j.status !== "FAILED") continue;
    ev.push({ at: j.finishedAt ?? j.createdAt, kind: "provision", title: `${j.type.toLowerCase()} ${j.status === "DONE" ? "finished" : "failed"} — ${j.hostname}`, detail: j.status === "DONE" ? `took ${Math.round(((j.finishedAt?.getTime() ?? j.createdAt.getTime()) - j.createdAt.getTime()) / 60_000)} min` : j.error ?? undefined, tone: j.status === "DONE" ? "good" : "bad" });
  }
  // Panel usage: group per day + category.
  const usage = new Map<string, { at: Date; cat: string; n: number }>();
  for (const a of audits) {
    const cat = usageCategory(a.action);
    if (!cat) {
      if (/^(card\.|billing\.|server\.cancel|user\.(password|2fa|google_link))/.test(a.action)) ev.push({ at: a.createdAt, kind: a.action.startsWith("billing.card_declined") ? "payment" : "account", title: a.action.replace(/[._]/g, " "), tone: /declin|unusable/.test(a.action) ? "bad" : "neutral" });
      continue;
    }
    const k = `${a.createdAt.toISOString().slice(0, 10)}|${cat}`;
    const e = usage.get(k) ?? { at: a.createdAt, cat, n: 0 };
    e.n++;
    usage.set(k, e);
  }
  for (const e of usage.values()) ev.push({ at: e.at, kind: "usage", title: `${e.cat}: ${e.n} action${e.n === 1 ? "" : "s"}` });
  for (const t of tickets) {
    ev.push({ at: t.createdAt, kind: "support", title: `Ticket opened: ${t.subject.slice(0, 100)}`, detail: `now ${t.status}`, tone: "neutral" });
    const firstStaff = t.messages.find((m) => m.isStaff);
    if (firstStaff) ev.push({ at: firstStaff.createdAt, kind: "support", title: `Staff replied (${Math.round((firstStaff.createdAt.getTime() - t.createdAt.getTime()) / 60_000)} min after opening)`, tone: "good" });
  }
  for (const c of chats) ev.push({ at: c.createdAt, kind: "support", title: `Live chat (${c._count.messages} messages)${c.botEscalatedAt ? " — handed to a human" : ""}` });
  for (const e of emails) {
    const t = (e.template ?? "email").split(":")[0];
    ev.push({ at: e.createdAt, kind: "email", title: `Email: ${t}${e.status === "FAILED" ? " — FAILED to send" : ""}`, detail: [e.openedAt ? "opened" : null, e.clickedAt ? "clicked" : null].filter(Boolean).join(", ") || undefined, tone: e.status === "FAILED" ? "bad" : "neutral" });
  }
  for (const c of coupons) ev.push({ at: c.createdAt, kind: "order", title: `Coupon ${c.coupon.code} (${c.state.toLowerCase()})`, detail: `$${(c.amountCents / 100).toFixed(2)} off` });
  if (activity)
    for (const a of activity) {
      // Activity rows duplicate visits/wizard steps already shown; keep payment + auth events.
      if (!/(payment|checkout|refund|dispute|renewal|dunning|login|logout|auth|verify|password)/i.test(a.kind)) continue;
      const code = typeof a.data.declineCode === "string" ? a.data.declineCode : typeof a.data.decline_code === "string" ? a.data.decline_code : null;
      const brand = typeof a.data.cardBrand === "string" ? a.data.cardBrand : typeof a.data.brand === "string" ? a.data.brand : null;
      ev.push({ at: a.at, kind: /pay|checkout|refund|dispute|renew|dunning/i.test(a.kind) ? "payment" : "account", title: a.kind.replace(/[._]/g, " "), detail: [code, brand].filter(Boolean).join(" · ") || undefined, tone: /fail|declin|cancel|dispute/i.test(a.kind) ? "bad" : /succe|paid/i.test(a.kind) ? "good" : "neutral" });
    }

  ev.sort((a, b) => a.at.getTime() - b.at.getTime());
  return {
    user: { id: u.id, email: u.email, name: u.name, createdAt: u.createdAt, method: u.googleId ? "Google" : "Email & password", verified: !!u.emailVerifiedAt, country: u.billingCountry, heardAboutUs: u.heardAboutUs, excluded: u.excludeFromRevenue, role: u.role },
    firstTouch,
    totals: { paidCents: paid, spentCents: spent, servers: servers.length + archived.length, tickets: tickets.length },
    events: ev.length > MAX_EVENTS ? ev.slice(ev.length - MAX_EVENTS) : ev,
    activityInstrumented: activity !== null,
  };
}

