"use server";

import { cookies } from "next/headers";
import { revalidatePath } from "next/cache";
import { requireArea } from "./rbac";
import { db } from "./db";
import { recordAudit } from "./audit";
import { INCLUDE_BOTS_COOKIE } from "./bots/scope";

/**
 * Admin "include bots" toggle for every visitor-analytics view (lib/bots/scope.ts).
 * A per-browser cookie (not a global setting) so one admin debugging a traffic
 * spike never changes what another admin's dashboards show. Expires after 12h
 * so nobody forgets it on and reads polluted numbers for a week.
 */
export async function setIncludeBots(on: boolean): Promise<{ ok: true }> {
  const admin = await requireArea("analytics");
  const jar = await cookies();
  if (on) {
    jar.set(INCLUDE_BOTS_COOKIE, "1", { httpOnly: true, sameSite: "lax", path: "/admin", maxAge: 12 * 3600 });
  } else {
    jar.delete({ name: INCLUDE_BOTS_COOKIE, path: "/admin" });
  }
  await recordAudit(admin.id, "analytics.include_bots", on ? "on" : "off");
  for (const p of ["/admin/visitors", "/admin/audience", "/admin/analytics", "/admin/insights"]) revalidatePath(p);
  return { ok: true };
}

/** Dismiss an insights alert (idempotent; a dismissed dedupeKey is never re-opened). */
export async function dismissInsightsAlert(id: string): Promise<{ ok?: true; error?: string }> {
  const admin = await requireArea("analytics");
  if (typeof id !== "string" || !/^[a-z0-9]{10,40}$/i.test(id)) return { error: "Bad id." };
  const r = await db.insightsAlert.updateMany({ where: { id, status: { not: "DISMISSED" } }, data: { status: "DISMISSED", resolvedAt: new Date() } });
  if (r.count > 0) await recordAudit(admin.id, "insights.alert_dismiss", id);
  revalidatePath("/admin/insights");
  return { ok: true };
}
