/**
 * The optional scheduled report digest (default OFF). Generated by the SAME
 * collector + engine as /admin/reports, stored as a ReportRun snapshot, and
 * emailed to the owner. Emails in the digest are never shown — findings carry
 * counts and links to the admin drill-downs instead.
 */
import { db } from "@/lib/db";
import { getSetting, getSettingBool, reportsEmail } from "@/lib/settings";
import { collectReport } from "./collect";
import { analyze } from "./engine";
import { parseReportRange, localYmd, addDaysYmd, isValidTimeZone } from "./range";
import { DOMAIN_LABELS, type ReportData, type ReportSummary } from "./types";

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** Pure: plain-text digest. */
export function digestText(d: ReportData, s: ReportSummary, baseUrl: string): string {
  const lines = [`Nxeon report — ${d.range.label} (${d.range.fromStr} → ${d.range.toStr}, ${d.range.tz})`, "", s.headline, ""];
  if (d.caveats.length) lines.push(...d.caveats.map((c) => `Note: ${c}`), "");
  if (!s.findings.length) lines.push("Nothing stood out: no change cleared the significance and minimum-sample checks, and no friction rule fired.");
  s.findings.forEach((f, i) => {
    lines.push(`${i + 1}. ${f.text}${f.confidence === "early" ? " (early signal)" : ""}`, `   Why it matters: ${f.why}`, `   Do: ${f.action}`);
    if (f.drill) lines.push(`   ${f.drill.href.startsWith("http") ? f.drill.href : `${baseUrl}${f.drill.href}`}`);
    lines.push("");
  });
  lines.push(`Full report: ${baseUrl}/admin/reports?${d.range.preset ? `preset=${d.range.preset}` : `from=${d.range.fromStr}&to=${d.range.toStr}`}`);
  return lines.join("\n");
}

/** Pure: HTML digest (simple, inline-styled, email-safe). */
export function digestHtml(d: ReportData, s: ReportSummary, baseUrl: string): string {
  const sev: Record<string, string> = { critical: "#ef4444", warning: "#f59e0b", info: "#3b82f6", positive: "#10b981" };
  const items = s.findings
    .map(
      (f) => `<tr><td style="padding:10px 0;border-top:1px solid #1e293b">
        <div style="font-size:12px;color:${sev[f.severity]};text-transform:uppercase;letter-spacing:.06em">${esc(f.severity)} · ${esc(DOMAIN_LABELS[f.domain])}${f.confidence === "early" ? " · early signal" : ""}</div>
        <div style="font-size:15px;color:#e2e8f0;margin:4px 0">${esc(f.text)}</div>
        <div style="font-size:13px;color:#94a3b8"><b>Why it matters:</b> ${esc(f.why)}</div>
        <div style="font-size:13px;color:#94a3b8"><b>Do:</b> ${esc(f.action)}</div>
        ${f.drill ? `<div style="font-size:13px;margin-top:4px"><a style="color:#8a70fb" href="${esc(f.drill.href.startsWith("http") ? f.drill.href : `${baseUrl}${f.drill.href}`)}">${esc(f.drill.label)} →</a></div>` : ""}
      </td></tr>`,
    )
    .join("");
  const full = `${baseUrl}/admin/reports?${d.range.preset ? `preset=${d.range.preset}` : `from=${d.range.fromStr}&to=${d.range.toStr}`}`;
  return `<div style="background:#060a14;padding:24px;font-family:Inter,Arial,sans-serif">
  <div style="max-width:640px;margin:0 auto;background:#0b1220;border:1px solid #1e293b;border-radius:14px;padding:24px">
    <div style="font-size:12px;color:#8a70fb;letter-spacing:.12em;text-transform:uppercase">Nxeon report · ${esc(d.range.label)}</div>
    <h1 style="font-size:18px;color:#fff;margin:8px 0 12px">${esc(s.headline)}</h1>
    ${d.caveats.map((c) => `<p style="font-size:12px;color:#fbbf24;margin:0 0 8px">${esc(c)}</p>`).join("")}
    <table style="width:100%;border-collapse:collapse">${items || `<tr><td style="color:#94a3b8;font-size:14px">Nothing stood out this period.</td></tr>`}</table>
    <p style="margin-top:16px"><a style="color:#22d3ee;font-size:14px" href="${esc(full)}">Open the full report →</a></p>
    <p style="font-size:11px;color:#64748b">Generated automatically from the database (no AI). Turn this off on the Reports page.</p>
  </div></div>`;
}

/** The period a digest covers: yesterday (daily) or the last full Mon–Sun week (weekly), in `tz`. */
export function digestPeriod(freq: "daily" | "weekly", tz: string, now: Date = new Date()): { from: string; to: string } {
  const today = localYmd(now, tz);
  if (freq === "daily") {
    const y = addDaysYmd(today, -1);
    return { from: y, to: y };
  }
  const dow = (new Date(`${today}T12:00:00Z`).getUTCDay() + 6) % 7; // 0 = Monday
  const lastMon = addDaysYmd(today, -dow - 7);
  return { from: lastMon, to: addDaysYmd(lastMon, 6) };
}

export async function generateReportRun(params: { from?: string; to?: string; preset?: string; tz?: string; compare?: string }, trigger: string) {
  const r = parseReportRange(params);
  const data = await collectReport(r, { fresh: true });
  const summary = analyze(data);
  const json = JSON.parse(JSON.stringify({ report: data, summary }));
  return db.reportRun.upsert({
    where: { trigger_periodFrom: { trigger, periodFrom: r.from } },
    update: { periodTo: r.to, label: r.label, headline: summary.headline, data: json, generatedAt: new Date() },
    create: { trigger, periodFrom: r.from, periodTo: r.to, label: r.label, headline: summary.headline, data: json },
  });
}

/** Worker sweep (hourly). Inert unless report_digest_enabled = true. One run + email per period. */
export async function reportDigestSweep(now: Date = new Date()): Promise<"disabled" | "waiting" | "sent" | "already" | "failed"> {
  if (!(await getSettingBool("report_digest_enabled", false))) return "disabled";
  const freq = (await getSetting("report_digest_frequency")) === "daily" ? "daily" : "weekly";
  const tzRaw = (await getSetting("report_digest_tz")) || "UTC";
  const tz = isValidTimeZone(tzRaw) ? tzRaw : "UTC";
  // Send after 06:00 local so late beacons and nightly rollups have landed.
  const hour = Number(new Intl.DateTimeFormat("en-US", { timeZone: tz, hour: "2-digit", hourCycle: "h23" }).format(now));
  if (hour < 6) return "waiting";
  const p = digestPeriod(freq, tz, now);
  const trigger = `digest-${freq}`;
  const r = parseReportRange({ from: p.from, to: p.to, tz }, now);
  const existing = await db.reportRun.findUnique({ where: { trigger_periodFrom: { trigger, periodFrom: r.from } } });
  if (existing?.emailedAt) return "already";
  const run = existing ?? (await generateReportRun({ from: p.from, to: p.to, tz }, trigger));
  const to = (await getSetting("report_digest_to")).trim() || (await reportsEmail());
  try {
    const { sendMail } = await import("@/lib/mailer");
    const { report, summary } = run.data as unknown as { report: ReportData; summary: ReportSummary };
    const base = (process.env.NXEON_ADMIN_HOST ? `https://${process.env.NXEON_ADMIN_HOST.replace(/^https?:\/\//, "")}` : process.env.APP_URL ?? "").replace(/\/$/, "");
    const ok = await sendMail({ to, subject: `Nxeon ${freq} report — ${report.range.label}: ${summary.findings[0]?.text.slice(0, 80) ?? "nothing stood out"}`, html: digestHtml(report, summary, base), text: digestText(report, summary, base), template: "report_digest" });
    if (!ok) return "failed";
    await db.reportRun.update({ where: { id: run.id }, data: { emailedAt: new Date() } });
    return "sent";
  } catch (e) {
    console.error("[reports] digest send failed", e);
    return "failed";
  }
}

