"use server";

import { revalidatePath } from "next/cache";
import { requireArea } from "./rbac";
import { db } from "./db";
import { recordAudit } from "./audit";
import { setSetting } from "./settings";
import { isValidTimeZone, parseReportRange, rangeQuery } from "./reports/range";
import { generateReportRun } from "./reports/digest";

/**
 * /admin/reports actions. Admin-only (requireArea("analytics") = ADMIN role);
 * the admin layout already refuses to render while impersonating.
 */

/** Normalise a view's query string through the range parser so only known params are stored. */
function cleanParams(params: string): string {
  const sp = Object.fromEntries(new URLSearchParams(params.slice(0, 500)));
  return rangeQuery(parseReportRange(sp));
}

export async function saveReportView(name: string, params: string): Promise<{ ok?: true; error?: string }> {
  const admin = await requireArea("analytics");
  const n = String(name ?? "").trim().slice(0, 60);
  if (!n) return { error: "Give the view a name." };
  const count = await db.reportView.count({ where: { ownerId: admin.id } });
  if (count >= 30) return { error: "You have 30 saved views — delete one first." };
  await db.reportView.create({ data: { ownerId: admin.id, name: n, params: cleanParams(String(params ?? "")) } });
  revalidatePath("/admin/reports");
  return { ok: true };
}

export async function deleteReportView(id: string): Promise<{ ok?: true; error?: string }> {
  const admin = await requireArea("analytics");
  if (typeof id !== "string" || !/^[a-z0-9]{10,40}$/i.test(id)) return { error: "Bad id." };
  await db.reportView.deleteMany({ where: { id, ownerId: admin.id } });
  revalidatePath("/admin/reports");
  return { ok: true };
}

export async function setReportDigest(input: { enabled: boolean; frequency: string; to: string; tz: string }): Promise<{ ok?: true; error?: string }> {
  const admin = await requireArea("analytics");
  const freq = input.frequency === "daily" ? "daily" : "weekly";
  const to = String(input.to ?? "").trim().slice(0, 200);
  if (to && !/^[^\s@,]+@[^\s@,]+\.[^\s@,]+$/.test(to)) return { error: "Enter one valid email address (or leave blank for the reports address)." };
  const tz = isValidTimeZone(input.tz) ? input.tz : "UTC";
  await setSetting("report_digest_enabled", input.enabled ? "true" : "false");
  await setSetting("report_digest_frequency", freq);
  await setSetting("report_digest_to", to);
  await setSetting("report_digest_tz", tz);
  await recordAudit(admin.id, "reports.digest_settings", `${input.enabled ? "on" : "off"} ${freq} ${tz}`);
  revalidatePath("/admin/reports");
  return { ok: true };
}

/** Freeze the current report as a ReportRun snapshot (re-readable later exactly as generated). */
export async function saveReportSnapshot(params: string): Promise<{ ok?: true; id?: string; error?: string }> {
  const admin = await requireArea("analytics");
  const sp = Object.fromEntries(new URLSearchParams(cleanParams(String(params ?? ""))));
  const run = await generateReportRun(sp, "manual");
  await recordAudit(admin.id, "reports.snapshot", run.id);
  revalidatePath("/admin/reports");
  return { ok: true, id: run.id };
}

