/**
 * Server-safe presentational pieces for /admin/reports (and its saved
 * snapshots). Built from the shared admin primitives + dependency-free SVG
 * charts; on brand (navy / violet / cyan, amber only as a warning colour).
 */
import Link from "next/link";
import { StatCard } from "@/components/ui/primitives";
import { AreaChart } from "@/components/ui/charts";
import { Bars, Table, axisLabels } from "@/app/admin/insights/_ui";
import { fmtValue } from "@/lib/reports/engine";
import { DOMAIN_LABELS, type Domain, type Finding, type Metric, type ReportData, type ReportSection, type ReportSummary } from "@/lib/reports/types";

const SEV: Record<Finding["severity"], { label: string; cls: string; dot: string }> = {
  critical: { label: "Critical", cls: "border-red-500/40 bg-red-500/[0.07] text-red-300", dot: "bg-red-400" },
  warning: { label: "Warning", cls: "border-amber-500/40 bg-amber-500/[0.07] text-amber-200", dot: "bg-amber-400" },
  info: { label: "Note", cls: "border-accent-blue/40 bg-accent-blue/[0.07] text-sky-200", dot: "bg-accent-cyan" },
  positive: { label: "Good news", cls: "border-emerald-500/40 bg-emerald-500/[0.07] text-emerald-200", dot: "bg-emerald-400" },
};

export function SeverityPill({ f }: { f: Finding }) {
  const s = SEV[f.severity];
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[11px] font-semibold uppercase tracking-wide ${s.cls}`}>
      <span className={`h-1.5 w-1.5 rounded-full ${s.dot}`} />
      {s.label}
    </span>
  );
}

export function FindingCard({ f, n }: { f: Finding; n?: number }) {
  return (
    <li className="report-finding rounded-xl border border-white/[0.07] bg-white/[0.02] p-4">
      <div className="mb-2 flex flex-wrap items-center gap-2 text-xs text-slate-400">
        {n != null && <span className="grid h-5 w-5 place-items-center rounded-full bg-brand-500/20 text-[11px] font-bold text-brand-200">{n}</span>}
        <SeverityPill f={f} />
        <span>{DOMAIN_LABELS[f.domain]}</span>
        {f.confidence === "early" ? (
          <span className="rounded border border-dashed border-white/20 px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-slate-400" title="Small sample — worth watching, not yet conclusive.">
            Early signal
          </span>
        ) : (
          <span className="text-[11px] text-slate-500">{f.confidence} confidence</span>
        )}
      </div>
      <p className="text-[15px] font-medium leading-snug text-slate-100">{f.text}</p>
      <p className="mt-2 text-sm text-slate-400">
        <span className="font-semibold text-slate-300">Why it matters: </span>
        {f.why}
      </p>
      <p className="mt-1 text-sm text-slate-400">
        <span className="font-semibold text-accent-cyan">Do: </span>
        {f.action}
      </p>
      {f.drill && (
        <Link href={f.drill.href} className="mt-2 inline-block text-sm font-medium text-brand-300 hover:text-brand-200 print:hidden">
          {f.drill.label} →
        </Link>
      )}
    </li>
  );
}

export function ExecutiveSummary({ s, d }: { s: ReportSummary; d: ReportData }) {
  return (
    <section className="card relative overflow-hidden" aria-labelledby="exec-summary">
      <div className="pointer-events-none absolute -right-24 -top-24 h-64 w-64 rounded-full bg-brand-500/10 blur-3xl print:hidden" />
      <p className="eyebrow">Executive summary</p>
      <h2 id="exec-summary" className="mt-2 text-lg font-semibold leading-snug text-white">
        {s.headline}
      </h2>
      <p className="mt-1 text-xs text-slate-500">
        {d.range.compare === "none" ? "Comparison off." : `Compared with ${d.range.prevLabel} (${d.range.prevDetail}).`} Generated {new Date(d.generatedAt).toISOString().slice(0, 16).replace("T", " ")} UTC from live data by rules, not AI.
      </p>
      {s.findings.length ? (
        <ol className="mt-4 space-y-3">
          {s.findings.map((f, i) => (
            <FindingCard key={f.id} f={f} n={i + 1} />
          ))}
        </ol>
      ) : (
        <p className="mt-4 rounded-lg border border-dashed border-white/10 px-3 py-4 text-sm text-slate-400">
          Nothing stood out: no metric moved enough to clear the significance and minimum-sample checks, and no friction rule fired.
        </p>
      )}
    </section>
  );
}

function deltaOf(m: Metric, compare: boolean): { text?: string; good?: boolean } {
  if (!compare || m.cur == null || m.prev == null) return { text: m.note };
  if (m.unit === "ratio") {
    const pts = Math.round((m.cur - m.prev) * 100);
    if (pts === 0) return { text: "flat vs previous" };
    return { text: `${pts > 0 ? "+" : ""}${pts} pts vs previous (${fmtValue(m.prev, "ratio")})`, good: pts > 0 === m.higherIsBetter };
  }
  if (m.prev === 0) return { text: m.cur === 0 ? "none before either" : `none before`, good: m.cur === 0 ? undefined : m.higherIsBetter };
  const r = (m.cur - m.prev) / Math.abs(m.prev);
  if (Math.abs(r) < 0.005) return { text: "flat vs previous" };
  return { text: `${r > 0 ? "+" : ""}${(r * 100).toFixed(Math.abs(r) < 0.1 ? 1 : 0)}% vs previous (${fmtValue(m.prev, m.unit)})`, good: r > 0 === m.higherIsBetter };
}

function Tile({ m, compare }: { m: Metric; compare: boolean }) {
  const d = deltaOf(m, compare);
  return <StatCard label={m.label} value={fmtValue(m.cur, m.unit)} delta={d.text} deltaGood={d.good} spark={m.spark && m.spark.some((x) => x) ? m.spark : undefined} />;
}

export function SectionBlock({ s, narrative, findings, d, exportBase }: { s: ReportSection; narrative?: string; findings: Finding[]; d: ReportData; exportBase?: string }) {
  const compare = d.range.compare !== "none";
  const fmt = (u?: string) => (u === "cents" ? (n: number) => fmtValue(n, "cents") : undefined);
  return (
    <section id={`s-${s.domain}`} className="card report-section scroll-mt-24" aria-labelledby={`h-${s.domain}`}>
      <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
        <h2 id={`h-${s.domain}`} className="text-base font-semibold text-white">
          {DOMAIN_LABELS[s.domain]}
        </h2>
        {findings.length > 0 && <span className="text-xs text-slate-500">{findings.length} finding{findings.length === 1 ? "" : "s"}</span>}
      </div>
      {narrative && <p className="mb-4 text-sm leading-relaxed text-slate-300">{narrative}</p>}
      {s.metrics.length > 0 && (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {s.metrics.map((m) => (
            <Tile key={m.key} m={m} compare={compare} />
          ))}
        </div>
      )}
      {findings.length > 0 && (
        <ul className="mt-4 space-y-3">
          {findings.map((f) => (
            <FindingCard key={f.id} f={f} />
          ))}
        </ul>
      )}
      {s.series?.map((x) =>
        x.values.some((v) => v) ? (
          <div key={x.key} className="mt-5">
            <p className="mb-2 text-xs font-medium uppercase tracking-wide text-slate-500">{x.title}</p>
            <AreaChart id={`rep-${x.key}`} series={[{ name: x.title, data: x.values, color: "#8a70fb" }]} height={160} xLabels={axisLabels(x.keys)} yLabel={x.unit === "cents" ? (v) => `$${Math.round(v / 100)}` : undefined} />
          </div>
        ) : null,
      )}
      {s.ranked.some((r) => r.rows.length) && (
        <div className="mt-5 grid grid-cols-1 gap-5 lg:grid-cols-2">
          {s.ranked
            .filter((r) => r.rows.length)
            .map((r) => (
              <div key={r.key}>
                <p className="mb-2 text-xs font-medium uppercase tracking-wide text-slate-500">{r.title}</p>
                <Bars rows={r.rows.map((x) => ({ label: x.label, value: x.value, hint: x.hint ?? (compare && x.prev != null ? `prev ${x.prev.toLocaleString("en-US")}` : undefined) }))} format={fmt(r.format)} />
              </div>
            ))}
        </div>
      )}
      {s.tables
        .filter((t) => t.rows.length)
        .map((t) => (
          <div key={t.key} className="mt-5">
            <div className="mb-2 flex items-center justify-between gap-2">
              <p className="text-xs font-medium uppercase tracking-wide text-slate-500">{t.title}</p>
              {exportBase && (
                <a className="text-xs text-brand-300 hover:text-brand-200 print:hidden" href={`${exportBase}&table=${s.domain}.${t.key}`} download>
                  CSV
                </a>
              )}
            </div>
            <Table head={t.head} rows={t.rows.map((r) => r.map((c) => (typeof c === "number" ? c.toLocaleString("en-US") : c)))} />
          </div>
        ))}
      {s.notes?.length ? (
        <ul className="mt-4 space-y-1 text-xs text-slate-500">
          {s.notes.map((n) => (
            <li key={n}>· {n}</li>
          ))}
        </ul>
      ) : null}
    </section>
  );
}

/** Render a whole report (live page and stored snapshots share this). */
export function ReportBody({ d, s, exportBase }: { d: ReportData; s: ReportSummary; exportBase?: string }) {
  const byDomain = new Map<Domain, Finding[]>();
