  for (const f of s.all) if (!inSummary.has(f.id)) byDomain.set(f.domain, [...(byDomain.get(f.domain) ?? []), f]);
  return (
    <div className="report-print-root space-y-6">
      {d.caveats.map((c) => (
        <p key={c} className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-200">
          {c}
        </p>
      ))}
      {d.failures.map((f) => (
        <p key={f.domain + f.message} className="rounded-lg border border-red-500/30 bg-red-500/[0.06] px-3 py-2 text-xs text-red-200">
          {DOMAIN_LABELS[f.domain]} could not be computed: {f.message}
        </p>
      ))}
      <ExecutiveSummary s={s} d={d} />
      <nav aria-label="Report sections" className="-mx-1 flex gap-1 overflow-x-auto px-1 pb-1 print:hidden">
        {d.sections.map((x) => (
