"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { saveReportView, deleteReportView, setReportDigest, saveReportSnapshot } from "@/lib/actions-reports";

const ZONES = ["UTC", "Asia/Singapore", "Asia/Manila", "Asia/Jakarta", "Asia/Kolkata", "Europe/London", "Europe/Berlin", "America/New_York", "America/Chicago", "America/Los_Angeles", "Australia/Sydney"];

/**
 * Time-frame picker. State lives in the URL (?preset= | ?from=&to=, &tz=, &compare=none)
 * so every view is a shareable link and the server renders it directly.
 */
export function RangeControls({ preset, fromStr, toStr, tz, compare, presets }: { preset: string | null; fromStr: string; toStr: string; tz: string; compare: "previous" | "none"; presets: { key: string; label: string }[] }) {
  const extra = (o: { tz?: string; compare?: string }) => {
    const q = new URLSearchParams();
    const z = o.tz ?? tz;
    const c = o.compare ?? compare;
    if (z !== "UTC") q.set("tz", z);
    if (c === "none") q.set("compare", "none");
    return q.toString();
  };
  const rangeQs = preset ? `preset=${preset}` : `from=${fromStr}&to=${toStr}`;
  const zones = ZONES.includes(tz) ? ZONES : [tz, ...ZONES];
  return (
    <div className="flex flex-col gap-3 print:hidden">
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex flex-wrap gap-1" role="group" aria-label="Time frame presets">
          {presets.map((p) => (
            <a
              key={p.key}
              href={`/admin/reports?preset=${p.key}${extra({}) ? `&${extra({})}` : ""}`}
              aria-current={preset === p.key ? "page" : undefined}
              className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition ${
                preset === p.key ? "border-brand-500/60 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-400 hover:border-white/20 hover:text-slate-200"
              }`}
            >
              {p.label}
            </a>
          ))}
        </div>
        <form action="/admin/reports" method="get" className="flex flex-wrap items-center gap-1.5 text-xs">
          <label className="sr-only" htmlFor="rep-from">From</label>
          <input id="rep-from" type="date" name="from" defaultValue={fromStr} className="input !h-8 !w-auto !px-2 !py-1 text-xs" />
          <span className="text-slate-500">→</span>
          <label className="sr-only" htmlFor="rep-to">To</label>
          <input id="rep-to" type="date" name="to" defaultValue={toStr} className="input !h-8 !w-auto !px-2 !py-1 text-xs" />
          {tz !== "UTC" && <input type="hidden" name="tz" value={tz} />}
          {compare === "none" && <input type="hidden" name="compare" value="none" />}
          <button type="submit" className="btn-secondary !h-8 !px-3 !py-1 text-xs">Apply</button>
        </form>
      </div>
      <div className="flex flex-wrap items-center gap-3 text-xs text-slate-400">
        <a
          href={`/admin/reports?${rangeQs}${extra({ compare: compare === "none" ? "previous" : "none" }) ? `&${extra({ compare: compare === "none" ? "previous" : "none" })}` : ""}`}
          aria-pressed={compare !== "none"}
          className={`inline-flex items-center gap-2 rounded-lg border px-2.5 py-1 font-medium transition ${compare !== "none" ? "border-accent-cyan/40 bg-accent-cyan/10 text-cyan-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`}
        >
          <span className={`h-2 w-2 rounded-full ${compare !== "none" ? "bg-accent-cyan" : "bg-slate-600"}`} />
          Compare to previous period
        </a>
        <label className="inline-flex items-center gap-1.5">
          Time zone
          <select
            className="input !h-8 !w-auto !px-2 !py-1 text-xs"
            value={tz}
            onChange={(e) => {
              const q = extra({ tz: e.target.value });
              window.location.href = `/admin/reports?${rangeQs}${q ? `&${q}` : ""}`;
            }}
          >
            {zones.map((z) => (
              <option key={z} value={z}>{z}</option>
            ))}
          </select>
        </label>
      </div>
    </div>
  );
}

export function ReportActions({ query, exportHref }: { query: string; exportHref: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  return (
    <div className="flex flex-wrap items-center gap-2 print:hidden">
      <button type="button" className="btn-secondary !h-8 !px-3 !py-1 text-xs" onClick={() => window.print()}>
        Print / PDF
      </button>
      <a className="btn-secondary !h-8 !px-3 !py-1 text-xs" href={exportHref} download>
        Findings CSV
      </a>
      <button
        type="button"
        disabled={pending}
        className="btn-secondary !h-8 !px-3 !py-1 text-xs"
        onClick={() =>
          start(async () => {
            const name = prompt("Name this view (time frame, compare and time zone are saved):");
            if (!name) return;
            const r = await saveReportView(name, query);
            setMsg(r.error ?? "View saved.");
            router.refresh();
          })
        }
      >
        Save view
      </button>
      <button
        type="button"
        disabled={pending}
        className="btn-secondary !h-8 !px-3 !py-1 text-xs"
        title="Freeze this report exactly as it is now, to re-read later."
        onClick={() =>
          start(async () => {
            const r = await saveReportSnapshot(query);
            setMsg(r.error ?? "Snapshot saved.");
            router.refresh();
          })
        }
      >
        {pending ? "Working…" : "Save snapshot"}
      </button>
      {msg && <span className="text-xs text-slate-400" role="status">{msg}</span>}
    </div>
  );
}

export function SavedViews({ views }: { views: { id: string; name: string; params: string }[] }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  if (!views.length) return null;
  return (
    <div className="flex flex-wrap items-center gap-1.5 text-xs print:hidden">
      <span className="text-slate-500">Saved views:</span>
      {views.map((v) => (
        <span key={v.id} className="inline-flex items-center gap-1 rounded-lg border border-white/10 py-0.5 pl-2.5 pr-1">
          <a href={`/admin/reports?${v.params}`} className="text-slate-300 hover:text-white">{v.name}</a>
          <button
            type="button"
            disabled={pending}
            aria-label={`Delete saved view ${v.name}`}
            className="rounded px-1 text-slate-500 hover:text-red-300"
            onClick={() =>
              start(async () => {
                if (!confirm(`Delete the saved view "${v.name}"?`)) return;
                await deleteReportView(v.id);
                router.refresh();
              })
            }
          >
            ×
          </button>
        </span>
      ))}
    </div>
  );
}

export function DigestSettings({ enabled, frequency, to, tz, fallbackTo }: { enabled: boolean; frequency: string; to: string; tz: string; fallbackTo: string }) {
