import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader } from "@/components/ui/primitives";
import { getSetting, getSettingBool, reportsEmail } from "@/lib/settings";
import { parseReportRange, rangeQuery, REPORT_PRESETS } from "@/lib/reports/range";
import { collectReport } from "@/lib/reports/collect";
import { analyze } from "@/lib/reports/engine";
import { ReportBody, PrintStyles } from "./_render";
import { RangeControls, ReportActions, SavedViews, DigestSettings } from "./Controls";

export const dynamic = "force-dynamic";

/**
 * /admin/reports — an automated analyst's report for any time frame: an
 * executive summary of the 5–8 findings that matter most, then every domain
 * (acquisition → signups → deploy funnel → revenue → payments → provisioning →
 * usage → retention → support → errors → fleet → email) with KPI tiles,
 * charts, tables and drill-downs. Deterministic: SQL aggregation
 * (lib/reports/collect*.ts) + a rule-based insight engine (lib/reports/engine.ts).
 * No LLM is called anywhere. Admin only.
 */
export default async function ReportsPage({ searchParams }: { searchParams: Promise<{ preset?: string; from?: string; to?: string; tz?: string; compare?: string }> }) {
  const admin = await requireArea("analytics");
  const sp = await searchParams;
  const range = parseReportRange(sp);
  const qs = rangeQuery(range);
  const [data, views, runs, digestOn, digestFreq, digestTo, digestTz, fallbackTo] = await Promise.all([
    collectReport(range),
    db.reportView.findMany({ where: { ownerId: admin.id }, orderBy: { createdAt: "asc" }, select: { id: true, name: true, params: true } }).catch(() => []),
    db.reportRun.findMany({ orderBy: { generatedAt: "desc" }, take: 8, select: { id: true, label: true, trigger: true, generatedAt: true, headline: true, emailedAt: true } }).catch(() => []),
    getSettingBool("report_digest_enabled", false),
    getSetting("report_digest_frequency"),
    getSetting("report_digest_to"),
    getSetting("report_digest_tz"),
    reportsEmail(),
  ]);
  const summary = analyze(data);
  const exportBase = `/admin/reports/export?${qs}`;

  return (
    <div className="space-y-6">
      <PrintStyles />
      <PageHeader title="Reports" sub={`${range.label} · ${range.fromStr} → ${range.toStr} (${range.tz})${range.partial ? " · period still running" : ""}`}>
        <ReportActions query={qs} exportHref={`${exportBase}&table=findings`} />
      </PageHeader>

      <div className="flex flex-col gap-3">
        <RangeControls preset={range.preset} fromStr={range.fromStr} toStr={range.toStr} tz={range.tz} compare={range.compare} presets={REPORT_PRESETS} />
        <SavedViews views={views} />
      </div>

      <ReportBody d={data} s={summary} exportBase={exportBase} />

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2 print:hidden">
        <section className="card">
          <h2 className="font-semibold">Scheduled digest</h2>
          <p className="mb-3 mt-0.5 text-xs text-slate-500">The same report, emailed to you on a schedule.</p>
          <DigestSettings enabled={digestOn} frequency={digestFreq} to={digestTo} tz={digestTz || "UTC"} fallbackTo={fallbackTo} />
        </section>
        <section className="card">
          <h2 className="font-semibold">Saved snapshots</h2>
          <p className="mb-3 mt-0.5 text-xs text-slate-500">Reports frozen exactly as generated (digests and &ldquo;Save snapshot&rdquo;).</p>
          {runs.length ? (
            <ul className="space-y-2 text-sm">
              {runs.map((r) => (
                <li key={r.id} className="flex flex-wrap items-baseline justify-between gap-2">
                  <Link href={`/admin/reports/runs/${r.id}`} className="text-brand-300 hover:text-brand-200">
                    {r.label}
                  </Link>
                  <span className="text-xs text-slate-500">
                    {r.trigger} · {r.generatedAt.toISOString().slice(0, 16).replace("T", " ")}
                    {r.emailedAt ? " · emailed" : ""}
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-sm text-slate-500">None yet.</p>
          )}
        </section>
      </div>

      <p className="text-xs text-slate-500 print:hidden">
        How this works: every number is a database query; a change is only reported when it clears a minimum sample and a significance test, and &ldquo;early signal&rdquo; marks findings on small samples. Rules and thresholds are listed on{" "}
        <Link className="text-brand-300 hover:text-brand-200" href="/admin/reports/rules">
          the rules page
        </Link>
        . Internal / QA accounts and bot traffic are excluded.
      </p>
    </div>
  );
}

