mkdir -p /tank/nxeon-wt-reports/app/admin/reports/{export,drill/\[kind\],journey/\[userId\],runs/\[id\],rules} && cat > /tank/nxeon-wt-reports/app/admin/reports/export/route.ts <<'EOF'
import { NextResponse } from "next/server";
import { requireArea } from "@/lib/rbac";
import { recordAudit } from "@/lib/audit";
import { toCsv } from "@/lib/insights/stats";
import { parseReportRange } from "@/lib/reports/range";
import { collectReport } from "@/lib/reports/collect";
import { analyze } from "@/lib/reports/engine";
import { drill, DRILL_KINDS } from "@/lib/reports/drill";
import { maskEmail } from "@/lib/reports/classify";
import { DOMAIN_LABELS } from "@/lib/reports/types";

export const dynamic = "force-dynamic";

/**
 * CSV export for /admin/reports. `table=findings` | `table=<domain>.<tableKey>` |
 * `drill=<kind>`. Customer emails are MASKED by default (j***@gmail.com); an
 * explicit `unmask=1` shows them and is audited. Admin-only.
 */
export async function GET(req: Request) {
  const admin = await requireArea("analytics");
  const url = new URL(req.url);
  const sp = Object.fromEntries(url.searchParams);
  const range = parseReportRange(sp);
  const unmask = url.searchParams.get("unmask") === "1";
  const table = url.searchParams.get("table") ?? "";
  const drillKind = url.searchParams.get("drill") ?? "";
  let rows: (string | number | null)[][] = [];
  let name = "report";

  if (drillKind && DRILL_KINDS[drillKind]) {
    const d = await drill(drillKind, range);
    if (d) {
      rows = [["Customer", ...d.head, "Journey"], ...d.rows.map((r) => [unmask ? r.email : maskEmail(r.email), r.when ? r.when.toISOString() : "", ...r.cols, r.userId ? `/admin/reports/journey/${r.userId}` : ""])];
      name = `drill-${drillKind}`;
    }
  } else {
    const data = await collectReport(range);
    if (table === "findings") {
      const s = analyze(data);
      rows = [["Rank", "Severity", "Confidence", "Area", "Finding", "Why it matters", "Suggested action", "Est. impact (USD)", "Drill-down"], ...s.all.map((f, i) => [i + 1, f.severity, f.confidence, DOMAIN_LABELS[f.domain], f.text, f.why, f.action, (f.impactCents / 100).toFixed(2), f.drill?.href ?? ""])];
      name = "findings";
    } else {
      const [domain, key] = table.split(".");
      const t = data.sections.find((s) => s.domain === domain)?.tables.find((x) => x.key === key);
      if (t) {
        rows = [t.head, ...t.rows];
        name = `${domain}-${key}`;
      }
    }
  }
  if (!rows.length) return NextResponse.json({ error: "Unknown table." }, { status: 404 });
  await recordAudit(admin.id, unmask ? "reports.export_unmasked" : "reports.export", `${name} ${range.fromStr}..${range.toStr}`);
  return new NextResponse(toCsv(rows), {
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="nxeon-report-${name}-${range.fromStr}_${range.toStr}.csv"`,
      "cache-control": "no-store",
    },
  });
