/**
 * Report aggregation SQL against a THROWAWAY Postgres (never the shared one).
 * Skipped unless REPORTS_TEST_DATABASE_URL is set, e.g.
 *   DATABASE_URL=postgresql://rep@127.0.0.1:54398/reptest npx prisma db push --skip-generate
 *   REPORTS_TEST_DATABASE_URL=postgresql://rep@127.0.0.1:54398/reptest npx tsx --test test/reports-collect-db.test.ts
 * WIPES the tables it seeds in that database.
 */
import test from "node:test";
import assert from "node:assert/strict";

const URL_ = process.env.REPORTS_TEST_DATABASE_URL;
const T = URL_ ? test : test.skip;
if (URL_) {
  if (/\/nxeon(\?|$)|nxeon_staging/.test(URL_)) throw new Error("refusing to run against a real database");
  process.env.DATABASE_URL = URL_;
}

const DAY = 86_400_000;
const today = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));
const ymd = (d: Date) => d.toISOString().slice(0, 10);
// Closed 7-day window ending yesterday, so nothing depends on the clock inside the period.
const FROM = new Date(today.getTime() - 7 * DAY);
const at = (dayOffset: number, hour = 12) => new Date(FROM.getTime() + dayOffset * DAY + hour * 3_600_000);

async function seed() {
  const { db } = await import("../lib/db");
  for (const t of ["DeployFunnelEvent", "Visit", "WalletTransaction", "Server", "ServerArchive", "FreeMinecraftServer", "AuditLog", "EmailLog", "ErrorDaily", "ErrorLog", "Ticket", "ChatConversation", "Job", "User", "Plan", "OsTemplate", "Setting"])
    await db.$executeRawUnsafe(`TRUNCATE "${t}" CASCADE`);
  const plan = await db.plan.create({ data: { slug: "std", name: "Standard VPS", cpuCores: 2, ramMB: 4096, diskGB: 80, bandwidthTB: 2, priceCents: 1299 } });
  const os = await db.osTemplate.create({ data: { name: "Ubuntu", vmid: 9000, family: "ubuntu" } as never });
  const mk = (email: string, created: Date, extra: Record<string, unknown> = {}) =>
    db.user.create({ data: { email, name: email.split("@")[0], passwordHash: "x", createdAt: created, ...extra } as never });
  // 6 real signups in the window, 1 before it, 2 internal (excluded by suffix), 1 flagged.
  const a = await mk("alice@gmail.com", at(0), { googleId: "g1", emailVerifiedAt: at(0) });
  const b = await mk("bob@gmail.com", at(1)); // email signup, never verified
  const c = await mk("carol@gmail.com", at(2), { emailVerifiedAt: at(2) });
  const d = await mk("dave@gmail.com", at(3));
  const e = await mk("erin@gmail.com", at(4), { googleId: "g2", emailVerifiedAt: at(4) });
  const late = await mk("late@gmail.com", new Date(FROM.getTime() + 6 * DAY + 23.5 * 3_600_000), { googleId: "g3" }); // 23:30 UTC on the last day
  await mk("old@gmail.com", new Date(FROM.getTime() - 3 * DAY));
  const qa = await mk("qa-sweep-1@nxeon-internal.test", at(1));
  await mk("admin@nxeon.local", at(1));
  await mk("owner-test@gmail.com", at(1), { excludeFromRevenue: true });

  // Visits: alice + bob landed from ChatGPT on /free-vps, carol from Google on /minecraft.
  const visit = (userId: string | null, vid: string, sid: string, path: string, referrer: string | null, when: Date, device = "Desktop", isEntry = true) =>
    db.visit.create({ data: { ip: `10.0.0.${Math.floor(Math.random() * 200)}`, path, referrer, userId, visitorId: vid, sessionId: sid, isEntry, deviceType: device, country: "US", createdAt: when, botKind: "human" } });
  await visit(null, "va", "sa1", "/free-vps?utm=x", "https://chatgpt.com/", new Date(at(0).getTime() - 3_600_000));
  await visit(a.id, "va", "sa2", "/dashboard", null, at(0, 13), "Desktop", false);
  await visit(null, "vb", "sb1", "/free-vps", "https://chatgpt.com/", new Date(at(1).getTime() - 600_000), "Mobile");
  await visit(b.id, "vb", "sb2", "/dashboard/deploy", null, at(1, 13), "Mobile", false);
  await visit(c.id, "vc", "sc1", "/minecraft-server-hosting", "https://www.google.com/", at(2, 11));
  await db.visit.create({ data: { ip: "66.249.66.1", path: "/", isEntry: true, isBot: true, botKind: "verified-crawler", createdAt: at(2) } });

  // Wizard: alice and carol reach Payment; carol orders (server-side complete has no session id). Bob stops at Plan. QA reaches payment too.
  const ev = (userId: string | null, sid: string | null, step: string, idx: number, type = "step", when = at(2, 14), extra: Record<string, unknown> = {}) =>
    db.deployFunnelEvent.create({ data: { userId, sessionId: sid, product: "game", step, stepIndex: idx, type, createdAt: when, ...extra } as never });
  for (const [u, sid] of [[a.id, "sa2"], [b.id, "sb2"], [c.id, "sc1"], [qa.id, "sq"]] as const) await ev(u, sid, "Game", 0);
  for (const [u, sid] of [[a.id, "sa2"], [c.id, "sc1"], [qa.id, "sq"]] as const) await ev(u, sid, "Plan", 1);
  for (const [u, sid] of [[a.id, "sa2"], [c.id, "sc1"], [qa.id, "sq"]] as const) await ev(u, sid, "Payment", 4);
  await ev(c.id, null, "Complete", 5, "complete");
  await ev(d.id, null, "Provision", 9, "error", at(3, 15), { errorCode: "PROVISION_FAILED", errorMessage: "game port 2456/udp never opened", detail: JSON.stringify({ game: "valheim" }) });
  await ev(qa.id, null, "Provision", 9, "error", at(3, 15), { errorCode: "PROVISION_FAILED", errorMessage: "qa noise" });

  // Money: carol's order ($12.99 new), dave renews ($9.99), a refund, QA's $0 order, an excluded account's order.
  const w = (userId: string, cents: number, description: string, when: Date, extra: Record<string, unknown> = {}) => db.walletTransaction.create({ data: { userId, amountCents: cents, description, createdAt: when, ...extra } });
  await w(c.id, 1299, "Stripe payment", at(2, 14), { stripeSessionId: "cs_1" });
  await w(c.id, -1299, "Game server: Valheim — 4 GB / 10 players (val)", at(2, 14));
  await w(d.id, -999, "Renewal: Standard VPS (web)", at(3));
  await w(d.id, -500, "Refund — downtime", at(4));
  const owner = await db.user.findFirstOrThrow({ where: { email: "owner-test@gmail.com" } });
  await w(owner.id, -5000, "Order: Pro VPS — Monthly", at(1));
  await db.server.create({ data: { name: "val", hostname: "val-1", userId: c.id, planId: plan.id, osTemplateId: os.id, isFree: false, status: "RUNNING", createdAt: at(2, 14) } });
  await db.server.create({ data: { name: "stuck", hostname: "stuck-1", userId: d.id, planId: plan.id, osTemplateId: os.id, isFree: false, status: "RUNNING", provisioningStep: "Installing the game…", createdAt: at(3), updatedAt: at(3) } as never });
  await db.emailLog.createMany({ data: [
    { toEmail: "x@y.z", subject: "v", template: "email_verify", html: "", status: "SENT", createdAt: at(1) },
    ...Array.from({ length: 12 }, (_, i) => ({ toEmail: "x@y.z", subject: "r", template: "ticket_reply", html: "", status: i < 4 ? "FAILED" : "SENT", createdAt: at(2) })),
  ] });
  await db.errorLog.create({ data: { context: "actions-order.placeOrder", source: "action", message: "boom", fingerprint: "fp1", count: 9, firstSeen: at(1), lastSeen: at(2) } });
  await db.$executeRaw`INSERT INTO "ErrorDaily" (id, date, fingerprint, context, source, level, count) VALUES ('ed1', ${new Date(FROM.getTime() + DAY)}, 'fp1', 'actions-order.placeOrder', 'action', 'error', 7)`;
  return { db, ids: { a: a.id, b: b.id, c: c.id, d: d.id, late: late.id } };
}

T("collectReport: real customers only, funnel matched by user, money, errors, friction", async () => {
  const { db, ids } = await seed();
  const { parseReportRange } = await import("../lib/reports/range");
  const { collectReport } = await import("../lib/reports/collect");
  const { analyze } = await import("../lib/reports/engine");
  const r = parseReportRange({ from: ymd(FROM), to: ymd(new Date(today.getTime() - DAY)) });
  const d = await collectReport(r, { fresh: true });
  assert.deepEqual(d.failures, [], JSON.stringify(d.failures));
  const m = (k: string) => d.sections.flatMap((s) => s.metrics).find((x) => x.key === k)!;

  assert.equal(m("signups").cur, 6, "6 real signups; internal suffixes, flagged account and pre-window signup excluded");
  assert.equal(d.friction.verification.eligible, 2, "bob + dave are email signups older than 24h");
  assert.equal(d.friction.verification.unverified, 2);
  assert.equal(d.friction.internalUnflagged, 2, "the two internal-suffix accounts are reported as unflagged");

  const game = d.friction.funnels.find((f) => f.product === "game")!;
  assert.equal(game.paymentReached, 2, "QA's payment session is excluded");
  assert.equal(game.paymentLeft, 1, "carol's session-less complete still counts her Payment session as ordered");
  assert.deepEqual(game.paymentLeftUserIds, [ids.a]);

  assert.equal(m("earned").cur, 1299 + 999, "excluded account and refund are not revenue");
  assert.equal(m("new_orders").cur, 1);
  assert.equal(m("renewal_revenue").cur, 999);
  assert.equal(m("refunds").cur, 500);
  assert.equal(m("cash_in").cur, 1299);

  assert.equal(d.friction.provisionByGame.find((g) => g.key === "valheim")?.failed, 1, "QA failure excluded, game read from event detail");
  assert.equal(d.friction.staleProvisioning, 1);
  assert.equal(m("error_events").cur, 7, "period counts come from ErrorDaily, not the lifetime ErrorLog.count");
  assert.equal(m("money_path_errors").cur, 7);
  const tr = d.friction.emailFailures.find((x) => x.key === "ticket_reply")!;
  assert.equal(tr.failed, 4);
  assert.equal(tr.total, 12);

  const ch = d.sections.find((s) => s.domain === "signups")!.tables.find((t) => t.key === "seg_Channel")!;
  const chat = ch.rows.find((x) => x[0] === "ChatGPT");
  assert.ok(chat && chat[1] === 2, "alice + bob first-touched from ChatGPT via their visitor cookie");
  assert.equal(m("visitors").cur, 3, "the crawler visit is excluded");

  const s = analyze(d);
  assert.ok(s.all.some((f) => f.rule === "stale_provisioning"));
  assert.ok(s.all.some((f) => f.rule === "internal_accounts"));
  assert.ok(s.headline.includes("$22.98"));
  void db;
});

T("time zone moves a 23:30 UTC signup into the next local day", async () => {
  const { parseReportRange } = await import("../lib/reports/range");
  const { collectReport } = await import("../lib/reports/collect");
  const last = ymd(new Date(today.getTime() - DAY));
  const utc = await collectReport(parseReportRange({ from: last, to: last }), { fresh: true });
  const sgt = await collectReport(parseReportRange({ from: last, to: last, tz: "Asia/Singapore" }), { fresh: true });
  const n = (x: typeof utc) => x.sections.flatMap((s) => s.metrics).find((mm) => mm.key === "signups")!.cur;
  assert.equal(n(utc), 1, "in UTC the 23:30 signup is on the last day");
  // In SGT the last local day runs 16:00 UTC (day before) → 16:00 UTC, so 23:30 UTC belongs to the following local day.
  assert.equal(n(sgt), 0);
});

