import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { AREA_ROLES, areaForHref, canAccess } from "../lib/rbac.ts";

const ROOT = path.join(import.meta.dirname, "..");

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((f) => {
    const p = path.join(dir, f);
    return statSync(p).isDirectory() ? files(p) : [p];
  });
}

test("/admin/reports is an ADMIN-only area (no SUPPORT / BILLING / EMPLOYEE)", () => {
  assert.equal(areaForHref("/admin/reports"), "analytics");
  assert.deepEqual(AREA_ROLES.analytics, ["ADMIN"]);
  assert.equal(canAccess("ADMIN", "analytics"), true);
  for (const r of ["SUPPORT", "BILLING", "EMPLOYEE", "CUSTOMER"] as const) assert.equal(canAccess(r as never, "analytics"), false, r);
});

test("every reports page and route guards itself with requireArea('analytics')", () => {
  const dir = path.join(ROOT, "app/admin/reports");
  const entry = files(dir).filter((f) => /(page\.tsx|route\.ts)$/.test(f));
  assert.ok(entry.length >= 6, `found ${entry.length}`);
  for (const f of entry) assert.match(readFileSync(f, "utf8"), /await requireArea\("analytics"\)/, path.relative(ROOT, f));
});

test("every server action in lib/actions-reports.ts is guarded", () => {
  const src = readFileSync(path.join(ROOT, "lib/actions-reports.ts"), "utf8");
  const fns = [...src.matchAll(/export async function (\w+)\([^)]*\)[^{]*\{([\s\S]*?)\n\}/g)];
  assert.ok(fns.length >= 4);
  for (const [, name, body] of fns) assert.match(body, /await requireArea\("analytics"\)/, name);
});

test("exports mask emails unless explicitly unmasked, and unmasking is audited", () => {
  const src = readFileSync(path.join(ROOT, "app/admin/reports/export/route.ts"), "utf8");
  assert.match(src, /unmask \? r\.email : maskEmail\(r\.email\)/);
  assert.match(src, /reports\.export_unmasked/);
});

test("no report code calls an LLM or writes customer card numbers", () => {
  for (const f of [...files(path.join(ROOT, "lib/reports")), ...files(path.join(ROOT, "app/admin/reports"))]) {
    const src = readFileSync(f, "utf8");
    assert.doesNotMatch(src, /@anthropic-ai|openai|claude-|messages\.create/i, path.relative(ROOT, f));
    assert.doesNotMatch(src, /last4|cardLast4|cardExp/, path.relative(ROOT, f));
  }
});

