// Scratch screenshot driver (not committed). Usage: node .scratch-pw.mjs <token>
import { chromium } from "playwright";
const token = process.argv[2];
const out = "/root/agent-notes/admin-reports";
const base = "http://localhost:3131";
const shots = [
  ["reports-7d", "/admin/reports?preset=7d"],
  ["reports-30d-sgt", "/admin/reports?preset=30d&tz=Asia%2FSingapore"],
  ["reports-today", "/admin/reports?preset=today"],
  ["reports-nocompare", "/admin/reports?preset=30d&compare=none"],
  ["drill-payment-leavers", "/admin/reports/drill/payment_leavers?preset=30d"],
  ["drill-unverified", "/admin/reports/drill/unverified?preset=30d"],
  ["rules", "/admin/reports/rules"],
];
const browser = await chromium.launch();
for (const [w, h, tag] of [[1440, 900, "desktop"], [390, 844, "mobile"]]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h } });
  await ctx.addCookies([{ name: "nxrep_session", value: token, domain: "localhost", path: "/" }]);
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  for (const [name, path] of shots) {
    const r = await page.goto(base + path, { waitUntil: "networkidle", timeout: 120000 });
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${out}/${name}.${tag}.png`, fullPage: true });
    const sw = await page.evaluate(() => document.documentElement.scrollWidth);
    console.log(tag, name, r?.status(), "scrollWidth", sw, page.url());
  }
  // journey of first leaver
  await page.goto(base + "/admin/reports/drill/payment_leavers?preset=30d", { waitUntil: "networkidle" });
  const href = await page.locator('a[href^="/admin/reports/journey/"]').first().getAttribute("href").catch(() => null);
  if (href) {
    const r = await page.goto(base + href + "?show=all", { waitUntil: "networkidle" });
    await page.screenshot({ path: `${out}/journey.${tag}.png`, fullPage: true });
    console.log(tag, "journey", r?.status());
  }
  if (tag === "desktop") {
    await page.goto(base + "/admin/reports?preset=7d", { waitUntil: "networkidle" });
    await page.emulateMedia({ media: "print" });
    await page.pdf({ path: `${out}/reports-7d-print.pdf`, format: "A4", printBackground: true }).catch((e) => console.log("pdf", String(e).slice(0, 100)));
    await page.emulateMedia({ media: "screen" });
    const csv = await page.request.get(base + "/admin/reports/export?preset=30d&drill=payment_leavers");
    console.log("csv", csv.status(), (await csv.text()).split("\n").slice(0, 3).join(" | "));
    const f = await page.request.get(base + "/admin/reports/export?preset=7d&table=findings");
    console.log("findings csv", f.status(), (await f.text()).split("\n").length, "lines");
  }
  console.log(tag, "page errors:", errors.slice(0, 5));
  await ctx.close();
}
// RBAC: no cookie → redirected to /login
const anon = await browser.newContext();
const p = await anon.newPage();
const r = await p.goto(base + "/admin/reports", { waitUntil: "domcontentloaded" });
console.log("anon", r?.status(), p.url());
const ex = await p.request.get(base + "/admin/reports/export?preset=7d&table=findings", { maxRedirects: 0 });
console.log("anon export", ex.status(), ex.headers()["location"]);
await browser.close();
EOF
