cat > /tank/nxeon-wt-reports/test/reports-digest.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { digestPeriod, digestText, digestHtml } from "../lib/reports/digest.ts";
import { analyze } from "../lib/reports/engine.ts";
import type { ReportData } from "../lib/reports/types.ts";

test("digest periods: yesterday / last full Mon–Sun week, in the owner's zone", () => {
  // Tue 2026-10-06 03:00 UTC = Tue 11:00 in Singapore, Mon 23:00 in New York.
  const now = new Date("2026-10-06T03:00:00Z");
  assert.deepEqual(digestPeriod("daily", "UTC", now), { from: "2026-10-05", to: "2026-10-05" });
  assert.deepEqual(digestPeriod("daily", "America/New_York", now), { from: "2026-10-04", to: "2026-10-04" });
  assert.deepEqual(digestPeriod("weekly", "Asia/Singapore", now), { from: "2026-09-28", to: "2026-10-04" });
  assert.deepEqual(digestPeriod("weekly", "UTC", new Date("2026-10-05T12:00:00Z")), { from: "2026-09-28", to: "2026-10-04" }, "on a Monday, the week just ended");
});

test("digest text/html contain findings but never customer emails, and escape HTML", () => {
  const d: ReportData = {
    generatedAt: "x",
    range: { from: "", to: "", prevFrom: "", prevTo: "", fromStr: "2026-09-28", toStr: "2026-10-04", label: "Sep 28 – Oct 4", prevLabel: "the previous 7 days", prevDetail: "", days: 7, partial: false, tz: "UTC", compare: "previous", preset: null },
    avgOrderCents: 1000,
    arpuCents: 1000,
    sections: [],
    friction: { staleProvisioning: 2, orderErrors: [{ product: "hosting", message: "<script>x</script> Enter a valid domain", count: 3 }] } as never,
    caveats: [],
    failures: [],
  };
  // Fill the rest of friction with empties via analyze's tolerance of missing fields.
  const f = d.friction as unknown as Record<string, unknown>;
  for (const k of ["declinesByCountry", "declineReasons", "provisionByGame", "provisionByNode", "emailFailures", "newErrorTypes", "winback", "capacity", "capacityRefusals", "segments", "paymentByCountry", "deviceSteps", "funnels", "devices"]) f[k] ??= [];
  const s = analyze(d);
  const text = digestText(d, s, "https://admin.example");
  const html = digestHtml(d, s, "https://admin.example");
  assert.match(text, /running servers still show an install step/i);
  assert.doesNotMatch(html, /<script>x/);
  assert.match(html, /&lt;script&gt;/);
  assert.doesNotMatch(text + html, /@gmail|@mailbox/);
  assert.match(text, /https:\/\/admin\.example\/admin\/reports\?from=2026-09-28&to=2026-10-04/);
});
EOF
